/* 令和5年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r05.committeeSessions.push(...[{"id":"r05-20230111-10","meetingId":"r05-cm01","date":"2023年1月11日","dateIso":"2023-01-11","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時３４分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を17件整理しています。","topics":[{"id":"topic-01","title":"令和４年第４回定例会","agenda":"令和４年第４回定例会","exchanges":[{"speaker":"石田委員","kind":"質問","question":"１点だけ伺いたいのですが、補正予算と区長給与の条例について、なぜ最終本会議というタイミングで出されるのか、理由を伺いたいと思います。","respondent":"森澤区長","answer":"本来は初日に行わせていただきたかったのですが、いろいろ文言の整理等が必要だったため、最終日となりました。どうぞご理解のほどよろしくお願いいたします。","id":"exchange-001"}]},{"id":"topic-02","title":"議員提出第５号議案、品川区議会個人情報の保護に関する条例","agenda":"議員提出第５号議案、品川区議会個人情報の保護に関する条例","exchanges":[{"speaker":"石田委員","kind":"確認","question":"区議会のほうでも仮名加工情報は扱うことはないし、これを利用するとなった場合は条例改正など、何か手続が必要になってくるのか伺いたいと思います。想定もし難いとご説明いただいていますけれども、これからも作る考えはないということでいいのか、確認させてください。","respondent":"工藤区議会事務局長","answer":"条例改正が必要だということを執行機関側から聞いておりますので、区議会としても、それと同じような扱いになると考えているところです。","id":"exchange-002"},{"speaker":"田中委員","kind":"確認","question":"これまでの議論を議事録などで確認してきました。最終的な確認をしたいのですけれども、住民側のリスクはないということでいいですかという確認をしたいのと、別表の第３０条関係の金額の部分で。","respondent":"工藤区議会事務局長","answer":"社会全体のデジタル化に対応するため、区議会の中でも条例をもって定めることで、個人情報の保護は十分に確保されると考えているところです。白黒の写しは１０円、カラーが５０円ということで考えているというお話ですので、規程の中で詳細な金額を定めてまいるです。","id":"exchange-003"},{"speaker":"田中委員","kind":"質問","question":"金額の部分、現在の品川区の情報公開の規定だと、カラーに関して、白黒以外のものによっては７０円という金額だったのですけれども、それよりも下がると考えていいのかというところを伺わせてください。","respondent":"工藤区議会事務局長","answer":"委員おっしゃるとおり、現在７０円ということが、今回５０円になるです。下がるです。","id":"exchange-004"},{"speaker":"田中委員","kind":"確認","question":"確認ができました。この１０円とかの金額も下がっていくのかなというところが気になってしまうので、確認をしたいのですけれども、そのときには条例改正になるのか尋ねました。","respondent":"工藤区議会事務局長","answer":"現状の中では、この金額で行ってまいるです。今お答えできませんけれども、その中で執行機関側が金額を変更するということであれば、区議会でも変更はあり得るということになっております。","id":"exchange-005"},{"speaker":"田中委員","kind":"質問・要望","question":"最後、要望で。そのときの状態に合わせて、議会や区のほうが高かったらあれかなと思うので、そのときに合わせて下げてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"石田委員","kind":"確認","question":"先ほど述べたとおり、個人情報保護の規定がないということになってしまいますので、個人情報をしっかり保護する条例をつくることは必要だと考えます。仮名加工情報も匿名加工情報も利用する考えはないということ、個人情報ファイルも作る想定はしていないということを確認しましたので、賛成します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"}]},{"id":"topic-03","title":"令和４年陳情第５６号、行政及び議会が宗教によって「政治的な差別」を行わないことを求める陳情","agenda":"令和４年陳情第５６号、行政及び議会が宗教によって「政治的な差別」を行わないことを求める陳情","exchanges":[{"speaker":"湯澤委員","kind":"意見","question":"大変悔やまれる事件で、どんな理由や背景があっても、絶対に許されない行為だとは思っております。十分留意して検討すべき内容だと考えておりますが、調査をしないという結論を区議会として一律に決めることは、適切ではないと考えるものでありますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"あくつ委員","kind":"質問","question":"ですから、この新法に関しても、今後は適正に運用されているかを注視して改善をしていくということは、国会で決まっているところです。憲法第２０条、逆に宗教に対する関与になる可能性もあるということで、なかなか願意には沿い難いのかなというのが私どもの考えです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"石田委員","kind":"質問","question":"陳情項目の１つ目の、反社会的集団との絶縁宣言をするというのは、むしろすべきだと思っています。私は、品川区議会としても宣言や決議をすべきだと考えていますが、ここにいらっしゃる会派の皆さんのご意見が伺えたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"田中委員","kind":"意見","question":"陳情項目の３に、様々な立場の人たちを巻き込んだ、広くかつ慎重な議論が必要だと考えています。権力者が決めてしまうというのは、過去の戦前・戦中の日本の行為、過ちを見ても明らかだと思うので、広く慎重な議論が必要だと考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"田中委員","kind":"質問","question":"本日結論を出すで、不採択です。先ほど１点言い忘れてしまったのですけれども、陳情項目２にある「調査・質問をしないこと」というのは、不採択を主張します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"}]},{"id":"topic-04","title":"令和５年第１回定例会","agenda":"令和５年第１回定例会","exchanges":[{"speaker":"石田委員","kind":"質問・要望","question":"これを２日間に分けて審議を行えないかといったことを、議会改革推進会議等で検討していただきたいと要望はしてきたのですけれども、検討はどのような状況か伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"石田委員","kind":"質問・要望","question":"直ちには難しいということで、以前から要望をしてきていることでして、しかるべき場で今後の議論はということでご説明がありましたので、ぜひ引き続き、ご議論・ご検討ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"田中委員","kind":"質問・要望","question":"ネットも今の石田委員と同じように、２日に分けてということを思っていたので、直ちには難しいということは理解したので、前向きに議論していただければと強く要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"}]},{"id":"topic-05","title":"議長会等の報告等","agenda":"議長会等の報告等","exchanges":[{"speaker":"石田委員","kind":"確認","question":"最後の、議員のコロナ感染状況の確認の変更のところで、国のコロナの対応が様々変わる中、区議会での対応も変わっていくのだろうなと感じました。減っていくのか、しかるべき時期に制限を今までどおりに戻すという検討をする必要があると思いますので、お願いしたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"あくつ委員","kind":"質問","question":"今後はホームページでの掲載、各議員への通知は行わないということは理解できたのですけれども、会議等への欠席の場合は連絡するようにと。感染の事実自体、陽性の事実自体は、もう報告をしなくていいということなのか尋ねました。","respondent":"本多議長","answer":"感染が分かったことの事実だけは、事務局にお知らせをいただければと思います。","id":"exchange-017"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/881920?Template=document&Id=5492#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":19079,"voices":94}},{"id":"r05-20230112-7","meetingId":"r05-cm01","date":"2023年1月12日","dateIso":"2023-01-12","committee":"厚生委員会","time":"午後 １時４１分～午後 ２時２５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を16件整理しています。","topics":[{"id":"topic-01","title":"第１１９号議案、令和４年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"第１１９号議案、令和４年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"石田委員","kind":"質問","question":"私たちも一般質問等で取り上げてきているのですが、国が少し増額して、５０万円が一時金として出るわけです。それで今回、品川区が行う事業によって、実質、出産費用が無償化するということで考えられているのか、そういう考えなのか伺いたいと思います。","respondent":"若生健康課長","answer":"そちらについての予算として１２月に成立して、市区町村で実施の運びになるというような流れですので、子育ても含めた全体的な支援ということになってあります。","id":"exchange-001"},{"speaker":"石田委員","kind":"質問","question":"妊娠して、そして出産するまででも、本当にお金がかかることなので、安心して出産できるというところでは、すごくよかったなと思っているのですが、これは一時的な事業なのか、それともずっと続く事業なのか、そこを伺いたいと思います。","respondent":"若生健康課長","answer":"国の説明では、これは継続的に令和５年度以降も実施していく予定だということを聞いておりまして、来年度も見据えて事業の組み立てをしていきたいと考えております。","id":"exchange-002"},{"speaker":"石田委員","kind":"質問・要望","question":"本当に少子化が深刻化している中で、こうした応援対策をさらに充実させてほしいと求めましたし、国にも求めていってほしいと求めました。１人合わせて１０万円ということなのだろうかと思うのですが、この５万円と１０万円というのがあるのは何なのか、説明を求めました。","respondent":"若生健康課長","answer":"先ほどの説明で触れさせていただいた遡及適用分、ほぼ遡及分になるということを見込んでおりますので、本格実施の段階では５万円を支給するという形になるのですけれども。","id":"exchange-003"},{"speaker":"石田委員","kind":"質問","question":"分かりました。それから、出産された方が１００％応援ギフトを知って、それで申請する方は申請するということになるのか伺いたいと思います。","respondent":"若生健康課長","answer":"２回目の部分、より妊娠期や出産に向けての寄り添った形での相談支援というところが充実してくるかなというところで考えているところです。それから２点目の、経済的支援の部分につきましては、ご説明させていただいた面談の実施というところを一つの要件としています。","id":"exchange-004"},{"speaker":"石田委員","kind":"質問・要望","question":"漏れのないようにというか、もらえない方がいないようにというのは、こういった応援給付金等では重々慎重にやってほしいと求めました。若い方なので、まれにいたりもするので、こうしたツールがない方がいた場合はどうするのか尋ねました。","respondent":"柏木品川区保健所品川保健センター所長","answer":"電子クーポンが使えない方の対応ですが、電子クーポンで対応できない方については、その対応がされるのではないかと考えております。","id":"exchange-005"},{"speaker":"いながき委員","kind":"意見","question":"面談に関してお尋ねしたいのですけれども、２回目を新しくつくるということなのですが、まずお尋ねしますとの意見を述べました。","respondent":"柏木品川区保健所品川保健センター所長","answer":"１つ目、面談が平日だけかということですけれども、現在のところ、平日のみで考えてあります。オンラインでも可能ということになっておりますので、必ずしも直接会ってということではないですけれども、面談は必須です。","id":"exchange-006"},{"speaker":"いながき委員","kind":"質問","question":"それと、もし、アンケートを出すのが難しいという方たちに対しては、この支援は届かないということなのでしょうか。それとも、何がしかの手当てをしていただけるということなのか尋ねました。","respondent":"柏木品川区保健所品川保健センター所長","answer":"先ほど面談は必須と申し上げましたが、やむを得ない事情の場合については個別に判断ということが、国からのＱ＆Ａで示されておりますので、そのときの状況によってご相談をさせていただきたいと思います。","id":"exchange-007"},{"speaker":"いながき委員","kind":"質問","question":"安心しました。２枚目の事業スキームのところなのですけれども、あれなのですが、具体的にどういったものがあるのかというのをお尋ねしてもよろしいか尋ねました。","respondent":"若生健康課長","answer":"東京都で検討を進めており、家事支援とか育児支援サービス、都の説明を確認しながら。","id":"exchange-008"},{"speaker":"いながき委員","kind":"確認","question":"スケジュールのところの要綱整備というのがあるのですが、要綱は今現在はあるものなのですか、これからつくられるものですか。一応、保健センターとかのホームページを探したのですけれども、見つからなくて、あるのだったら確認したいのですが。","respondent":"若生健康課長","answer":"こちらは全く新規の事業になりまして、補助金というか、交付金という形での事業になりますので、新たに一から要綱をこれから組み立てるということです。","id":"exchange-009"},{"speaker":"いながき委員","kind":"質問","question":"遡及的措置をというお話だったのですけれども、これはどこまで遡っていっていただけるものなのでしょうか。そういった方たちに、何よりも早くこういった情報が届いてほしいと思うので、情報の周知がどのぐらい行くのかということ。","respondent":"若生健康課長","answer":"２点目の周知に関しては、支援につなげていくというところが趣旨の一つでもありますので、きめ細かく周知を図っていきたいと考えています。そういった考え方ですとか、都が広域連携で事業をクーポンで実施するのでというところで、効率的かつ早期の実施というところの観点からは。","id":"exchange-010"},{"speaker":"あくつ副委員長","kind":"質問","question":"２つ質問したいのですが、本事業をご案内する際には、ここのところがきちんと明記されているのかどうかということが１つ。その２つを伺います。","respondent":"柏木品川区保健所品川保健センター所長、若生健康課長","answer":"こちらは国の通知の中でも、流産または死産のことが書かれておりまして、妊娠届出後、面談前に流産・死産となった場合でも対象となると。面談後、ギフトを渡した後に流産・死産した場合にも… ２点目のスケジュールの関係です。これは東京都の事業の広域連携を活用してという関係で、３月ぎりぎりいっぱいぐらいになるような説明があったことから、こういった記載をしています。","id":"exchange-011"},{"speaker":"あくつ副委員長","kind":"提案","question":"ごめんなさい、もう一つ、もう分かっていますけれども、一つ確認させてください。１０万円分の出生のギフトと、東京都内の方に関しては、２０万円分の恩恵が受けられるのかということを確認させてほしいと求めました。","respondent":"柏木品川区保健所品川保健センター所長","answer":"副委員長のご指摘のとおりです。出産応援事業で１０万円、こちらの伴走型ので５万円・５万円と、プラス２０万円という形になります。","id":"exchange-012"},{"speaker":"せお委員","kind":"質問","question":"すみません、１点だけ。１点だけお聞きしたいのですけれども、伴走型の支援は面談が１回、そこだけお聞きしたいのですけれども。","respondent":"柏木品川区保健所品川保健センター所長","answer":"１００％近くになるのではないかと想定しておりますので、２回目の面談もあるということで、今後は人事等とも調整をしていきたいと思います。少なくともそういう部分では、業務が増えるということは確実です。","id":"exchange-013"},{"speaker":"せお委員","kind":"質問・要望","question":"対象の方の意向もお聞きしながら、そういうところも検討して、あとは助産師・保健師の業務もしっかり検討していただきたいと要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"石田委員","kind":"質問・要望","question":"２年延長されたとはいえ、私たちも一般質問で求めましたけれども、品川区からもぜひ声を上げて求めていってほしいと求めました。賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"賛成です。面談をされるので、そこのところで、子育てというところのフォローが一番大事なところだと思うので、しっかりとそちらをしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/651938?Template=document&Id=3650#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":12009,"voices":51}},{"id":"r05-20230112-5","meetingId":"r05-cm01","date":"2023年1月12日","dateIso":"2023-01-12","committee":"総務委員会","time":"午後 １時４１分～午後 ２時５０分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を16件整理しています。","topics":[{"id":"topic-01","title":"第１２０号議案、品川区長の給与の特例に関する条例","agenda":"第１２０号議案、品川区長の給与の特例に関する条例","exchanges":[{"speaker":"須貝委員","kind":"提案","question":"品川区長の給与削減の提案ですが、国民生活や区内産業の運営が厳しいことから、新区長は給与を減額するということになったかと思います。今回のこの議案については、私自身は賛成いたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"これはなぜ２割なのかということと、区長の給与がどれくらいあるべきかという基準の考え方があるのか、その点についてまず伺いたいと思います。地域手当が、何が基準で１２％という数字がつけられているのか、地域手当とはどういうものなのかということについても伺いたいと思います。","respondent":"古巻総務課長","answer":"区長の給与の考え方ですけれども、区として条例の提案をさせていただいて、現在の額になっているという認識です。これを職員と同様に区長のほうにも適用したというような考え方ですので、同じ割合で加算をするという形での考え方で整理がされているものです。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"２３区の中でどういう、２３区の区長の給料が、どういう状況になっているのかということについても伺えたらと思います。この２０％と２５％というのは、なぜこれがプラスされるのかという、その理由についても伺いたいと思います。","respondent":"古巻総務課長","answer":"大田区は１１５万４,８００円、それぞれの区が特別職報酬等審議会の意見を踏まえて制定をして決めている額というふうに認識をしております。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"お答えいただいたところでは１００万円は超えている、そういう中で９１万２,０００円というのは、その点も伺いたいと思います。期末手当、そのトータルで削減される額ということで計算したのですけれども、これでいいかということを確認をさせてほしいと求めました。","respondent":"古巻総務課長","answer":"２３区全体での状況といいましょうか、資料にもあります９１万２,０００円というのは、２３区で一番金額の低い数字ということで認識をしております。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この４倍になるというのが退職手当だと思うのですけれども、この４.８倍というのは、どういうところからこの数字が出てきたのか。結構出るものだなと、この考え方と仕組みがどういうふうになっているのか、そこら辺の退職手当の考え方と根拠について教えてほしいと求めました。","respondent":"古巻総務課長","answer":"今、基本的には、割合としてはほぼ同じ割合を当てはめているのかなというふうに考えています。４００から５００ぐらい、周辺区でありますとか、いろいろな状況に応じて定められているものという認識です。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そうすると、５４３万７３２円のカットということになるということで確認をさせていただきたいのですが、それでよろしいでしょうか。その報酬等審議会の役割についても伺いたいと思います。","respondent":"古巻総務課長","answer":"もう１回、また改めて考えるといいましょうか、定めるというような形になろうかと思います。改めて日程を定めて、どこかのタイミングで開かせていただいて、そういった形で今後は進めていくような予定で考えております。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"ということは、今回、特例という形での条例なので、今回の２割カットということに対しては、この報酬等審議会の意見を聞くということは、今後、これからも聞くということはなく、特例ということで、４年間はこれでいくのだということで進んでいくのかということの確認だけさせてください。","respondent":"古巻総務課長","answer":"具体的に意見を聞くということはないとは思いますけれども、当然、今回、給与の減額を条例で特例で定めておりますので、それを踏まえた上で、いろいろご意見を伺うというような形にはなろうかと思います。","id":"exchange-007"},{"speaker":"吉田委員","kind":"質問","question":"この議案の付則の第３項というのですか、どう読み取っていいのかが分からなくて、教えていただけますか。","respondent":"古巻総務課長","answer":"全体として２割にするということで、調整のさらに調整ということでご理解いただければと思います。ぴったり２割にするための規定です。","id":"exchange-008"},{"speaker":"吉田委員","kind":"確認","question":"これだけ減らしてもこれだけの額になるのだということを今回改めて確認させていただいたようなことで。ただ、今回につきましては、区長自ら給与を減額するという決断をされたことについては尊重したいと思いますので、賛成をいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"}]},{"id":"topic-02","title":"第１１９号議案、令和４年度品川区一般会計補正予算","agenda":"第１１９号議案、令和４年度品川区一般会計補正予算","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これ、６分の１と６分の１が東京都と区ということで伺ったのですけれども、それでいいのかということを１つお聞かせほしいと求めました。品川区は第４回定例会も遅かったので今回になったのか、ほかの区の状況も教えていただけたらと思います。","respondent":"黒田財政課長","answer":"区のほうに６分の５を補助金として交付して、区の負担割合は６分の１ですので、ご指摘のとおりです。基本的にはどの自治体も、時期の差はあれど、実施するというふうに伺っているものです。","id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そういう点では、今後について具体的にこういうふうな方向性が出されそうだとかということは、区のほうには来ているのか。来ていたら、どのようなものが方向性として出されているのか、その点についても伺えたらと思います。","respondent":"黒田財政課長","answer":"それが国で直接行うものでありましたり、東京都で行うものでありますとか、あとは区市町村で行うものが様々出てくると思います。そういった中で実施主体が区市町村になるものにつきましては、区としても、しっかりその内容をとらまえて対応してまいりたいと考えています。","id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"本当に少子化が深刻な状況というところでは、子育て支援は、区独自にも様々に対策を打っていくことがすごく必要だと思います。国に対しても言ってほしいと求めましたし、ぜひとも区独自にも、これから対策をとっていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"須貝委員","kind":"意見","question":"どうすれば子どもたちが、品川区も考えて、少子化が少しでも改善できるような方向性に持っていけたらいいなというふうに思います。意見だけ言わせていただきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"つる副委員長","kind":"質問","question":"品川区の出生数が大体３,５００人前後、５億２,０００万円ぐらいが、それから出産時を合わせてそのぐらいになっていく。今の既存の予算配分になると６分の１、今後どういうような考え方で財政としてやっていくのか、この辺りを説明を求めました。","respondent":"黒田財政課長","answer":"１０月以降については令和５年度の国の予算を措置する方向で検討を進めていると聞いてございまして、令和６年度以降の事業につきましては。その事業ボリュームにつきましては、全体の予算編成の中で、毎年度また検討していくものと考えています。","id":"exchange-014"},{"speaker":"つる副委員長","kind":"質問・要望","question":"死産等をされた方でも、返金を求めないという形でご活用いただけるというところを、先ほどの所管委員会で確認させていただいたところです。６分の１を出しているわけですので、区からもしっかり意見具申をしていただければと、これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"吉田委員","kind":"質問・要望","question":"なぜ子どもをなかなか持ちにくいのかということについては、きちんとその理由を探っていただいて、抜本的な対策をとってほしいと求めました。そういう方たちにも、こういうサービスが届くように配慮をしていただくことをお願いして、賛成といたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/246119?Template=document&Id=2256#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":14994,"voices":57}},{"id":"r05-20230112-10","meetingId":"r05-cm01","date":"2023年1月12日","dateIso":"2023-01-12","committee":"議会運営委員会","time":"午後 ３時４０分～午後 ３時４２分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/881920?Template=document&Id=5494#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":1067,"voices":8}},{"id":"r05-20230123-6","meetingId":"r05-cm01","date":"2023年1月23日","dateIso":"2023-01-23","committee":"区民委員会","time":"午後 １時００分～午後 １時２８分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を14件整理しています。","topics":[{"id":"topic-01","title":"引越し手続きのオンラインサービス開始","agenda":"引越し手続きのオンラインサービス開始","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"引っ越しに伴う行政手続き等のオンライン化が実施されるという理解でよろしいのでしょうか。何も変更がないのか、何らかの不利益をこうむるようなことはないのか、その点をお伺いいたします。","respondent":"吉野戸籍住民課長","answer":"２月６日なのですけれども、２月６日、こちらの関係法律が制定されたことに伴ってのものになります。こちらは今までどおり手続きはそのまま、手で書いていただいてということで、可能になります。","id":"exchange-001"},{"speaker":"おくの委員","kind":"意見","question":"応えないまま、マイナンバーカードのサービスを拡大していくのは、私はやめるべきだと思います。これを意見として述べさせていただいて、終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"松本委員","kind":"意見","question":"オンライン手続きということでホームページ上も掲載されていると思うのですが、この既存のものと今回のものの違いというか、どういう差があるのかというところのご説明をお願いいたしますとの意見を述べました。","respondent":"吉野戸籍住民課長","answer":"それから、転入するに当たって、いつ手続きに行きますという予約もできるような形になっています。ただし、時間は指定できないのですけれども、いつ来られるということで、こちらも準備ができるというような、そういった手続きになります。","id":"exchange-003"},{"speaker":"松本委員","kind":"質問","question":"既存のオンラインのほうの転出というのは、これは品川区でやられていたということでしょうか。これまでは基盤は品川区で予算をかけて整備していたけれども、それが国の予算で新しい仕組みになるという理解でよろしいか尋ねました。","respondent":"吉野戸籍住民課長","answer":"委員のご指摘のとおりになります。今までのものに関しましては、マイナポータルを使わずに、グラファーという独自のものを使っておりました。","id":"exchange-004"},{"speaker":"松本委員","kind":"意見","question":"今おっしゃったものは、これまではどのくらいの費用をかけていたのか。品川区としての費用というのはなくなると理解していいのか、それはどのくらいの額なのか、分かればお願いいたしますとの意見を述べました。","respondent":"吉野戸籍住民課長","answer":"今度のサービスに関しましては、全て補助金のほうになります。ですので、グラファーのほうの使用料なのですけれども、そちらはかからなくなります。","id":"exchange-005"},{"speaker":"松本委員","kind":"質問","question":"これまでのグラファーは、これは区の持ち出しというか、補助、国庫とか、全くなかったという理解でよろしいか尋ねました。","respondent":"吉野戸籍住民課長","answer":"委員のご指摘のとおり、これまでは区の持ち出しという形になっておりました。","id":"exchange-006"},{"speaker":"塚本委員","kind":"質問","question":"何がどう変わるのかをしっかり理解したいと思いますので、改めての質問なのですが、オンラインで（１）で入力しますと。こういう理解でよろしいか尋ねました。","respondent":"吉野戸籍住民課長","answer":"転入のときだけ、必ずマイナンバーカードをお持ちになっていただいて、そこで手続きをしていただくという形になります。今までは申請書を書いていただいていたのですけれども、その申請書自体が署名だけで済むようなサービスになります。","id":"exchange-007"},{"speaker":"塚本委員","kind":"確認","question":"これは転入のときと同じようなことをするということなのでしょうかと。やはりここも来庁して本人確認をせざるを得ないものなのか、そこが来てくださいとなっている事情というのはどういうところか尋ねました。","respondent":"吉野戸籍住民課長","answer":"これに関しましては、マイナンバーカードには顔写真がありまして、まず間違いなくあなたが引っ越されてきますねという確認をしますので、転入と同様に、やはり転居も不正を防ぐという意味で、まず顔と一致させていただいて、それで手続きを行うという段取りになっています。","id":"exchange-008"},{"speaker":"塚本委員","kind":"確認","question":"必ず１回本人確認、本人の顔写真つきのものと本人が間違いないと窓口で確認しますということは、これは法律で決まっているのですか。それとも区としての判断なのか、そこを説明を求めました。","respondent":"吉野戸籍住民課長","answer":"こちらなのですけれども、住民基本台帳法で本人確認をするようにということで、あと戸籍法でも本人確認をするようにということで、こういったことは決まっております。","id":"exchange-009"}]},{"id":"topic-02","title":"「第３２回伝統の技と味／しながわ展」の開催","agenda":"「第３２回伝統の技と味／しながわ展」の開催","exchanges":[{"speaker":"おくの委員","kind":"質問・要望","question":"ＱＲコードというのですか、ちょっとやってみたのですけれども、そうしますと区のホームページに飛ぶのです。この第３２回のしながわ展のもう少し詳しい説明というか、その点、いかがか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"活動などの周知といいますか、こういうことをやっていますということでご案内させていただいているところです。思いとかそういうものがあれば、そういう部分も広げられるような形で、工夫を考えていければと考えています。","id":"exchange-010"},{"speaker":"本多委員","kind":"質問・要望","question":"第３２回を迎えまして、匠の技の種類ですか、これがどういうふうになっているのか。匠の技の種類がどうなっているのか、その辺の推移を簡潔に教えていただきたいのと、その辺の現状について説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"その人を、横展開という言い方は変ですけれども、そういう部分で何とか盛り上げていければなということでうちのほうでも考えているところです。その後どういう展開というか、どういう支援をしていくというところでは、なかなか難しい部分があろうかなと考えているところです。","id":"exchange-011"},{"speaker":"本多委員","kind":"質問・要望","question":"本当に自主的に努力していかなければいけない部分も多いかと思いますが、ぜひ伝統を後世に伝えることを課題に置いて、努めてほしいと求めました。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"塚本委員","kind":"確認","question":"すみません、１つだけ確認させてください。お子さんがけん玉をやったり、そういうのがかなり密に昔遊びのコーナーで連携できるような関係が醸成されてきているのか、現状を説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"今回の昔遊びのコーナーについては、特別にそういう専門家といいますか、そういう方を配置する予定はないというのが正直なところです。ほかのところとの連携といいますか、ＮＰＯの支援なども、私どもでも貢献できればなと思っているところです。","id":"exchange-013"},{"speaker":"塚本委員","kind":"質問","question":"所管が違うのですかね。そういうのは、区としては多分持っていなくて、どこかからさくっと借りられるような状況にあるのか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"こちら、例えば児童センターとかはあろうかと思いますので、ただすみません、今回どこから持ってくるかというのはお答えが難しいところですが、ただ、経験から、いろいろなところで持っているかなと考えています。","id":"exchange-014"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/753456?Template=document&Id=2950#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":9376,"voices":45}},{"id":"r05-20230123-7","meetingId":"r05-cm01","date":"2023年1月23日","dateIso":"2023-01-23","committee":"厚生委員会","time":"午後 １時００分～午後 ２時２５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を29件整理しています。","topics":[{"id":"topic-01","title":"品川区立東大井地域密着型多機能ホーム指定管理者候補者の公募","agenda":"品川区立東大井地域密着型多機能ホーム指定管理者候補者の公募","exchanges":[{"speaker":"石田委員","kind":"質問・要望","question":"そこをもう一度ご説明いただきたいのと、こういう連続して１０年を経過することから、伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"しかし、令和３年の４月に、品川区指定管理者制度活用に係る基本方針の改定版が出ました。先ほどの説明で、合わせて１５年というところで、制度として変わったという経過があります。","id":"exchange-001"},{"speaker":"石田委員","kind":"質問","question":"分かりました。では、問題があってということではないので、公募要項の中身というのはおおよそ変わらないまま、公募がされていくということでいいのか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"公募の中身等につきましては、指定管理者が行う業務、３番のところに記載しておりますが、こちらは今までもこの施設で行われているサービスのことについてですので、中身は変えずに同じような形で公募を行うということです。","id":"exchange-002"},{"speaker":"いながき委員","kind":"質問・要望","question":"公募となると、どういったところに配られるのかというのをお尋ねしたいのと、どういった方が入られるのかというのが少し気になっています。これまでご利用されていた方が入るのか、そういった方たちの意見が反映されるのかというのをお尋ねしたいのですが。","respondent":"菅野高齢者福祉課長","answer":"サービスの施設ごとに４つの視点ということで、組織力、それにのっとって選定をする予定です。選定の方法が、こちらの基本方針によって２段階の方法になっておりまして、選定予備委員会と選定委員会があります。","id":"exchange-003"},{"speaker":"あくつ副委員長","kind":"質問","question":"東大井の小規模多機能の施設の公募ということなのですが、私も視察に、もう何年も前ですが伺ったことがあって、認知症対策の切り札ということで、この小規模多機能の施設は展開していただいているのですが、今現在行っていただいている指定管理者はどこなのかというところをまず伺います。","respondent":"菅野高齢者福祉課長","answer":"現在行ってもらっている指定管理者は、株式会社大起エンゼルヘルプという会社となっております。こちらの会社は、平成２１年４月に開設してから、以来１５年近くお願いしている運営事業者です。","id":"exchange-004"},{"speaker":"あくつ副委員長","kind":"質問","question":"この１５年ごとにというか、今までの実績というのは、当然この選定の中で加味をされていくのかどうか。例えば能力が同レベルだというふうに判断をしたときに、実績みたいなものがその評価の基準になるのかというところをお伺いしたいと思います。","respondent":"菅野高齢者福祉課長","answer":"１点目の、これはもう令和３年にこちらの制度が改正されたということで、その部分については事業者には説明をしています。ただ、利用者のいろいろな負担とかを考えたときにはということで、あくまでも公平な基準というところで審査は行いたいと思っているところです。","id":"exchange-005"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"できれば今やっている方に応募していただきたいとおっしゃったのですが、一般論として伺いますが、同じようにそういう発言をされるのですか。それと今の課長の発言は、どうなのかなというところがあるのですが、そのあたりはいかがか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"あくまでも今回の指定管理者の基本方針が変わったということにつきましては、やはり制度上の公平性とか透明性とか、そういった部分があります。きちんと、募集をする際には公平に審査は行いたいというのがもちろんのことですので、しっかりと徹底したいと考えています。","id":"exchange-006"},{"speaker":"高橋（し）委員","kind":"確認","question":"今、確認で、公平に行っていただけるというお話だったので、大丈夫です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"}]},{"id":"topic-02","title":"品川区立北品川高齢者多世代交流支援施設（北品川ゆうゆうプラザ）指定管理者候補者の公募","agenda":"品川区立北品川高齢者多世代交流支援施設（北品川ゆうゆうプラザ）指定管理者候補者の公募","exchanges":[{"speaker":"石田委員","kind":"質問","question":"この北品川ゆうゆうプラザの、高齢者の健康維持や増進および生きがいづくりを支援するということで、ここでミニデイとかも入れるということになってくるのか、伺いたいと思います。","respondent":"川原高齢者地域支援課長","answer":"あくまでも令和６年４月の開設の予定ではありますが、地域ミニデイの実施は、現状に合わせて予定をしたいとは考えてあります。ただ、あくまでも予定の段階です。","id":"exchange-008"},{"speaker":"石田委員","kind":"確認","question":"では、全てにおいてミニデイがあるというわけではなかったでしたか。そこの確認と、今の段階ではそこはそもそも入っている、検討事項なのか尋ねました。","respondent":"川原高齢者地域支援課長","answer":"実際に開設してから何の事業を実施するかというところまでは、まだ、もちろん現段階では未定です。区が委託する、依頼する事業であることというところも、基準に入ってあります。","id":"exchange-009"},{"speaker":"いながき委員","kind":"確認","question":"配布先をお尋ねしたいのと、やはり確認ですが、選定基準を教えてほしいと求めました。どういった方たちが入るのかをお尋ねしたいのと、利用者の声はどういった形で反映されるのか、そういった点を教えていただけますか尋ねました。","respondent":"川原高齢者地域支援課長","answer":"初の公募ということで、今までの改築工事の説明会とか新築工事に至る説明会で、事業者の方もいらっしゃっていただいています。やはり各種の住民説明会全体に関しても、利用者を対象とした説明会、あと高齢者クラブの会長を対象とした説明会。","id":"exchange-010"}]},{"id":"topic-03","title":"品川区医師会館内改修工事に伴う休日診療所の休診および代替実施","agenda":"品川区医師会館内改修工事に伴う休日診療所の休診および代替実施","exchanges":[{"speaker":"石田委員","kind":"質問・要望","question":"品川区医師会の中にある休日診療所の改修工事ということでいいのかという確認と、そうした改修工事への区からの工事費の支援というのも要望で出ていたかと思うのですが、伺いたいと思います。","respondent":"若生健康課長","answer":"それから、改修工事への工事費の支援のお話ですけれども、医師会からは、予算をご要望としていただいております。こちらについては現在検討中というところでございまして、来年度の予算編成のところでの回答になるかとは思うのですけれども、現在検討中です。","id":"exchange-011"},{"speaker":"石田委員","kind":"質問・要望","question":"人材に当たってもそうだし、運営に当たっても様々、ずっと出されてきた要望だと思います。もう一回、いつぐらいまでにどういう支援がされるというのがあるのか、伺いたいと思うのですが。","respondent":"若生健康課長","answer":"こちらの経済的支援のところですけれども、現在、来年度予算についての予算編成というところでの検討というところで、検討しているということでお答えさせていただいたところです。","id":"exchange-012"},{"speaker":"石田委員","kind":"質問・要望","question":"来年度予算のところで検討ということで、でも、来年度に入る前の工事というところでは、大変負担になってくると思いますので、そこは早急な対応を私は取るべきだなと思いますし、取っていただきたいという要望ですけれども、お願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"あくつ副委員長","kind":"質問","question":"やはり区民にとって何が一番重要かというと、この輪番でやる診療所がどこでやるのかということを周知することが、非常に重要なのかなと。そういうことも当然想定されていると思うのですが、そのあたりの周知、このほかの手段で何かお考えになっているのか説明を求めました。","respondent":"若生健康課長","answer":"まず最初の周知としてはホームページでご案内するのと、併せまして、ＳＮＳ等で広く周知できるよう検討していきたいと思います。広報しながわの２月１日号で、いつがどこの診療所なのかというところは、きちんと周知を図っていきたいと考えております。","id":"exchange-014"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"ＳＮＳというお話もあったのですが、品川区のＬＩＮＥが結構頻繁な確率で飛んでくるのですが、やはり非常に有益な情報というか、自分に関心のある情報は結構目に飛び込んでくるので、そこについては目につくような表示の仕方で、ぜひ周知をさらに進めていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"もう２月からこういうふうになるということなので、区のホームページの改修を早くしていただきたいと、そこの改修を急いでほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"いながき委員","kind":"意見","question":"多分１年先、２年先になってしまうとあまり効果がないのかなというふうに素人考えでは思ってしまうのですが、お尋ねしますとの意見を述べました。","respondent":"若生健康課長","answer":"来年度の予算編成に向けた検討というところで、年度当初から工事の予定は伺っていたのですが、また一定期間の検討が必要だということでご理解いただければと思います。","id":"exchange-017"},{"speaker":"いながき委員","kind":"意見","question":"前に補聴器の請願があったときにも、やはり８年前からそれがあって、でも検討中というお話だったのですね。何かつまずきがあるのかとお尋ねしたらば、もう本当に８年間２０％しかいかなかったから、判断する基準はないのかな……との意見を述べました。","respondent":"高橋（伸）委員長","answer":"いながき委員、本日、報告事項は代替実施についてということなので、それに関してのご質疑をお願いします。","id":"exchange-018"},{"speaker":"いながき委員","kind":"質問","question":"駄目ということなので、そういった疑問がありますので、何かのときに教えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"}]},{"id":"topic-04","title":"品川区における新型コロナウイルス感染症対策","agenda":"品川区における新型コロナウイルス感染症対策","exchanges":[{"speaker":"石田委員","kind":"質問・要望","question":"今年の４月、５月に引き下げていくことを目指すとされているのですが、すごく危険なのではないかなと私は思うのです。検査も全て有料になってくるというところでは、区としては５類への移行についてはどのような見解をお持ちなのか、伺いたいと思います。","respondent":"坂野保健予防課長","answer":"国のほうも、先週の金曜日も国の別件の説明会があったのですが、全然それに関してはなしです。今のところ情報はないということです。","id":"exchange-020"},{"speaker":"石田委員","kind":"質問・要望","question":"車内で結局行き場がなくて２時間程度、要は行き場を求めてずっと停車しているという状況で、品川区内の話です。抗原検査キットを配布する、そういうことを区民にもしていただきたいなと思うのですけれども、いかがか尋ねました。","respondent":"坂野保健予防課長","answer":"もちろん保健所に電話をいただけたら、ここでやっていますよというご案内をしていますので、それである程度の対応ができているのかなとは思います。","id":"exchange-021"},{"speaker":"石田委員","kind":"質問・要望","question":"何ていうのですかね、家族との接触はどうなるのかというのがすぐに分からない、分かりたいというところがあると思うのです。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"いながき委員","kind":"質問・要望","question":"３月末で終了して、今現在、何かあるのか。どういった対策とか、もしくは将来的に何かこういった方向で考えているというものがあれば、教えていただきたいのですが。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"ワクチンのことかと思われますので、私のほうでお答えします、ワクチン自体は区で独自で供給が賄えるのではなくて、全て国で行っているものです。","id":"exchange-023"},{"speaker":"いながき委員","kind":"質問","question":"そういうところがすごく品川区はいいなと思っているので、そういった部分が継続的にこれからも進んでいければなと思っての質問でした。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"}]},{"id":"topic-05","title":"産後ケア（日帰り型）の会場変更","agenda":"産後ケア（日帰り型）の会場変更","exchanges":[{"speaker":"石田委員","kind":"質問","question":"７月中旬からは、しかもこれ、全部場所が近くないですよね。なので、大変だなと思ったりしたのですけれども、そこら辺の利用する側の利便性や声、そういったところは何か出ているのか伺いたいと思います。","respondent":"柏木品川区保健所品川保健センター所長","answer":"ケアする側に不便がないかということですが、一応、会場変更に伴って、ケアする側の不便性は特にはございません。使えるのは１回ということですので、１人の方が何回も使って会場が毎回違うとか、こちらはきっちり周知することで解消できるかと考えております。","id":"exchange-025"},{"speaker":"いながき委員","kind":"質問・要望","question":"同等のホテルとかで会場をもう一度お探しいただきたいなという希望がありまして、私、本人負担額は変えなくていいと思うのです。そういったところで産後ケアのお母さんたちの支援を続けていただきたいなということがありますので、それはご検討いただけるのか尋ねました。","respondent":"柏木品川区保健所品川保健センター所長","answer":"会場の点ですが、こちらは内部で検討する際にも、代替のホテルという話はございました。ただ、先ほどの説明の中でも申し上げたのですが、産後ケアをやっている中で、やはり助産師が気になる母親の情報が、年々増えてきている。","id":"exchange-026"},{"speaker":"いながき委員","kind":"意見","question":"その日のリラックスであるとか、こちらの雰囲気づくりとかも、できればいま一度検討をいただければなというお願いですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"せお委員","kind":"質問・要望","question":"その事業者というのはどういったところなのかというのを教えていただきたいのと、本当に声が多いですというのを伺っていたり、そこもお聞かせほしいと求めました。","respondent":"柏木品川区保健所品川保健センター所長","answer":"大きいことはできませんが、一応内装等で雰囲気をつくれるような形で、備品等もそろえて対応していきたいと考えています。特に今の予定ですけれども、そういうふうな部分も作って、充実させていきたいと考えているところです。","id":"exchange-028"},{"speaker":"せお委員","kind":"意見","question":"そこからいかに相談につなげていくかというか、支援につなげていくかというところかなと思っているので、そこの検討をとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/651938?Template=document&Id=3652#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":21600,"voices":96}},{"id":"r05-20230123-8","meetingId":"r05-cm01","date":"2023年1月23日","dateIso":"2023-01-23","committee":"建設委員会","time":"午後 １時００分～午後 １時５１分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を18件整理しています。","topics":[{"id":"topic-01","title":"令和５年２月都営住宅入居者募集","agenda":"令和５年２月都営住宅入居者募集","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"これまでの応募倍率などの実績、戸数も含めて、それを伺いたいと思います。","respondent":"竹田住宅課長","answer":"昨年１年間の応募数等をご説明します。昨年２月が、８月が４戸に対して２０８人で５２.０倍、１１月が６７戸に対して７０４人で１０.５倍となっています。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"９.９倍から５２.０倍ですか、どういうところに多いとか、そういったのがあれば伺いたいと思います。それを、区として都に増設すべきだと求めていただきたい、求めるべきではないかと思いますが、いかがか尋ねました。","respondent":"竹田住宅課長","answer":"それから、増設の働きかけというご質問ですが、区内には都営住宅が１４団地建設されております。総合的に様々な施策を組み合わせていくべきだと考えておりますので、都へ都営住宅の増設を働きかける考えはございません。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"その傾向というのですか、そこを伺いたいというのが１点と、増設を求める考えはないということでしたけれども。区営住宅も含めて、役割発揮が求められていると思いますが、いかがか尋ねました。","respondent":"竹田住宅課長","answer":"倍率の傾向ですが、昨年１年間を例にご説明しますと、８月は４戸の募集で２０８人の応募がありましたので、５２.０倍となっております。居住支援協議会のご意見を聞きながら住宅対策を進めているところですので、今後、住宅施策を展開していきたいと考えております。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"住民の暮らしをしっかり支えていく、保障していくということが必要だと、これは強く求めておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"}]},{"id":"topic-02","title":"戸越公園駅交通広場に関する都市計画素案","agenda":"戸越公園駅交通広場に関する都市計画素案","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"資料のところから伺っていきたいのですが、別紙２の３の課題のところで、そこを伺いたいと思います。防災性の高い空間を確保ということが書かれているのですが、それはどういった空間になるのか、そこを伺いたいと思います。","respondent":"中道まちづくり立体化担当課長","answer":"なかなか年配の方が、駅前に車をつけて乗り降りするというのが非常に難しいといいますか、人混みがあるので避けているような状況です。中学校に行こうかといろいろ考える中で、駅前広場を整備することで、そういった空間に人が集まることができるというところも考えております。","id":"exchange-005"},{"speaker":"のだて委員","kind":"質問","question":"そこのところを伺いたいのと、その辺、区で考えている部分があれば伺いたいと思います。この都市計画素案の説明会の前に、住民の方にこうした計画があるよということはお知らせしているのか、伺いたいと思います。","respondent":"中道まちづくり立体化担当課長","answer":"今回の説明会の前に、こういった計画を区民に説明したことがあるかですが、今回初めて皆様にご説明するタイミングではあります。その記載の中に駅前広場の考え方、またはどこの位置に設置するか、イメージなど、そういったものは今までも説明してきているところです。","id":"exchange-006"},{"speaker":"のだて委員","kind":"質問・要望","question":"そこはしっかりお知らせをしていただきたいと思うのですが、そのあたりになると思うのですが、そこを伺いたいと思います。地権者と、あと借家人も含めて伺いたいと思いますが、いかがでしょう。","respondent":"中道まちづくり立体化担当課長","answer":"配布枚数は約１万１,０００枚と、非常に丁寧に今回、説明を進めているところです。一番最初の赤枠で書いてあります素案の説明会に向けて進めておりまして、４つ目、説明会の時期についてはまだ未定です。","id":"exchange-007"},{"speaker":"のだて委員","kind":"質問","question":"単純にこの今の計画図を見ますと、１６棟ですかね、建物が範囲内に入っているというふうに見えますので、この中にはマンションもあるのかな。数十人以上の方が関わってくるのかなと思うのですけれども、そこの人数、ご説明できるところがあれば伺いたいと思います。","respondent":"中道まちづくり立体化担当課長","answer":"今回のこの敷地の中で該当する方たちに対しての対応ですが、原則といたしましては、金銭補償といったものを通常行っているところです。そうしたところも、今後、東京都と連携しながら、また検討していきたいと考えています。","id":"exchange-008"},{"speaker":"のだて委員","kind":"質問・要望","question":"補償は金銭補償が原則ということですが、原則ということは、求めれば代替地も確保されるということか、そこも伺いたいと思います。いないのか、何人いるのか、伺いたいと思います。","respondent":"中道まちづくり立体化担当課長","answer":"補償に対しての仕組みについては、東京都と今後、検討して、仕組みづくりをしていきたいと考えています。高架化になるのか地下化になるのかは、今度の説明会の中で明確になると聞いてあります。","id":"exchange-009"},{"speaker":"松永委員","kind":"質問","question":"１つは、先ほどの質問の中で、そのほかにも何かありますでしょうか。シェアサイクルの設置場所というのもやるのかどうかというのを、分かる範囲でいいので説明を求めました。","respondent":"中道まちづくり立体化担当課長","answer":"検討する中で、詳細に検討するのですけれども、ご協力いただく用地も多く必要になってくることになります。補助２９号線の整備等を進めて、バス会社が、民間会社等がどう考えるかというのは必要になってくるかなと考えています。","id":"exchange-010"}]},{"id":"topic-03","title":"環境講演会","agenda":"環境講演会","exchanges":[{"speaker":"横山委員","kind":"質問・要望","question":"ご説明ありがとうございました。１点確認ですけれども、できる限り受入れをしていただきたいという思いがあってお聞きするのですが、何かありましたら説明を求めました。","respondent":"河内環境課長","answer":"それを入れますと１.２トンというところで、１人当たり１６キロだとかというところで、またご協力いただいているところです。利用しやすさなども含めまして、工夫を重ねてまいりたいと考えているところです。","id":"exchange-011"},{"speaker":"澤田委員","kind":"質問","question":"３００名の定員で７００名の応募があったということですが、例えばＹｏｕＴｕｂｅであったり映像であったり、行けなかったけど行きたかったなという人が見られるような状況というのをつくる計画はあるのか尋ねました。","respondent":"河内環境課長","answer":"進めさせていただきまして、また別の講座などによりまして、フードドライブの面につきましては啓発を重ねてまいりたいと考えているところです。アドバイスありがとうあります。","id":"exchange-012"},{"speaker":"こんの委員","kind":"質問","question":"澤田委員が質問された、ほかの契約ということですが、この講師料というのは大体どれぐらいになるのでしょうか。予算はどれぐらいで計画されているのか尋ねました。","respondent":"河内環境課長","answer":"講師料につきましては、予算５０万円、ぎりぎりの５０万円です。値切るといいますか、趣旨をご説明させていただきまして、併せてエコルとごしなどで行われておりますフードドライブの件も説明させていただき。","id":"exchange-013"},{"speaker":"芹澤委員","kind":"質問・要望","question":"お聞かせいただきたいのと、今の澤田委員の質問にも関連するのですが、非常に多くの申込みがある。予算を取っていただきたいなと思うのですが、まず、その２点を説明を求めました。","respondent":"河内環境課長","answer":"おっしゃるとおりで、真面目なだけではなかなか啓発は難しいのだなと。それから、見た方がやはり感銘を受けてしっかり取り組めるものというところのバランスを取って、しっかりやっていきたいと考えているところです。","id":"exchange-014"},{"speaker":"芹澤委員","kind":"意見","question":"最後、ＳＮＳ総フォロワー数が７６０万人ということで、品川区でこういうことをやりますというのを言っていただける契約になっているのですよね。多分７００人どころではなくて、そこの取組を、最後説明を求めました。","respondent":"河内環境課長","answer":"ご説明の中でご了解いただいているという中で、ここは大きな数字として、この人選のときに参考にさせていただいたところです。しかし、皆さんの身近に感じられるところだと認識しておりまして、食品ロスにまた大きな一歩が示せるのではないかと考えているところです。","id":"exchange-015"},{"speaker":"芹澤委員","kind":"質問・要望","question":"私もお恥ずかしながら１年前ぐらいにＹｏｕＴｕｂｅを１回やってみて、さっき見たら３６人ということで、ぜひ品川区から発信していただければと。これは要望でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"横山委員","kind":"質問・要望","question":"面白い体験として進めていただきたいと思うのですけれども、そのあたり、考え方を説明を求めました。","respondent":"河内環境課長","answer":"それから情報の広域な発信と、両面にわたりまして、しっかりと視野を広げていきながら進めてまいりたいと考えております。","id":"exchange-017"},{"speaker":"横山委員","kind":"質問・要望","question":"何が区にとって一番環境問題、区民の方が取り組みやすいように周知・啓発していけるのかということをぜひ考えてほしいと求めましたので、どうぞ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/372951?Template=document&Id=4370#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":16846,"voices":60}},{"id":"r05-20230123-9","meetingId":"r05-cm01","date":"2023年1月23日","dateIso":"2023-01-23","committee":"文教委員会","time":"午後 １時００分～午後 ３時１１分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を36件整理しています。","topics":[{"id":"topic-01","title":"令和４年度第２回家庭教育講演会","agenda":"令和４年度第２回家庭教育講演会","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"お伺いしたいのと、この講演会ではないとは思うのですけれど、旧統一教会や関連団体の講師を採用したりというようなことがあったのか。調査などはされたのか、というのを伺います。","respondent":"宮尾庶務課長","answer":"２点目の、いつからというところなのですが、今、手元で確認できる範囲で、平成の一桁までは遡ってデータがあります。ある特定の考え方ですとかそういったことによらない中立で公正な方、こういったことも講師の方を選ぶ基準の一つとしています。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"それ以降、旧統一教会とか関連団体の講師を採用したりということはなかったということなのでしょうか。確認させていただきたい。","respondent":"宮尾庶務課長","answer":"他の自治体に何か問合せを、ということはありますが、最終的には事務局の職員のほうで決めしています。つぶさに該当するかどうかという調査自体は行っておりませんが、過去にそういった関係の方はいないというふうに認識しております。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"こうした保護者の声とかご指摘とか、そのガイドラインを策定してほしいという要望について、区教委には届いておりますでしょうか。伺います。","respondent":"宮尾庶務課長","answer":"その中に、講師の方を選ぶ際にはこういうことに気をつけてくださいということも、記載しています。例えば、次はもう少しこういうところの記述を厚くしよう、こういったことも日々私どものほうでやらせていただいているところです。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"先ほど言ったようなお声もあったので、現在のガイドラインというのを少し見直してほしいというようなご要望があるのです。それは、現在見直す方向に入っているのか尋ねました。","respondent":"宮尾庶務課長","answer":"そのときは丁寧に、お声、内容をお伺いするように心がけているところです。そういったご相談内容をその場限りとしないで、その辺も盛り込んだ上で、次年度のガイドラインを作るときに対応させていただいているところです。","id":"exchange-004"},{"speaker":"田中委員","kind":"質問・要望","question":"ただ、ＰＴＡの家庭教育担当というのですか、その方たちだけにそれは配布されているものなのか、そこの部分をお知らせいただけますか。どういった会を実施したらいいのだろうと悩まれている方は確かにおられて、そこら辺をお知らせいただきたいのですけれど、いかがか尋ねました。","respondent":"宮尾庶務課長","answer":"委員おっしゃるように基本的にはご担当の方といいますか、事務説明会というのを毎年開催しているのですが、その時にお配りをしているものです。その事務説明会の配付用という位置づけでお作りしています。","id":"exchange-005"}]},{"id":"topic-02","title":"令和５年度品川区立学校における土曜授業の実施","agenda":"令和５年度品川区立学校における土曜授業の実施","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"１０か月ほどたっていると思うのですけれど、主にどのような声などを聞いているのか、伺えればと思います。子どもと保護者と学校、それぞれについてもしあれば、説明を求めました。","respondent":"矢部教育総合支援センター長","answer":"皆さん、役員を含め保護者はお忙しいので、これを機会に工夫をしていただきたいというお話をしております。学校を通して、まだ３月まではきちっとお話を聞きながら、対応してまいりたいと思います。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"工夫して活動できる時間というのも必要だと思いますので、土曜授業を減らすことになったというのは、私としては非常にいいことではないかと思います。は限られた時間でいかに教育活動の質を上げていくかということについては、これからも頑張ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"}]},{"id":"topic-03","title":"を、改めて聴取いたします。 (3)今後の児童センターの方向性","agenda":"を、改めて聴取いたします。 (3)今後の児童センターの方向性","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"確認させていただきたい。3)の課題のほうに、これはどういうことを指しているのか、お願いします。","respondent":"廣田子ども育成課長","answer":"五人ですと、１人の担当する事業の数が多くなりますので、改善されるのではないかと考えているところです。先ほどご説明したとおり、育成がしやすくし、今の強みを継承していくというところを話し合っております。","id":"exchange-008"},{"speaker":"安藤委員","kind":"質問","question":"これはどういう意味なのか伺いたいのですが、直営館１３館ということなのですが、この直営館を減らすということなのでしょうか。伺います。","respondent":"廣田子ども育成課長","answer":"各館に１.５人ずつ置いているのですけれども、部分休業と言って育児のため１時間とか２時間早く帰るという職員もいるので、それも使わせてもらう。職員の人数であったり、スキルで足りない部分で委託の力を借りるという考え方で、進めていこうと考えております。","id":"exchange-009"},{"speaker":"安藤委員","kind":"質問・要望","question":"その具体的な検討についても、当事者の子どもたちの参加というのを求めたいのですが、いかがでしょうか。それだけ確認させてください。","respondent":"廣田子ども育成課長","answer":"今後の検討なのですけれども、検討のメンバーを今から決めまして、４月から取りかかろうかと思っています。まだ今の段階で具体的なことは申し上げられない時期ですので、そのような形で聞いております。","id":"exchange-010"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひ子どもの意見を取り入れて、いい方向に進んでいってほしいと求めました。もうすぐ４月だと思いますけれど、検討メンバーというのはどのような方を考えているのか、もう一回聞かせてもらえますか。","respondent":"廣田子ども育成課長","answer":"検討に関しましては、大きいくくりを考えながら、また個別具体的なものも考えながら進めようと思っています。検討メンバーについては、今検討しているところなので、そこから進めていきたいと思っているところです。","id":"exchange-011"},{"speaker":"田中委員","kind":"質問","question":"伺いたいのですけれど、南品川になった理由を伺いたいのですけど、中心からずれているというか。そこになった理由は何なのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"渡部委員","kind":"質問","question":"例としてこういう状況に今ありますよと教えているだけだから、地域がどうこうでなくて。今の立地条件だとこういうふうになっていますと書いてあるだけなので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"田中委員","kind":"質問・要望","question":"ここで確定でないということが確認できたので、よかったです。そういうソフトの面はぜひすぐにでも進めていただきたいというのと、アピールにも力を入れていただけたらと思うのですが、いかがか尋ねました。","respondent":"廣田子ども育成課長","answer":"９館の児童センター、この３年はコロナでできなくて縮少してしまったのですけれど、少しずつ取り組みができるようになっています。子どもたちが行きやすい場所で、児童センターの子も使うことを視野に入れながら考えていきますということを、お示ししたかったものです。","id":"exchange-014"},{"speaker":"渡部委員","kind":"質問","question":"先ほども地区の１３館で、その下にいわゆるサテライトというような感じになっていくのか、どうなのか。いわゆる１３館体制を維持するというところから入ってしまうと、話が違うのかなと思うのですけれど、その辺の考え方はどうなのか尋ねました。","respondent":"廣田子ども育成課長","answer":"その検討の中では、取り仕切る館というのをやはり絞っていくという答えも、出てくる可能性はもちろんあると思っています。先ほどご説明したとおり、エリアも含めて検討をしっかりと、その辺りを少し検討して。","id":"exchange-015"},{"speaker":"渡部委員","kind":"質問・要望","question":"これはこれからなのでしょうから。要望であります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"江野下委員","kind":"質問","question":"公園とのコラボ、特色のある編成というところで、スケートボードですとかバスケットボール、これは音の関係でなかなか、こちらにも実現するのは難しいと書いてありますけれども、例えば期間限定とか、そういったことで運営していくことは、可能性はなきにしもあらずか尋ねました。","respondent":"廣田子ども育成課長","answer":"庁内の検討会の中で合築している施設がある課長たちに来てもらって、探ることはできるのではないかというのが、今回の検討の中では出てきました。","id":"exchange-017"},{"speaker":"くにば委員","kind":"質問","question":"１点伺いたいのが、職員の年齢分布についてです。４０代がゼロになっていたりするのか、４０代が０％という部分についての見解など、説明を求めました。","respondent":"廣田子ども育成課長","answer":"今育休をとっている人の分、２０代を大勢雇ってしまうと、やはりバランスよく世代を任用していくということを考えていかなければいけない。３０代が４０代、１００人欲しいといっても１００人来ないという状況なので、自由にやめたり雇ったりできるわけではない状況です。","id":"exchange-018"},{"speaker":"くにば委員","kind":"質問","question":"なぜかと言いますと、例えば４０代ぐらいのお母さんが２０代の児童センターの職員に子育ての話をしても、事実だと思います。別の部分で伺いたいのですけれども、そういったものに一部比例して予算を配分しているのかどうか、その予算配分等々に関して説明を求めました。","respondent":"廣田子ども育成課長","answer":"特色を持って全館の中で３館だけこれをやっているとか、ということで、必要な金額を積算して予算を決めています。お金がないから何かができないということはあまりなくて、必要なものに関しては本課予算でも、同じお財布の中で分配しているだけということです。","id":"exchange-019"},{"speaker":"くにば委員","kind":"質問・要望","question":"そちらの部分は、設備・備品の乳幼児親子の欄、下から２行目に「おもちゃの種類を豊富にしてほしい」等々の要望があると思います。それが予算と関わるのかどうかという部分も含めて伺いたかったのですけれども、統一的に指導している部分があったりするのか、伺えますか尋ねました。","respondent":"廣田子ども育成課長","answer":"貸出しのメニューや出してほしいということについては、現場にお話ししようかと思います。お金云々とも、またちょっと違うかなというところなので、職員のほうにはそういうご意見があったということは伝えておきます。","id":"exchange-020"},{"speaker":"くにば委員","kind":"質問・要望","question":"分かりました。こういった部分を改善してほしいとか、こういった部分をより充実させてほしい、そこの声をよく拾えるような形にしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"若林委員","kind":"質問・要望","question":"１か所でも多くそういう場を与えていただきたい、増やしていただきたいと、これは要望として申し上げておきたいと思います。こういう場所ではこういうことが期待できるねという、そのような意見交換か何かがあったら、説明を求めました。","respondent":"廣田子ども育成課長","answer":"障害者支援課長に来ていただいたのが大原の児童センターで、サロン的なところもあるので、というお話もさせていただきました。進めたいというのは割と具体的に、今後すぐにでもできますよねということでは、お話が出たところです。","id":"exchange-022"},{"speaker":"松澤副委員長","kind":"質問","question":"若林委員とかぶってしまったのですけれども、公園課との話合いというのは、児童センターの方向性について検討がなされたから話合いを始めたのか、もともと公園課とのそういう話合いというのですか、遊びの提供もあったのか、まず説明を求めました。","respondent":"廣田子ども育成課長","answer":"利用者への支援に関して協力してもらって、公園課とはプレイパークのことで大分、いろいろ近隣の方との調整をやっていたところです。改修が一緒にできたらいいなという、具体的なご意見をいただいたのは、今回が初めてです。","id":"exchange-023"},{"speaker":"松澤副委員長","kind":"質問","question":"４０代でしたっけ、都が決めているとあるので、それは変えられないものだと。もう決まりがあるから、なかなか動かせないものなのか、そこら辺を説明を求めました。","respondent":"廣田子ども育成課長","answer":"任期付きは１年とかなので、数人雇いたいところでも申込みは１人とか、職種のせいで来ないということでもないようです。採らないのでなくて採れないので、決して減らしたいというわけではなく、配置できないというのが現状です。","id":"exchange-024"},{"speaker":"松澤副委員長","kind":"意見","question":"申込みがないと理解しました。そういうことがどんどん広報できて、人員なども確保できるように、一緒に頑張っていきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"}]},{"id":"topic-04","title":"令和４年度 小中学生の生活状況調査、ひとり親家庭状況調査の結果","agenda":"令和４年度 小中学生の生活状況調査、ひとり親家庭状況調査の結果","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"項目についての要望なのですが、理想の子どもの数というのも伺えると、そういった質問項目なども追加していただきたいのですけれど。そうでないということで、要因についてはどういうふうに見られているのか、伺いたいと思います。","respondent":"飛田子育て応援課長","answer":"前回は平成２８年に行いましたが、今まで子ども未来応援プロジェクトでいろいろ各事業の検討はしておりまして。調査内容については、子ども・若者計画の資料編に、今回の主なものの結果は入れる予定です。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"どのような支援策を計画されるお考えなのかというのが、これだけだと分からないので、そこについてはおいおい報告もあるのでしょうか。区としてはどういう実態を把握して、どういう支援策の検討を重ねたのかというのを伺いたいと思います。","respondent":"飛田子育て応援課長","answer":"そういう中から、そういう変化にいち早く気づきながら、先手を打てるように努めていこうかと考えております。各子ども食堂とも相談しながら、ホームページやＳＮＳなどで、必要な方に情報が周知できるように努めていく必要があると感じております。","id":"exchange-027"},{"speaker":"安藤委員","kind":"意見","question":"調査全体の発表についてはどうなのかということと、収入は増えたけれど、何らかの課題が出てくるのではないかというご意見を紹介されました。何らかの課題というのはもう少し具体的に、ご説明ほしいと求めました。","respondent":"飛田子育て応援課長","answer":"それと女性の就業率というところですが、我々としてもまだそこまで、実態というのはつかめていないのが正直なところです。ですので、そういうところはまた、何らかの機会に、保護者、またそういう現場の声とか、聞きながら、また解明していければと考えております。","id":"exchange-028"},{"speaker":"安藤委員","kind":"質問・要望","question":"現在、高校生には拡大して給付型が、結構もう、５年、４年ぐらいたっているのではないですか。どのようなものがあるのか尋ねました。","respondent":"飛田子育て応援課長","answer":"ですので、私のほうも、国が実施している様々な支援策とか効果とか、今後の動向などは注視していきたいと考えております。大学進学に向けた支援としては、貸与となりますけれど応援資金というところで、審査等も一緒にやっているところです。","id":"exchange-029"},{"speaker":"安藤委員","kind":"質問・要望","question":"区民からこのアンケートを頂いているわけですから、それに対して、やはり自治体としてできることをやっていくというのはすごく大事だと思います。第４回定例会の一般質問でも紹介したように、自ら行ったアンケート調査結果からも、検討をぜひしていただきたいと改めて要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"田中委員","kind":"確認","question":"それは学校で配布とかはされているのかどうかというところを確認させてください。この改善に向けては、どのように今、区は考えられているのかというところを伺いたいのですが、２点伺います。","respondent":"飛田子育て応援課長","answer":"アンケートのほうでは「区内に約３０か所の子ども食堂がありますが、ご存じですか」というような問いかけをしております。ただ、こういう支援が品川区としてありますよということはその都度、説明はさせていただいているところです。","id":"exchange-031"},{"speaker":"田中委員","kind":"意見","question":"教育委員会にも協力していただいて、必要な子どもに届くように、そういった働きかけをぜひしていただけたらというのが１点です。この数値がもうちょっと上がるように、取決めをしてないというのが減るように、ぜひお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"},{"speaker":"渡部委員","kind":"質問","question":"何点か伺いますけれど、小中学生の生活状況調査というのは、これは何かルールがあって２年生と９年生でとっているのかというのを教えてください。中央値というのをよくとるではないか尋ねました。","respondent":"飛田子育て応援課長","answer":"９年生に対しては、９年生を調査対象にしているということで、そこのところに準じてやっております。今後何かしら調査があるときは、その辺もまた再度見直して、アンケートの項目等、また考えていきたいと思います。","id":"exchange-033"},{"speaker":"渡部委員","kind":"質問","question":"それがいい、悪いという話ではないのですけれど、そういうものなのですかね。これは２年生と９年生に全数調査かけているのでしょうから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"新妻委員長","kind":"質問・要望","question":"私のほうから３点、確認します。そこをどう読み取っていただいて、私は求めたいところだなと思っているのですが、そこら辺のお考えをお聞かせほしいと求めました。","respondent":"飛田子育て応援課長","answer":"このアンケートの回答が見えない部分はどうしても、２０問以上にならないようにということで配慮して、そのようにさせていただきました。約２５％に届いてないというところもあるので、そういうところでまた周知しながら、行っていきたいと考えております。","id":"exchange-035"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"田中委員","kind":"確認","question":"というようなことがあったと思うのですけれど、今の状況はどうなのかというのと、今後どうなっていくのか。もう行かなかった月にはその分利用料もかかりませんといったことでしたが、それは来年度もその形になるのかというところも、確認をさせてください。","respondent":"廣田子ども育成課長","answer":"１年生は大体使っていただいているのと、その辺りについて、担当指導員が丁寧にご説明しようと思っています。その４月の状況によってなのですけれども、月に１日も利用してない場合には引き落としをしないという形は、まだ継続しているところです。","id":"exchange-036"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/106437?Template=document&Id=5090#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":39993,"voices":105}},{"id":"r05-20230123-5","meetingId":"r05-cm01","date":"2023年1月23日","dateIso":"2023-01-23","committee":"総務委員会","time":"午後 １時００分～午後 ２時２０分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件整理しています。","topics":[{"id":"topic-01","title":"請願・陳情審査","agenda":"請願・陳情審査","exchanges":[{"speaker":"吉田委員","kind":"確認","question":"「職員は資料がないからと基本的な質問に答えず」というような記述があるのですけれども、そういうこともされていないということなのでしょうか。その辺、事実の確認をさせてください。","respondent":"佐藤（聡）計画担当課長","answer":"例えば土地区画整理事業ですとか、可能な限りはお話ししておりますけれども、細部に関して十分に説明できなかったことはあると聞いております。","id":"exchange-001"},{"speaker":"吉田委員","kind":"確認","question":"その辺についてさっき伺ったのですが、必ずしもそのときに全員の質問に答えられるとは限らないというのは十分理解できます。このケースについてはどうだったか、最終的には区としての答えがきちんと行ったと理解していいのでしょうかということを確認させてください。","respondent":"佐藤（聡）計画担当課長","answer":"この方についてということで間違いないと思うのですけれども、別途、メールで所管課に質問みたいな形で受けておりまして、個別に対応していると聞いておりますので、質問された方に対しては真摯に、個別に対応していると聞いております。","id":"exchange-002"},{"speaker":"吉田委員","kind":"質問","question":"結局、その場で答えられなかったから、そのままにされてしまった方もいるのではないかなと。後ほどこういう形でお答えしますというふうにすべきと考えるのですけれども、品川区としての基本的な考え方を改めて伺いたいと思います。","respondent":"佐藤（聡）計画担当課長","answer":"お答えを求められれば対応していると聞いておりますし、個別に対応するというのは、そのように対応していると思います。","id":"exchange-003"},{"speaker":"吉田委員","kind":"質問・要望","question":"後日でいいのできちんと回答してほしいということを伝えてほしいし、その後、きちんとお答えをほしいと求めました。この陳情者の方以外でも、この陳情の中で求められていますけれども、やはり教室型の説明会というのも必要ではないかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"来場者が３５９人ということなのですが、区としてはどう考えられているのか、その点を伺いたいと思います。それがなぜ基本構想ではされなかったのか、それがなぜ基本計画になったときにされることになったのか、そこの考え方についても伺いたいと思います。","respondent":"佐藤（聡）計画担当課長","answer":"まちづくりマスタープランのほうですけれども、委員ご指摘のとおり、今回についてはオープンハウス型の説明会を４回実施しています。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これまでも様々な計画のところで求め続けてきているのですけれども、品川区の考え方として、教室型の説明会をやるという方針にならないのですよね。これは区全体のところでの考え方というのが、そこがあるのではないかなと思うのですけれども、その点はいかがか尋ねました。","respondent":"佐藤（聡）計画担当課長","answer":"今回行われましたオープンハウス方式あるいは説明会方式にあっても、それぞれ内容について説明をして、質疑の時間を設けて。冒頭申し上げたとおり、お一人の方にできるだけ時間をとって説明をするということもやっておりますので、あまり方式にこだわらずに。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"意見交換の場、それからほかの人の意見も聞きながら、自分の意見も述べると。区としても、そういうところで教室型説明会というのはしっかりと位置づけるというふうにすべきだと思うのですけれども、その点はいかがか尋ねました。","respondent":"佐藤（聡）計画担当課長","answer":"今回やったオープンハウス方式の説明会では、説明者のほうで返して、そのやり取りを時間の許す限りやったと聞いておりますので。それを受けて、また審議会のほうでご議論いただくという形で、区民の方のご意見を十分聞いて計画は策定されていると認識しております。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それだけではなくて、区民が求めているのは、教室型の説明会で、ほかの人の意見も聞きながら、自分の意見もその中で述べていくこと。教室型説明会を位置づけるというふうにぜひしていただきたいと思うのですけれども、その点、いかがか尋ねました。","respondent":"佐藤（聡）計画担当課長","answer":"どういった説明をしていくかというところですとか、今回ご説明した２例以外にも、十分果たしていると考えております。例えばパブリックコメントも平成１９年ぐらいから始まっているというところもありますので、今後も手法については研究していきたいと考えております。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この間ずっと説明会を求め続けて、基本計画に関してはやっと５回という形でやっていただいたのですけれども、それでも参加者はすごく少ないですよね。関心を持ってもらって、その点、いかがか尋ねました。","respondent":"佐藤（聡）計画担当課長","answer":"説明会の方式につきましては、先ほど来、申し上げたとおりで、それぞれの計画に沿って工夫をしていきたいと考えております。説明会への参加者が少ないのではないかというご指摘についてです。","id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"こういうふうに進めたいけれどもどうかと、その点、いかがでしょうか。区民による検討委員会を設置するという、この公約というのはこれからどういうふうになっていくのか、具体的な中身についても伺いたいと思います。","respondent":"佐藤（聡）計画担当課長","answer":"説明会等を開いていくというところもありますし、そういった手法について、今後も研究していきたいと考えております。説明会等も含めた手法については、先ほどパブリックコメントの例も出しましたけれども、手法については今後も研究していきたいと考えております。","id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それをぜひとも転換していただきたい。ずっとそういうことを要望し続けていますけれども、ぜひともここのところは変えていただきたいということを強く要望させてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"須貝委員","kind":"質問","question":"審議会の委員にもそれは伝わるわけですから、皆さんの声は、疑問点なんかは伝わっているのではないかなと私は思います。これだけやっているということは、計画担当課長もそれなりのことをやったのではないかなと私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"湯澤委員","kind":"質問・要望","question":"今のご説明で、区として今後も出席者や質問者が納得されるような、後日でもしっかりと回答していただきたいと考えています。区民ニーズをどのような形で取り入れていく、そういった努力をされているのかというのを改めて確認させていただいてよろしいか尋ねました。","respondent":"佐藤（聡）計画担当課長","answer":"計画によって個別にそれぞれあろうかと思いますが、今回お示ししたような形で、区民の方にアンケートをとるというようなことが一つ。そういったところでニーズを捉えて、その解決といいますか、そういう方向で計画をつくっていくということで進めているという認識です。","id":"exchange-013"},{"speaker":"湯澤委員","kind":"質問・要望","question":"この手法についてはどういった場面が適しているのか、そういったことの研究もこれからされていくのもいいかなと思っています。これは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"大倉委員","kind":"確認","question":"個別にも対応して、ご説明をして、質疑の時間もとりながらやっているというお話を伺いました。私も登録をして、今度パブリックコメントがありますよみたいなこともよくスマホで見て、いつあるのだなという確認もさせていただいているところです。","respondent":"佐藤（聡）計画担当課長","answer":"審議の進行状況については、各所管の委員会のほうに報告しているということもあります。広報しながわでも概要についてご説明する記事を載せたりという形で、なるべく区民の方の目に入るような形で周知しているという状況です。","id":"exchange-015"},{"speaker":"大倉委員","kind":"質問・要望","question":"様々意見が聞けるような方法を、効果的・効率的に聞けるような方法をこれからも考えていただきながら取り組んでいただきたいと思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"本日結論を出すで、採択でお願いしたいと思います。品川区としても積極的に発信してほしいと求めましたし、教室型説明会を積極的に行う方針への転換を改めて求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"大倉委員","kind":"質問・要望","question":"本日結論を出すということで、不採択でお願いします。ぜひ丁寧に対応していただきたいと考えていますし、陳情に書いてあるようなところも含めて、この陳情については不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"吉田委員","kind":"質問・要望","question":"やはり区民参画の場を保障する形での、区民の参画というのを、今の理事者側の方たちで求めておられない方は１人もいらっしゃらないと思います。ぜひそういう形の第一歩として、やはりこういう協働で策定するということを求める陳情には、採択を主張したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"須貝委員","kind":"質問・要望","question":"代弁者としての役割もきちんと、こういうことは直してほしい、改善してほしい、こうやってほしいという要望も出しました。それ以外に何を望むのか、そうすると切りがないのではないかなと思いましたので、それだけ一言言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"せらく委員","kind":"質問","question":"本日結論を出すで、不採択でお願いします。今回、討論会や地域別のワークショップなどをされたい方もいらっしゃると思うのですが、満遍なく区民の意見を聞く場が望ましいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"}]},{"id":"topic-02","title":"第25回品川区世論調査","agenda":"第25回品川区世論調査","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この世論調査は２年に一遍やっているということなのですけれども、この結果を区としてはどういうふうに評価して、これからの区政運営にどう活かしていくかというものが何かあるのであれば、教えてほしいと求めました。","respondent":"大澤広報広聴課長","answer":"世論調査の質問の項目につきましては、各所管から希望調査をいたしまして、広報広聴課のほうでヒアリングを行い、調整して項目を決めておりますので、このような調査がしたいという希望をした所管にこの調査結果を戻して、今後の施策の参考にするというのが基本的なスタンスです。","id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この世論調査をどう評価して、何にどうつなげていくということも考えていかなくてはいけないのではないかとか、その点についても伺いたいと思います。世論調査の中からどう検討課題にしていくのかというところがあるのか、その点についても伺いたいと思います。","respondent":"大澤広報広聴課長","answer":"生活環境、重点施策等は、その傾向というのはもちろん区として方向性を決めるときの参考にはなったと思います。もやはり１０年以上継続して聞いている、区民の方のご意向を調査して、活かしていくという姿勢は同じです。","id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"前回と比べても、３ページを見ても、ここら辺の区の施策に対しての評価というのが軒並み下がっているのではないかなと思うのです。だから、各所管からもこれを充実してほしいというのは多分出されているのではないかなと思うので、そういうところではいかがか尋ねました。","respondent":"大澤広報広聴課長、佐藤（憲）企画調整課長","answer":"経年でずっとやっている調査の傾向というのは、やはり区民の方の意向ということで重要なものだと思いますので、その点に関しては、経年でやっていることの意味というのは、区全体で検討していくべきことだと認識しています。広報広聴課長からご説明があったように、そこは素直に認めて、我々としても引き続き見ていきたいというところ。","id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"品川区のそういう施設の整備率というのは本当に低い状況だというところが、こういうところに出ている部分もあるのかなという思いが私はしています。そういう点では、こういう世論調査も受けて、ぜひ充実をさせていただきたいということで要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"須貝委員","kind":"確認","question":"今回、調査結果の概要を見せていただいて、再確認できてよかったと思います。意見だけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"吉田委員","kind":"質問","question":"前にも同じようなことを伺ったかもしれないのですけれども、こういう調査は、例えばクロスチェックみたいなものはされているのでしたか。今後また調査をするときに、その後の施策に活かすということも検討したらいいかなと思うのですが、その辺についてはいかがか尋ねました。","respondent":"大澤広報広聴課長","answer":"明日以降、区議会事務局を通して、議員の皆様のお手元に届くようにしています。期待することということでクロスチェックできるようになってありますので、報告書配布以降、またご確認いただければと思います。","id":"exchange-027"},{"speaker":"吉田委員","kind":"提案","question":"分かりました。では、私たちとしての今後の政策提案にも活かせるところがあったら、また何か伺うことがあったらとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/246119?Template=document&Id=2258#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":23913,"voices":71}},{"id":"r05-20230124-14","meetingId":"r05-cm01","date":"2023年1月24日","dateIso":"2023-01-24","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ２時１８分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を39件整理しています。","topics":[{"id":"topic-01","title":"新庁舎に関すること","agenda":"新庁舎に関すること","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"なるべく早く進めていただきたいと思うのですが、その中で何点か確認させてください。今日のこの変更の中で、委員長または委員の方にどのような形で変更があったということを伝えていくのか尋ねました。","respondent":"山下新庁舎整備課長","answer":"今回１０月１７日の答申案の段階から、各委員の皆様には郵送で変更点を含めてご案内をさせていただきました。策定に至る段階で答申からの変更点はこういったところがあるということは、別表をおつけする形で丁寧な説明に臨んでまいりたいと考えています。","id":"exchange-001"},{"speaker":"鈴木（真）委員","kind":"質問","question":"今新庁舎担当ではなく、全体的なまちづくりになってくるような部分も絡んでくると思うのですが、その辺はどのように考えていらっしゃるのか。これから今までのような検討委員会のようなものを作っていくのか、その点についても説明を求めました。","respondent":"山下新庁舎整備課長","answer":"どの部署がというところは、これから検討を進めていく必要があると思いますけれども、その部分にまずは注力していきたいというふうに考えてあります。","id":"exchange-002"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"それから、建物の本体についてちょっと確認させてください。今までちょっと確認し損なっているのですが、今この区の総合庁舎は、国の法務局の品川出張所、それから東京都建設局の第二建設事務所が入っています。","respondent":"大友新庁舎建設担当課長","answer":"国と都がそれぞれ入居するというか、一緒に建てていくということで、総合庁舎という形で調整を進めている状況です。入居につきましては、基本的にはそこまで大きく現在の庁舎と変わるような面積変更はないかと考えています。","id":"exchange-003"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"殊に今回は経費の件も出てきていますので、効率的な建物、そして全体的な開発に含めてやっていってほしいと求めました。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"あくつ委員","kind":"質問","question":"どういうスケジュール感なのかということが１つと、どういう方から、どのような内容を聴取することをお考えになっているのか教えてください。この３点伺います。","respondent":"山下新庁舎整備課長、大友新庁舎建設担当課長","answer":"私から第二庁舎に対する考え方の部分について１つお答えいたしますと、残さない、今後の検討が十分に必要だという考え方で捉えているものです。２点目の５２ページ、１つ前の委員のご質疑でもございましたとおり… この２か月、当初４月１日から設計に入れるようにという形で、プロポーザルは年度内に行う予定で考えておりました。基本設計と実施設計は、丸々１年ちょっと、年度をまたいでのスケジュールとなっているところです。","id":"exchange-005"},{"speaker":"あくつ委員","kind":"確認","question":"１番目の質問の第二庁舎のことについては、在り方についても改めて検討するという意味なのか、もう一回確認させてください。それと、そうすると、審査委員の中に大学の教授等の有識者が入るということではないという意味なのか尋ねました。","respondent":"山下新庁舎整備課長、大友新庁舎建設担当課長","answer":"現庁舎跡地および周辺のまちづくりを一体的に行うというような方針を少しお出ししながら、この基本計画の策定というところに至っている部分がありますので、在り方の部分についても今後この検討を進めていく必要があると認識しています。 学識経験者は審査委員の中に入らないという認識のとおりです。２点目の件ですけれども、ＣＭのほうのプロポーザルの進みですけれども、開始時期は基本設計の業者選定と同時期に開始を考えてあります。","id":"exchange-006"},{"speaker":"あくつ委員","kind":"質問","question":"いわゆる世田谷区なんかでは、そこから入っていたと思うのですけれども、関われない。設計段階ではどういったことをＣＭに、設計段階ではどのような関わりがあるのか、また、そのあたりについて最後に説明を求めました。","respondent":"大友新庁舎建設担当課長","answer":"設計業者の選定に関しましては、今回ＣＭといわれるコンストラクション・マネジメントの会社は関わることはありません。続いて２点目ですけれども、区に対して参考意見であったり、アドバイスをいただく形になってあります。","id":"exchange-007"},{"speaker":"渡部委員","kind":"質問","question":"これから先、新庁舎とは別に跡地を考えていく上で、まちづくりをしっかり区有財産の中でやっていくというイメージで捉えていいのでしょうか。そうでないと第二庁舎だけが問題点になってくると、そこはまた違うような気がするのですけれども、考え方を説明を求めました。","respondent":"山下新庁舎整備課長","answer":"今ご質問がございました、第二庁舎に限定した捉え方なのかです。第４回定例会で差し上げているご答弁の中では、少し広町２－１－３６だけではないところの視点というのはやはり必要になってこようと認識しています。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"なぜ答申を受けた後、策定委員も知らない中でこういう形で第二庁舎を残すということが変更になったのか、なぜなったのか。そして、それはどこでどんな検討がされたのか、この点についてまず伺いたいと思います。","respondent":"山下新庁舎整備課長","answer":"今回、１２月１９日に答申をいただきましてから策定に至る段では、実際にどういった形が考えられるのかということを種々議論してまいりました。今回、第４回定例会の中で、今回そういった内容をこの整備計画策定の段で反映されたものと認識しています。","id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"この庁舎跡地周辺の一体的なまちづくりというのは、今回、答申を受けた後に初めて出てきた考え方なのでしょうか。なぜ今の段階で突然それが出てきて、そして、品川区の担当部署だけでこういうことが決定されたということなのか、その確認をお願いしたいと思います。","respondent":"山下新庁舎整備課長","answer":"答申から策定に至るまでの変更点につきましては、実際に昨年８月にパブリックコメントを実施しまして、説明会形式の説明会等を実施する中でも。","id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"それで、残すか残さないかも含めて今後検討する方向なのか、その点の確認をお願いしたい。「区民負担軽減」というところは官民連携のＰＰＰという手法ですか、今回のこういう変更点になったのか、その点についても伺いたいと思います。","respondent":"山下新庁舎整備課長","answer":"今回、計画策定に至る中では、答申を経て、その後決裁を計画の策定に向けて進めていく中で、議論を進めてきたものです。実際に区民負担を軽減し、今回、この新庁舎の整備が滞りなく進んでいくように取り組んでいくというところは変わらぬものとして１つ柱としてある中で。","id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"公表してこれから学識経験者の意見も伺って、契約をする時期というのが何月ごろなのかというところのスケジュールについても伺いたいと思います。こちらの基本設計の業者と、それぞれどういうスケジュールなのかについて、もうちょっと詳しくお願いしたいと思います。","respondent":"山下新庁舎整備課長、大友新庁舎建設担当課長","answer":"１点目の策定委員の皆様への説明のところについて私のほうからお答えいたします。今回、品川区新庁舎整備基本構想・基本計画策定委員会の皆様に説明していく、しっかりと説明責任を果たしていきたいと考えています。現在準備を進めている段階でございまして、今のこの時点でいつという形でのお答えは避けさせていただければと考えています。","id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それなのに募集要項がいつごろ出されるか、公表されるかということもお答えいただけないのか、その点を伺いたいと思います。それはおおよそというところで言えるのではないかなと思うのですけれども、教えてほしいと求めました。","respondent":"大友新庁舎建設担当課長","answer":"しかしながら、まだそのスケジュールの決定が取れているところではございません。今現在、６月中に契約をするとなりますと、２月中には実施要領の公開をしなくてはならないと考えているところです。","id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"第二庁舎がこういう形でこれまで残ると言っていたものが、「残る」という文言が全て消された形になったわけです。森澤区長は、そういう方向でも準備をされているのか、その点について伺いたいと思います。","respondent":"山下新庁舎整備課長","answer":"今ご質問いただきました、この後の跡地のほうの委員会につきましては、区長のほうでそのようなお話をされてありますので、今後どのような形で進めていくかというのは、内部でも検討が必要だろうと考えています。","id":"exchange-014"},{"speaker":"松本委員","kind":"質問","question":"今の第二庁舎のところですけれども、これは設置要綱とか諮問文を見ると、あくまでも「新庁舎」となっているかと思います。必ずしも残っている今の本庁舎と第二庁舎について、このあたりの事実関係はどういうふうに整理すればいいのでしょうか、お願いします。","respondent":"山下新庁舎整備課長","answer":"新庁舎にどういった機能が必要なのか、新庁舎のことについて考えていただきたい場であるということはご指摘のとおりかと存じます。文言上、諮問の事項として直接に関わるものではございませんけれども、関連する事項としては一体として捉えているところがあります。","id":"exchange-015"},{"speaker":"松本委員","kind":"質問","question":"その場合というのは、例えばまた新たに要綱を作って、こういうことを諮問していくのですという形で進めていくという理解でよろしいでしょうか。お願いします。","respondent":"山下新庁舎整備課長","answer":"今回諮問事項についての答申を頂戴したということで、この委員会が終了している、廃止になっているです。まだこれから検討という中で、必ずしも委員会設置の要綱という形ではなくて、また新たな形が考えられるのかなというふうに捉えてあります。","id":"exchange-016"},{"speaker":"松本委員","kind":"質問","question":"どういうふうに跡地を検討していくのかということを、こういう方針でいきますよというところは、大体いつごろに示される可能性がありそうでしょうか。お願いします。","respondent":"山下新庁舎整備課長","answer":"これから令和５年度を迎えていく中にありまして、予算をしっかりつけていかないとそういった事業は進められないというところが裏面としてあろうかと思いますので、予算の形で出ていくという形が想定されるのかなと考えています。","id":"exchange-017"},{"speaker":"塚本委員","kind":"質問・要望","question":"別紙３の５５ページの財源計画のところを質問させていただきたいのですけれども、「区民負担軽減の方策」というところの一応確認ですが、まずこういう理解でいいのかということを確認させてください。","respondent":"山下新庁舎整備課長","answer":"ご質問いただきました区民負担軽減に対する考え方です。使った、もしくは次の時代の投資に振り向けていくという発想から、このような記載になっているものと考えています。","id":"exchange-018"},{"speaker":"塚本委員","kind":"意見","question":"一応公会計的な見方をすると、１回壊してしまいましょうというような話になったとすると、多分減価償却というところでの損失みたいなものが出てくる。だから、そこは大変に理解できるところなのですが、ぜひそういった視点を持って検討してほしいと求めました。","respondent":"山下新庁舎整備課長","answer":"昭和４３年で、今年で築５５年を迎えるといったところから、新庁舎の必要性ということで区民の皆様にもこの間ご説明を申し上げてまいりました。今、委員からご指摘の点を踏まえた、やはり一体としてといいますか、より広い視点での検討が必要と考えています。","id":"exchange-019"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"多分東京都のスタートアップ事業というのですかね、そういうところまで活用していくということが視野に入っているのではないかなと思うのですけれども、わかる範囲で教えていただけたらと思います。","respondent":"山下新庁舎整備課長","answer":"現庁舎の広町の位置を考えたときに、やはり３６０度見渡せば、こういった部分が周辺というような広い捉え方をしています。東京都のほうが実施されているものですので、都の事業に何か参画するとか、そういった考えがあるというところは耳にしてございません。","id":"exchange-020"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"そうすると、周辺というのは、大井町側もですか、ということですよね。そこら辺はイメージできるようにしていただけたらなと思うのですが、今の段階では全くないということでしょうか、伺います。","respondent":"山下新庁舎整備課長","answer":"庁舎の敷地を含めたところの大井町駅周辺地域まちづくり方針というところで言いますと、今のこの庁舎の場所を中心地点として考えたときには。","id":"exchange-021"},{"speaker":"鈴木（真）委員","kind":"確認","question":"もう一度この確認ですが、「保健所／保健センター」が約２,０００m2ですが、この中に第二庁舎は入っているのですか。その確認をさせてください。","respondent":"大友新庁舎建設担当課長","answer":"新庁舎の建設想定規模の中に、第二庁舎は入っております。今、第二庁舎に入っていて、新庁舎に入ってくる課とか、組織とかの想定面積は入ってあります。","id":"exchange-022"},{"speaker":"鈴木（真）委員","kind":"確認","question":"建物自体、第二庁舎の建物は、当初は残す形ですよね。総体、約６万m2の中に第二庁舎の部分は入っているのか、それともこれは最初から計算していなかったのか、そこをちょっと確認したい。","respondent":"大友新庁舎建設担当課長","answer":"この新庁舎の６万m2の中に、第二庁舎の約１万２,０００m2は入っておりません。","id":"exchange-023"},{"speaker":"鈴木（真）委員","kind":"確認","question":"要するに壊しても影響、新庁舎を建てれば当初の計画どおりで、第二庁舎を壊しても面積的にこの６万m2で足りるということでよろしいですね。その確認だったのです。","respondent":"大友新庁舎建設担当課長","answer":"今回の基本計画の中でも一部検討していくというところで、全く影響がないという形でもなく、調整事項になるかというところで考えております。","id":"exchange-024"},{"speaker":"鈴木（真）委員","kind":"質問","question":"第二庁舎をもし壊すというときには、新庁舎だけでは足りなくなってしまうのではないかというところが出てくるような気がするのですけれども、その辺はどう考えたらいいのか尋ねました。","respondent":"榎本新庁舎整備担当部長","answer":"特に、「災害対応従事者の休憩・宿泊」、「協定先や支援団体車両の駐車」というのを災害時には第二庁舎で担ってもらいたいと思っていました。","id":"exchange-025"},{"speaker":"鈴木（真）委員","kind":"確認","question":"前も確認したのですけれども、防災の駐車場がないというお話もあったと思うのですが、確かにその辺は必要な部分があると思うのです。そこは大丈夫なのでしょうねという確認をしたい。","respondent":"大友新庁舎建設担当課長","answer":"こちらの検討機能というところがまだ課題として残っているところではありますけれども、こちらは約６万m2とさせていただいているところです。こちらのほうに盛り込むことで、問題なく検討は進められるかと思ってあります。","id":"exchange-026"},{"speaker":"鈴木（真）委員","kind":"確認","question":"これから設計、プロポーザルを受けていく段階で、６万m2ということで設計してくるのだと思うのですよね。だけど、何か約６万m2で足りなくなってくるのは、最後にもう一回そこの確認をさせてください。","respondent":"大友新庁舎建設担当課長","answer":"必要な機能を決めて、この６万m2というところは、必ず６万m2ぴったりでなくてはならないというところではございません。基本計画に沿った中身の必要な機能を盛り込んで設計をしていく形になりますので、基本的にはこの設計発注で問題ないかと考えています。","id":"exchange-027"},{"speaker":"渡部委員","kind":"確認","question":"６万m2でよかったのですかという中で、設計ができて、また設計を直さなければならないということになりませんかということを確認したかったのです。全くそこが使えない状況で、では本庁舎の６万m2というパイの中で全てが収まるのですか、大丈夫ですよねという確認です。","respondent":"榎本新庁舎整備担当部長","answer":"それについては、これから設計をしながら都市計画を定める段階で、一番は容積率がどれぐらいかというのを調整しながら、全部入れ込む形できちんと機能できるのかどうか、そういうのを確認しながら進めていく予定です。","id":"exchange-028"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"あらゆるところで区民参加というのをしっかり位置づけているというところが、本当にすばらしいと思って、伺ってきました。区民からの意見も取り入れて、区民のための庁舎を造っていくというところで、ぜひ活かしていただきたいなと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"各団体の皆さん、そして入られていない皆さんも含めて、ぜひきめ細かく声を聞く場を作っていただきたいなと思います。区民への説明というのを繰り返しやっている、区民へのさらなる周知を広げていただきたいし、私たちも含めて広げていかなければと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"}]},{"id":"topic-02","title":"特定事件調査のまとめ","agenda":"特定事件調査のまとめ","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"意見","question":"この重点項目というのは、この９項目の中の１つにマイナンバーカードの普及促進というのが入っているのですよね。前倒しで進めていくということに対しては、共産党としては賛成できないので、ちょっとこのところはとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"表現を。そういうふうにしていただければと思うのですけれども、それが入っているとなると削除していただきたいという意見を申し上げたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"あくつ委員","kind":"質問","question":"それはいろいろな捉え方ができるでしょうから。そんなことを言っていたら、全部削除しないと無理になってしまうので、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"渡部委員","kind":"意見","question":"途中まで手を挙げかけたら、あくつ委員から手が挙がったのですが、全く同感でございまして、あくまでも全てを前倒しだとか何だとかというのではなくて、「可能なもの」というような注意記載が入っていますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"「可能なもの」というのは、何て言うのですかね、誰が可能だというふうに判断するか。共産党が反対しているから、「可能なものについては」ということでは、私たちの思いは反映されないのではないかなと思うのですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"あくつ委員","kind":"質問","question":"そういうことを言っていたら、まとまらないですよ、はっきり言って。配慮に気づかれたのかどうかわかりませんが、先ほど申し上げたとおりですが、まだそれでもご主張されるということか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"実施という方向を打ち出していますので、それをあえて前倒しで、ここの委員会として出さなくてもいいのではないかなと私は思います。「可能なもの」というところだと、マイナンバーが除かれるという表現には捉えられないと思いますので、それはご検討いただけたらと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-037"},{"speaker":"渡部委員","kind":"質問","question":"ですから、マイナンバーに対して配慮するのであれば、「可能な限り」。今、主張されているところの副委員長もいらっしゃいますので、そこはお任せいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"共産党としても今の委員長の提案どおりで、まとめはしないという方向でいいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/642035?Template=document&Id=6144#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":24514,"voices":90}},{"id":"r05-20230125-19","meetingId":"r05-cm01","date":"2023年1月25日","dateIso":"2023-01-25","committee":"災害・環境対策特別委員会","time":"午後 １時００分～午後 ３時４３分","status":"正式会議録","sourceType":"formal","overview":"災害・環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を50件整理しています。","topics":[{"id":"topic-01","title":"防災に関すること","agenda":"防災に関すること","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"でも、これは本当に命に関わる大事なことですから。防災訓練において、幅広い世代で訓練参加率が向上していくことにもつながるというふうに私は思ったのですけれども、そこら辺はいかがか尋ねました。","respondent":"平原防災課長","answer":"その方々が災害時には避難所運営会議という形で組織の名称を少し変更して、何か区が決めてやるというよりは、皆さんで考えていただいて行動する。","id":"exchange-001"},{"speaker":"おくの委員","kind":"意見","question":"大分分かりました。そうやって伝えていかないと、やはり実際になったときに慌ててしまいますので、ぜひよろしくお願いいたしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問","question":"質問なのですけれども、この改定の中身は何かと伺いたいと思います。そして２つ目ですけれども、何か違うものなのか、そこを伺えたらと思います。","respondent":"平原防災課長","answer":"先ほど資料のご説明の中で触れさせていただきましたとおり、こちらで「個別避難計画」の作成が各市区町村単位での努力義務とされたところです。","id":"exchange-003"},{"speaker":"中塚委員","kind":"確認","question":"確認ですが、在宅での避難生活への支援と、その両方が含まれているという理解でよいのか伺いたいと思います。どういう仕組みが必要かということなのですけれども、そうしたことが必要だと思うのですけれども、それぞれいかがか尋ねました。","respondent":"平原防災課長","answer":"様々な情報の支援、そういったところでしっかり対応するということを考えてありますので、それぞれの特性に応じた形での支援ということは。説明会のようなものということは、防災計画の説明など、引き続きそういった取組を今後も進化させていきたいというふうに考えてあります。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"１点だけ伺いたいのですけれども、町会や自主防災避難所連絡会議など、地域の皆さんがスキルをアップしてからという話がありました。当事者が参加できるようにしていただきたいと思うのですけれども、その点、いかがか尋ねました。","respondent":"五十嵐災害対策担当課長","answer":"一応、仕組みづくりをしつつ訓練参加を促したいと考えています。そのスタートとして、この９月に始まる地区総合防災訓練を目途に進めているところです。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ障害者団体のヒアリングを、もっともっと対象を拡げて、繰り返し行っていただきたいと思うのです。実態や要望を受け取る、防災の部隊も一緒に参加していただいて状況を把握していただきたいと思うのですけれども、最後にいかがか尋ねました。","respondent":"平原防災課長","answer":"個別避難計画を作成するに当たりましては、こちらについては、そういった方々のお話を十分聞いてから作成されていくものというふうに考えてあります。","id":"exchange-006"},{"speaker":"松澤委員","kind":"質問","question":"避難の考え方で、在宅避難の定義といいますか、見極め、要は、在宅中に地震がありました。あくまでも自己判断なのか、まず、そこら辺を説明を求めました。","respondent":"平原防災課長","answer":"まずご本人に考えていただくのですが、公的な判定がされていくような形になりますので、まずはご自身で見ていただく。例えば、よく分からないから不安だというような場合には、そういったところで幅広に考えていただいて避難していただくものと考えています。","id":"exchange-007"},{"speaker":"松澤委員","kind":"質問","question":"心配だったら問い合わせていただく、そういうやり方で今後もやっていくのか、そこを説明を求めました。","respondent":"平原防災課長","answer":"例えば避難所でありますとか、病院であるとか、大勢の方々が公的に集まるようなところを優先して行っていく形になります。住家被害認定が先行するような場合も十分考えられると思いますので、例えば、そういうような形で考えていただければというふうに思ってあります。","id":"exchange-008"},{"speaker":"松澤委員","kind":"質問・要望","question":"やっぱりそこら辺の周知というのですか、まずは自分たちでしっかり見て確認してくださいという、そこら辺はしっかりしてほしいと求めました。その方たちの活用というのですか、地域防災力を底上げしていくということも１つの考えかと思うのですけれども、そこら辺を説明を求めました。","respondent":"鈴木都市計画課長","answer":"年１回、そうした、いざ発生した場合の機敏に動ける体制構築を毎年整えているというような状況です。それが割り当てられて、速やかに応急危険度判定を行っていく、そうした体制が今整えられているという状況です。","id":"exchange-009"},{"speaker":"松澤委員","kind":"質問・要望","question":"前に台風１９号、危険だから学校まで運んでほしいと声をかけてくれた５人の方は、みんなお一人の高齢者だったのです。助けてほしい人たちは、より一層のそういう本当に必要な方の周知というのですか、本当に今まで以上に頑張ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"たけうち委員","kind":"質問","question":"高齢者が４,７００件強、障害者が１４５件終わっているというお話ですが、その辺の状況が分かれば説明を求めました。","respondent":"菅野高齢者福祉課長、松山障害者支援課長","answer":"高齢者の個別避難計画について、ご質問にお答えします。本人の同意や避難場所、あと支援者等の調整を今しているところで、本計画の移行を進めているというところが現状となっております。 障害者の方の個別避難計画についてです。障害者の方につきましても、入所の方は除いて在宅の障害者の方を対象としております。","id":"exchange-011"},{"speaker":"たけうち委員","kind":"質問","question":"在宅ということで分かりました。聞き取りの中でそういうご希望をされる方がどれくらいいらっしゃるかということが分かればと思ったので、もし分かれば説明を求めました。","respondent":"松山障害者支援課長","answer":"現在、１４５人の障害者の方に同意を得て進めております。そのうち９割の方が在宅避難ということで、福祉避難所というよりは、ご自分の家で安心して過ごせるというふうに思われている方が多いです。","id":"exchange-012"},{"speaker":"たけうち委員","kind":"質問","question":"申し訳ない言い方なのですけれども、大きい地震が来ると、自宅がちょっと難しいのではないかという方も中にはいらっしゃるかもしれないです。その辺まできめ細かくはなかなかすぐはできないのかなと思うのですけれども、そこも大事かなと思うのですが、その辺はどのような感じなのか尋ねました。","respondent":"松山障害者支援課長","answer":"あるいは、何階建ての何階にお住まいなのかということも確認いたしまして、まずは第１回目の作成です。相談支援員が関わっているものですから、防災地図、どうしていくかをきちんと同意を取った上で計画を再編するということになろうかと考えております。","id":"exchange-013"},{"speaker":"たけうち委員","kind":"質問","question":"分かりました。マンパワーですか、立場とか、それはもう決まっているということでよろしいか尋ねました。","respondent":"松山障害者支援課長","answer":"では、どうしますかという問題が生じてきますので、なかなか１回で全ての完璧な計画をつくるのは難しいと考えています。避難誘導支援者の部分も含めまして、ご本人が安心できるように、モニタリングの機会を通じましてお話をしていきたいと考えています。","id":"exchange-014"},{"speaker":"新妻委員","kind":"質問・要望","question":"それに関しての見解をお伺いいたします。そのことをまずお伺いします。","respondent":"平原防災課長","answer":"続きまして、ペット避難ですが、ペット避難については、私ども、重要なものと認識しております。私どもは全地域で進められるように、現状というか、広まっていくようなところを今後とも進めてまいりたいと考えています。","id":"exchange-015"},{"speaker":"新妻委員","kind":"質問・要望","question":"もう１つ、防災訓練についてお伺いいたします。区の助言といいますか、何かアドバイス的なところをほしいと求めましたが、いかがか尋ねました。","respondent":"五十嵐災害対策担当課長","answer":"１つの区民避難所で複数の町会が連携して訓練を実施しているところのリーダーシップ性についてのお話なのですけれども、報告事項で、先ほど。どういうような形で複数の町会が連携してやっていけるのか、また、今から課題解決に向けて進めていきたいというふうに思っております。","id":"exchange-016"},{"speaker":"新妻委員","kind":"質問","question":"すみません、それではまた後ほど報告をいただいて、お聞きしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"田中委員","kind":"質問・要望","question":"当事者の方たちも安心するのかなと思うので、ぜひ進めてほしいと求めましたが、見解を伺います。今、品川区としてこういった姿勢を持っていますよといった周知があればいいのかなと思うのですが、そこの考え方についても伺いたいと思います。","respondent":"平原防災課長","answer":"まず、まずは地域での取組をしっかりと考えていただいて、全ての地域で行われるということを前提に進めてまいりたいと思っています。そういったところの考え方もしっかりと出しながら、そういったところについても考えてまいりたいというふうに思ってあります。","id":"exchange-018"},{"speaker":"田中委員","kind":"質問・要望","question":"ただ、計画を基にした訓練の状況などは、今はどうなっているのでしょうか。そういった説明とかだけでもいいので、ぜひ関心があるよということを示せるような周知はしてほしいと求めましたが、いかがか尋ねました。","respondent":"平原防災課長","answer":"要配慮者利用施設における訓練の実施ですけれども、こちらにつきましても、１７１施設全てで行われているということで私ども把握しています。現在、今後そういったことも含めまして、さらに周知はどういったものが効果的か考えてまいりたいというふうに思っております。","id":"exchange-019"},{"speaker":"つる委員","kind":"質問・要望","question":"消火隊のポンプの口径というのですか、これの口径を改めて教えていただきたいのと、これは区から支給していただいているものかどうかも改めて説明を求めました。","respondent":"五十嵐災害対策担当課長","answer":"消火の関係で東京消防庁にも聞いてみたのですけれども、後継はまだないというようなことで聞いております。一部の外国製の商品で、それは正式に採用されているものではございませんので、まだ決まっていないというのが実情です。","id":"exchange-020"},{"speaker":"つる委員","kind":"質問","question":"私は、大きさというのですか、口の径です。それと、今ご答弁いただいた後継というのはどういう意味か、改めて、不勉強なので説明を求めました。","respondent":"五十嵐災害対策担当課長","answer":"Ｃ級可搬ポンプの口径につきましては、個別に回答させていただきたいと思います。Ｄ級可搬ポンプの後継が、今、なくなっているので、Ｃ級可搬ポンプは現在も継続して生産されてあります。","id":"exchange-021"},{"speaker":"つる委員","kind":"確認","question":"前提の確認だったのであれなのですが、これがなかなか高齢になってくると非力になってきて難しいという、やりづらいという声を伺ったのです。地域の防災力向上に資していただいているということを伺う中で、１つ、この辺りについてお考えがあれば説明を求めました。","respondent":"五十嵐災害対策担当課長","answer":"一度、消防団の方々にもガンタイプノズル、消防署と連携して活用してみてもらってはどうかと、感想を逆に聞きたいというふうに思います。一度、消防団の方にも手にしていただければなというふうに、それで逆に感想を聞きたいなというふうに思ってあります。","id":"exchange-022"},{"speaker":"つる委員","kind":"質問・要望","question":"正に使い勝手等を確認いただきながら、支援だけではなくて、そういう場面もありました。ですから、改めてそういうことも踏まえて、防災区民組織の方へのガンタイプノズルの支給の検討についても併せてやってほしいと求めました。","respondent":"五十嵐災害対策担当課長","answer":"改めてガンタイプノズルの区としての支援を検討していただきたいというようなお話のお答えなのですけれども、毎年消防団に補助金を出していますので。ただ、東京消防庁から配布してもらうというようなことも１つ手がありますので、両方の線で考えていきたいと思っています。","id":"exchange-023"},{"speaker":"須貝委員","kind":"確認","question":"区民避難所５２か所、これが出されたら、皆さんこっちに目がいってしまうではないですか。安全だと確認したら、その辺について、どのようなお考えがありますか。","respondent":"平原防災課長","answer":"避難所のところに矢印が引いていなくて、そのまま自宅にいてくださいといったことは、まず大前提であると考えています。私どもも最上位に置いているところですので、そういったところは今後ともしっかり周知してまいりたいというふうに考えてあります。","id":"exchange-024"},{"speaker":"須貝委員","kind":"質問","question":"ここの右側に大きく明記して、区民の皆さんに協力してもらうということがやはり第一だと思うのですが、どうなのですか。町会でも、ご近所の方でも、運び出せるような機材というのは１軒１軒にあるのか尋ねました。","respondent":"平原防災課長","answer":"ご説明のとおり、今後ともそういったところも利用しながら、しっかり周知してまいりたいと思ってあります。そういったところもご説明していますので、なかなか全ての避難行動要支援者のところに、そういったものがない状況でも着実に支援できるように。","id":"exchange-025"},{"speaker":"須貝委員","kind":"質問","question":"その中でもちろん常時使われている方もいらっしゃるから、実質在庫としては２台か３台というような状況です。その辺について、もし何かありましたら説明を求めました。","respondent":"平原防災課長","answer":"避難支援を行う際の資機材ですけれども、物干し竿を利用した毛布担架、こういったものも１つ有効な手段になるかなと思います。避難行動要支援者の支援に当たるときには、車椅子、まずそういう考え方の下に始めさせていただいているところです。","id":"exchange-026"},{"speaker":"つる委員","kind":"意見","question":"せっかくご答弁いただいたので。防災区民組織の配備も、段階を踏んでという形になろうかと思いますけれども、ぜひ積極的な検討をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"田中委員","kind":"質問・要望","question":"どういう基準でそうなったのかという部分を伺いたいのと、朝の７時の時点で警報が出ていたときに、そこで警報が出ていないと判断が分かれるのです。区内の学校については、こういう判断をしましたよというものをお知らせの段で出してほしいというのが、要望も兼ねて伺いたいと思います。","respondent":"平原防災課長","answer":"さらにその中でも令和元年の台風１９号、昨日、特段の自主避難施設開設というようなところには至りませんでした。何らかの気象警報と連動しているやには聞いてありますので、そういったところのご意見についてはお伝えさせていただきたいというふうに思います。","id":"exchange-028"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"これは高齢者のほうですか、今、合意なども得られて運用できるような形になっているというのは何件あるのかということを伺いたいと思います。これがどういうことかということと、本当にこの１週間の間の体制ができていない、そこのところを確認させていただきたいと。","respondent":"菅野高齢者福祉課長、平原防災課長、松山障害者支援課長","answer":"取り組んでいる最中ですので、何件というのは、ちょっとお示しできないような状況になっております。避難するときの支援者や避難方法… 区の初動対応体制のところについてですけれども、計画自体は、当然のことながら確立しています。そういった方々と避難所の役員となられる防災区民組織の役… ご本人との、なかなか障害の方は同意を得るのが非常に難しいかと考えていますので、１人ずつ丁寧に進めていきたいと考えています。","id":"exchange-029"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"そこも１つ大きな課題かと思いますが、やはり自宅で、計画作成に向けてもしっかり説明をして理解を得ていっていただきたいというふうに思います。これから初期の１週間のところで、これが実際の支援していく、ぜひそういったところでしっかり進めていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"}]},{"id":"topic-02","title":"令和４年度品川区地域防災計画の修正","agenda":"令和４年度品川区地域防災計画の修正","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"そこについて区の見解を伺いたいと思います。そういう位置づけに変更することが必要ではないかと、そのための検討が必要ではないかと思うのですけれども、いかがか尋ねました。","respondent":"平原防災課長","answer":"まず、ちょうど１００年前の関東大震災の地震火災で多くの方がお亡くなりになったということを契機に、全てのところはオープンスペースです。現状では、そういったところで広域避難場所の活用を考えているところです。","id":"exchange-031"},{"speaker":"中塚委員","kind":"質問","question":"居住スペースだったり、そういう検討を進めていくことが必要になってくるのではないかと思うのですけれども、改めて伺いたいと思います。３か月後、こうした工夫も品川区地域防災計画の修正の中で検討を進めていくべきだと思うのですけれども、それぞれいかがか尋ねました。","respondent":"平原防災課長","answer":"進めているところですので、避難者数の変更等々も含めて、現状の区有施設の勢力の再検証を行っているところです。現状、私どものところで全ての広域避難場所の運営方法を検討しておりますので、そういった中で考えてまいりたいというふうに思ってあります。","id":"exchange-032"},{"speaker":"中塚委員","kind":"質問・要望","question":"孤立だったり、支援が行き届かなかったり、様々な問題を解決する１つの考え方かというふうに思って述べさせていただきました。検討していただけたらと要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"田中委員","kind":"質問・要望","question":"１点伺いたいのですけれども、品川区地域防災計画の修正ということで、今回の修正でもやはりそれは改善はされないのでしょうか。２０２０年に私が一般質問をしたときには、そういった具体的な航空機が街中で墜落したときの、そこのところについて伺いたいと思います。","respondent":"平原防災課長","answer":"様々な事故が考えられると思いますが、そのような形で考えさせていただいているところですので、そういう位置づけをさせていただいているところです。","id":"exchange-034"},{"speaker":"田中委員","kind":"質問・要望","question":"残念ながらある状況なので、具体的に修正をしていただきたいと、加筆してほしいと思います。強く要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"これを分かりやすいように地図などをぜひつけていただきたい、改善を求めたいと思いますが、いかがでしょうか。やはりこれは命を守るためにしっかり周知をすることが必要だと思いますけれども、いかがか尋ねました。","respondent":"平原防災課長","answer":"そこを対象としていくものですので、ハザードマップと併せまして、しっかりと説明してまいりたいと思ってあります。仮に避難基準といいましょうか、避難指示などを発令するときにも、付近住民に対して分かりやすくしていきたいと思ってあります。","id":"exchange-036"}]},{"id":"topic-03","title":"防災地図の改定及び全戸配布","agenda":"防災地図の改定及び全戸配布","exchanges":[{"speaker":"中塚委員","kind":"提案","question":"もう１つは、障害がある方への防災地図情報の提供の仕方、ここをどう考えているのか、どうしているのかを伺いたいと思います。説明会も１つの手法だと思いますし、全部の人に配る必要はないわけですから、どのように考えていらっしゃるのか伺いたいと思いますとの意見を述べました。","respondent":"平原防災課長","answer":"私ども、地域の防災の中核となります防災区民組織本部長に地域別にご説明させていただきたいと考えていますので、１３地域に関しては。これを広げるような意味で、説明会というような形ではないのですけれども、動画を作成していきたいというふうに考えてあります。","id":"exchange-037"},{"speaker":"中塚委員","kind":"質問・要望","question":"１つの輪もできるし、私は力になると思いますので、ぜひ検討いただきたいと要望したいと思います。戸別なのか、説明会みたいな全体なのか、手法も検討していただきたいと要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"新妻委員","kind":"質問・要望","question":"作成をして全戸配布をしていただくに当たっては、これはシルバー人材センターの方にお願いをするものでしょうか。それともう１点が、こういう配布をしますよということの周知がされるのか、そのことを説明を求めました。","respondent":"平原防災課長","answer":"裏面のところに、防災地図が届きましたというような形で工夫して、一見してすぐ分かるような形でお配りさせていただきたいと考えています。配布の前段階での説明ですが、配布前に地域の防災区民組織の本部長にはご説明してまいりたいというふうに考えてあります。","id":"exchange-039"},{"speaker":"田中委員","kind":"質問・要望","question":"その周知方法で、こういったものを今度発行しますみたいなことをＳＮＳのほうでも発信をしていただきたいということを求めたいと思います。ＹｏｕＴｕｂｅでの公開というのは確認したのですけれども、ぜひ説明会は実施してほしいと求めましたが、いかがか尋ねました。","respondent":"平原防災課長","answer":"ただ一方で、こちらの資料のデジタル化についても検討させていただいて、こういったところについては進めてまいりたいと思ってあります。","id":"exchange-040"}]},{"id":"topic-04","title":"令和４年度区内一斉防災訓練等の実施結果","agenda":"令和４年度区内一斉防災訓練等の実施結果","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"品川区では、そういった形での啓発ということは考えていらっしゃらないでしょうかということをお伺いしたいと思います。より親しみを持って見てもらえるのではないかと私は思ったりしたのですけれども、その点、いかがか尋ねました。","respondent":"五十嵐災害対策担当課長","answer":"今年は特に関東大震災から１００年の位置づけの年ですので、訓練の必要性、多くの方に参加していただくような形でやっていきたいと考えております。引き続き、ＳＮＳやデジタル動画等を通じて、訓練参加と訓練啓発を進めていきたいと考えておりますので、よろしくお願いします。","id":"exchange-041"},{"speaker":"田中委員","kind":"質問","question":"保護者数が０ということで、特にこの２番の避難所訓練を行った学校、どう考えたらいいのかというところを伺いたいと思います。","respondent":"五十嵐災害対策担当課長","answer":"加えて、隔年で児童・生徒が加わる年と、加わらない年という形で訓練を進めております。ですので、昨年は加わらなかったので、今年の１２月には、学校と連携して多くの児童・生徒が参加する訓練を実施していく予定です。","id":"exchange-042"},{"speaker":"田中委員","kind":"確認","question":"町会・自治会参加者数の中に、児童・生徒とか保護者も含まれているのかと思ったのですけれども、そうではないということですか。そこの部分も確認させてほしいと求めました。","respondent":"五十嵐災害対策担当課長","answer":"町会・自治会参加者数のところは、純粋に町会・自治会の方、今回は人数制限の中でやっていますので、基本的には役員系の役付きの方が多かったかなと思われます。","id":"exchange-043"},{"speaker":"田中委員","kind":"確認","question":"１年ごとに子どもたちが参加したり、しなかったりということがあるというのは確認できました。保護者の数が０なのは、毎年なのか尋ねました。","respondent":"五十嵐災害対策担当課長","answer":"保護者の欄が０なのは、全部町会・自治会員としてカウントしています。","id":"exchange-044"},{"speaker":"中塚委員","kind":"質問・要望","question":"品川区が確認をしたり、品川区はどういう関わりを持っているのか、その点を確認させてほしいと求めました。しっかり位置づけていただきたいと思うだけに、その点、いかがか尋ねました。","respondent":"五十嵐災害対策担当課長","answer":"１点目、今回に関しては、こちらで避難所訓練で実施した内容をぜひやってみてくださいというご提案をさせていただきました。ぜひ一旦やってみてはいかがでしょうかというような形でご提案させていただいて、了解をいただき、訓練に採用されたというような流れになります。","id":"exchange-045"},{"speaker":"中塚委員","kind":"質問・要望","question":"「どうですかね、訓練の準備とかやってみて」と伺うと、なるほどなと思ったのです。それぞれの訓練内容や感想や状況を把握しているわけですから、やっている側からすると、今後につなげていただきたいと要望しておきたいと思います。","respondent":"五十嵐災害対策担当課長","answer":"それについても今までコロナ対応の避難所運営ということでやってきたのですけれども、では、どのようなテーマにしようかということは検討中です。ぜひそのテーマにも沿って訓練していただければなと考えております。","id":"exchange-046"},{"speaker":"松澤委員","kind":"質問・要望","question":"そういうものは町場の協議会でやるわけではないですか、いろいろな意見を落としていただきたいなということが１個と、多分初めてですよね。これは１人だけできる人がいても駄目だし、難しいところだと思うのですけれども、そこら辺のご見解を説明を求めました。","respondent":"五十嵐災害対策担当課長","answer":"訓練の進め方が悪かったという学校が２校ございまして、今検討しているところですので、やっていきたいと考えています。それが途絶してしまうと、その区民避難所が孤立化してしまうということを認識していただいた上で訓練に参加してもらうようにしていただきますので。","id":"exchange-047"},{"speaker":"松澤委員","kind":"質問・要望","question":"おろすではないですか、どう変わったのかとか、いろいろご報告をいただけるとありがたいと思っています。本当に和気あいあいとやられていて、私は非常によかったなという感想を持っていますので、こういったことをしっかり続けてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"}]},{"id":"topic-05","title":"特定事件調査のまとめ","agenda":"特定事件調査のまとめ","exchanges":[{"speaker":"田中委員","kind":"意見","question":"（２）の障害者等への情報発信についてのところで、特に海外の方たちへの発災時の情報発信はとても重要だという議論が多分あったと思うのです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-049"},{"speaker":"田中委員","kind":"質問・要望","question":"６行目のところに、意識もすごく高まっているところですし、どこかしらにリデュースも入れていただきたいなということを要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/924121?Template=document&Id=6630#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=19&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":55095,"voices":145}},{"id":"r05-20230126-10","meetingId":"r05-cm01","date":"2023年1月26日","dateIso":"2023-01-26","committee":"議会運営委員会","time":"午後 １時００分～午後 １時１３分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/881920?Template=document&Id=5496#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":4398,"voices":21}},{"id":"r05-20230220-10","meetingId":"r05-cm02","date":"2023年2月20日","dateIso":"2023-02-20","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時２６分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を14件整理しています。","topics":[{"id":"topic-01","title":"議事日程(1)(2)(3)および追加議事日程","agenda":"議事日程(1)(2)(3)および追加議事日程","exchanges":[{"speaker":"石田委員","kind":"質問・要望","question":"総務委員会に付託予定の請願で、「消費税インボイス（適格請求書）実施中止を求める意見書」を国へ提出を求める請願が出されていると思うのです。大きな影響が出てきますので、意見書を上げるかどうかの審議を十分に充実した形でされるべきだと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"議会運営委員会の場ではまずいと思うので、前回の委員会でも、私ども委員長判断で商業・ものづくり課長をお呼びしませんでした。今回の段階は、まだ正式に詰めておりませんけれども、前回と同じ内容で進めさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"大倉委員","kind":"確認","question":"その際に、質問の取り下げについても、確認をさせていただきました。今後、こうした質問の取り下げ等の対応については、さらにしっかりと確認しながら、丁寧に対応をしていきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"高橋（伸）委員","kind":"質問","question":"先般あった、立候補予定者説明会にも、くにば議員はいらしていたという話も伺っております。１点だけ、事務局長にお伺いしたいのですけれども、どのようにお考えになっているのかということをお聞きしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"大倉委員","kind":"確認","question":"診断書等を持って、しっかりと説明をしますということで、確認はしているところであります。本人からもしっかりと皆様を含めて、お話ができるようにしていかなければいけないと考えていますので、そのように対応していければなと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"鈴木（真）委員","kind":"質問","question":"質問も変わっている中で、やはり、載せておいてもいいのではないかなと私は思います。皆様の見解で、皆様がどうするのかにもよりますけれども、話として載せるべきだと自民党としては考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"田中委員","kind":"確認","question":"くにば議員が、もしも話せる機会があれば、議会に対して聞かせてほしいかなと思います。そこの部分は、これから削除か何かをされるのかなというところだけ確認させてほしいと求めました。","respondent":"工藤区議会事務局長","answer":"今日中に取り下げの正式な書類が出てくるですので、そういった中で、取り下げの正式な手続きをするということになります。そうしますと、取り下げ行為が正式に受理されたということになりますので、そういった事実に対しての対応をホームページで修正をしてまいるです。","id":"exchange-007"},{"speaker":"田中委員","kind":"確認","question":"議長への通告は上がったけれども、質問自体が上がってこなかったことについて、議長と区との調整などはされたのですかというところを確認したいです。","respondent":"本多議長","answer":"前回も謝罪しましたが、今回も２度目で本当に申し訳ありません。ご迷惑をかけたということで、謝罪はさせていただきました。","id":"exchange-008"},{"speaker":"石田委員","kind":"質問・要望","question":"当日も含めて確認をされながら、丁寧に対応したいとおっしゃっておりましたので、そのように対応していただきたいなと思います。区民に負託された議員としては、最も重要な仕事を放棄してしまったというところは、本当に重く受け止めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"たけうち委員","kind":"質問・要望","question":"質問ということに対して、そこら辺の見解をしっかり正していかないと、そのときの議長に本当に迷惑がかかっていく。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"あくつ委員","kind":"確認","question":"当時は須貝幹事長でしたけれども、再発防止のために、どのようなことをされるのですかというお話を聞きました。もし会派として責任を感じておられるのであれば、そこのところのお考えをお伺いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"大倉委員","kind":"確認","question":"前もって事前の質問の内容も含めて、丁寧に確認をしながらやっていかなければいけないと考えていますので、事前の確認をさらに丁寧にしながら。それ以外の方法についても、様々検討しながら取り組んでいきたいなと思っているところであります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"あくつ委員","kind":"質問・要望","question":"丁寧にやられているなということは感じたのですけれども、当日確認して、そこから連絡が取れなくなってしまうという今回の件。それぐらい具体的なことをお考えいただかないと、そこはぜひ具体的な検討をお願いした上で、また議長にご報告いただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"田中委員","kind":"質問・要望","question":"財政調整のところなのですけれども、都の法的責任が発生した部分で、資料などはありますかという確認と、例えば、法的にどのような部分か。どの法律の何条にかかってしまったなどの具体的な部分を、もし分かればお知らせいただきたい。","respondent":"本多議長","answer":"大体１月末ぐらいには協議が成立するのですが、各２３区は予算の歳入は５５.１％を想定して予算計上していると、品川区から伺いました。後で資料を見ていただければと思います。","id":"exchange-014"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/881920?Template=document&Id=5498#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":18243,"voices":74}},{"id":"r05-20230224-3","meetingId":"r05-c-budget","date":"2023年2月24日","dateIso":"2023-02-24","committee":"予算特別委員会","time":"午前１１時４５分～午前１１時５１分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/756395?Template=document&Id=1160#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":1994,"voices":18}},{"id":"r05-20230227-6","meetingId":"r05-cm02","date":"2023年2月27日","dateIso":"2023-02-27","committee":"区民委員会","time":"午前１０時００分～午前１１時２２分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を5件整理しています。","topics":[{"id":"topic-01","title":"第１１号議案、品川区印鑑条例の一部を改正する条例","agenda":"第１１号議案、品川区印鑑条例の一部を改正する条例","exchanges":[{"speaker":"おくの委員","kind":"確認","question":"単純な確認ですけれども、ということはマイナンバーカードの取得が前提になっているという理解でよろしいでしょうかというのが第１点です。この点、区としてどうお考えなのかということを伺いたいと思います。","respondent":"吉野戸籍住民課長","answer":"今回のスマートフォンですけれども、マイナンバーカードの取得が前提条件になります。それから、２つ目の安全性ですけれども、今回のスマートフォンの部分というところでよろしいでしょうか。","id":"exchange-001"},{"speaker":"おくの委員","kind":"質問・要望","question":"ですから、教育とか管理というか、データの管理、その点、念には念を入れてということは心がけとしてやってほしいと求めました。要望として言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"松本委員","kind":"意見","question":"今回は、移動端末設備と書かれていると思うのですけれども、電子通信事業法の定義を見ると、スマートフォンだけでなくてタブレットなんかも当てはまりそうな気がするんですけど、その点はいかがでしょうとの意見を述べました。","respondent":"吉野戸籍住民課長","answer":"委員のご指摘のとおりでして、そういった移動端末というところの全般になります。","id":"exchange-003"},{"speaker":"松本委員","kind":"質問","question":"では今はアンドロイドというお話なので、ｉＰｈｏｎｅについてはまだ使えないという認識でよろしいか尋ねました。","respondent":"吉野戸籍住民課長","answer":"去年、デジタル大臣からの答弁にもありましたとおり、最初にアンドロイドをやりまして、実際にｉＰｈｏｎｅに関しましては、遅れながら開発するということで、今アップルと国とでやりとりをやっている最中です。","id":"exchange-004"},{"speaker":"松本委員","kind":"質問・要望","question":"恐らくｉＰｈｏｎｅで、ほかのタブレットも使えるようなってくると思いますので、可能な端末が広がった場合には周知をしてほしいと求めました。以上、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/753456?Template=document&Id=2952#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":4721,"voices":29}},{"id":"r05-20230227-7","meetingId":"r05-cm02","date":"2023年2月27日","dateIso":"2023-02-27","committee":"厚生委員会","time":"午前１０時００分～午後 ０時０５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を39件整理しています。","topics":[{"id":"topic-01","title":"第１７号議案、品川区社会福祉基金条例の一部を改正する条例","agenda":"第１７号議案、品川区社会福祉基金条例の一部を改正する条例","exchanges":[{"speaker":"石田委員","kind":"質問","question":"複数人の方からなのかを伺いたいのと、名前を出さずにこういう形になったということでよろしいのか、２点お願いします。","respondent":"寺嶋福祉計画課長","answer":"残りの１００万円につきましては、同じく既にお亡くなりになりました故人の方の遺言によるものです。２名とも、故人の方につきましては匿名希望、非公開ということでお受けしておりますので、お名前の記載はございません。","id":"exchange-001"},{"speaker":"高橋（し）委員","kind":"意見","question":"補正予算のところに８,０００万円ぐらいの社会福祉基金積立金があるのですけれども、それと、今のこの７,８００万円余との関係。補正予算で、それが８,１００万円ぐらいあるのですけれども、それはこの７,８００万円余との関係はどうなりますかとの意見を述べました。","respondent":"寺嶋福祉計画課長","answer":"補正予算のほうの記載は３００万円を合わせた形での合計金額となっておりますので、８１００万余という形になってあります。基金としては別々に積み立てるということです。","id":"exchange-002"},{"speaker":"いながき委員","kind":"確認","question":"確認と質問なのですが、高齢者福祉に特化したものという理解でいいのかというのが１つと、何かほかのとの違いはあるのか尋ねました。","respondent":"寺嶋福祉計画課長","answer":"以前お名前があった一つの理由というか当時の考え方ということにはなるのですけれども、金利がよかったときに運用益を活用すると。そうするとおのずと基金の設置期間が長くなりますので、恐らくその辺の事情も含めて、このような状況があろうかと思います。","id":"exchange-003"},{"speaker":"いながき委員","kind":"質問","question":"そうすると、例えばお名前付きの基金で頂戴した金額を使い切ってしまったらば、その基金はなくなるという理解でいいか尋ねました。","respondent":"寺嶋福祉計画課長","answer":"おっしゃるとおりです。補正予算等々を組ませていただきまして、基金の金額を全て事業に充当することになった場合には、基金はその時点で終了するということなります。","id":"exchange-004"},{"speaker":"あくつ副委員長","kind":"質問","question":"素朴な疑問として伺います。企業と１人の方からはたまたまそういう申出があったので、こういう汎用的というか受皿を特化して作ったという理解でよろしいのか尋ねました。","respondent":"寺嶋福祉計画課長","answer":"副委員長のご認識のとおりです。","id":"exchange-005"},{"speaker":"あくつ副委員長","kind":"確認","question":"分かりました。確認ですけれども、もしくは使う目的であるということで、これは変わらずということでよろしいのか尋ねました。","respondent":"寺嶋福祉計画課長","answer":"基本的にはそういう考え方ですけれども、今の金利から考えますと、恐らく基金を直接崩して活用するときには基本的にはそういう形になろうかと。考え方としては、使途のとおりに運用益であろうとも活用はする方向です。","id":"exchange-006"},{"speaker":"石田委員","kind":"確認","question":"２人以上で入れる高齢者住宅というのは何戸ぐらいあるのか伺いたいのと、パートナーシップの証明書を持っていても、各自治体が条例を改正しないと入れないという仕組みになっているということでしょうかというのを確認させてください。","respondent":"川原高齢者地域支援課長","answer":"２つ目の質問です。今回、パートナーシップ条例の認定の要件を追加することで、条例改正に伴って４月１日より施行するという流れです。","id":"exchange-007"},{"speaker":"石田委員","kind":"確認","question":"ほかの自治体は、品川区と同様の条例改正をしているわけではないところもあるということなのでしょうか。確認をお願いいたします。","respondent":"川原高齢者地域支援課長","answer":"１つ目の世帯用住宅の空きはないかというご質問に関しましては、空きはなし、現在皆様お住まいでいらっしゃる状況です。質問の２つ目のパートナーシップの条例に関しましては、既にパートナーシップ制度を導入している都内の自治体は１９区市あると伺ってあります。","id":"exchange-008"},{"speaker":"石田委員","kind":"意見","question":"それがもしほかの自治体もそうではなく、条例改正をしていないような区があった場合はなぜなのだろうなと疑問に思ったので、私のほうで調べてみたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"いながき委員","kind":"意見","question":"これは意見ですが、やはり私の知る限り、２３区中では１０区が既にパートナーシップ制度を入れています。ぜひとも品川区もほかの区に続いて、パートナーシップ制度を導入していただければという意見というか思いですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"あくつ副委員長","kind":"質問","question":"すごく素朴な質問なのですが、これはそういうことになるのかという、その辺りの考え方を説明を求めました。","respondent":"川原高齢者地域支援課長","answer":"所管の課長から聞いている部分での範囲のお答えになってしまいますが、それに附属する区の制度につきましては、今後審議を進めていきたい部分です。ちょっとまだ協議中の部分です。","id":"exchange-011"}]},{"id":"topic-02","title":"令和５年陳情第２号、重度障害者を差別しないグループホーム入居選考を求める陳情","agenda":"令和５年陳情第２号、重度障害者を差別しないグループホーム入居選考を求める陳情","exchanges":[{"speaker":"石田委員","kind":"質問","question":"グループホームに重度障害者も入れるようにということで、今重度障害者というのは、区が把握しているところでは何人いらっしゃるのか。そして、この重度の方が入れるグループホームは区内に何人分あるのか伺いたいと思います。","respondent":"松山障害者支援課長","answer":"重度障害者という定義が不明確ですので、人数等についてはお答えはできかねます。あるいはグループホームの支援者の体制、一概に重度障害者の方が入れるグループホームは何か所ですというのはお答えはしかねます。","id":"exchange-012"},{"speaker":"石田委員","kind":"質問","question":"重度の知的障害者、要は身体のところでの重度の方というふうに分けると、数は分かるのでしょうか。そこを伺いたいのと、重度障害者も対象としているグループホームは、区内には何か所あるのか尋ねました。","respondent":"松山障害者支援課長","answer":"重度障害者という言葉を使っているグループホームにつきましては、今後整備していく出石つばさの家等になります。","id":"exchange-013"},{"speaker":"石田委員","kind":"確認","question":"そうすると、今の時点で重度障害者を受入れ対象としているグループホームはないということなのでしょうか。この陳情のところには、重度障害者を受入れ対象としているグループホームは区内にどれぐらいあるのか伺いたいと思います。","respondent":"松山障害者支援課長","answer":"先ほど説明しましたように障害の程度だけではなくて、また医療情報、もちろんご本人やご家族の希望を踏まえて総合的に判断しているものです。年数の経過によって、開設当初は比較的支援が少ない人が入っていたとしても、区としては支援をしています。","id":"exchange-014"},{"speaker":"石田委員","kind":"質問","question":"そうすると、そういった選定会議だったり民間の事業者がどう選定するかというのは、重度であろうが軽度であろうが状況に応じて選定されていくと。なので、障害者グループホームというのは軽度から重度まで対象になっているというふうに考えているということでいいのか尋ねました。","respondent":"松山障害者支援課長","answer":"グループホームの制度につきましてご説明申し上げます。重度化・高齢化に対応できるグループホームの新たな類型として、日中サービス支援型グループホームが創設されたということで、品川区だけではなく。","id":"exchange-015"},{"speaker":"石田委員","kind":"質問","question":"１０月の本会議でも一般質問で、グループホーム２６９人中、区内に足りないために区外を利用せざるを得ない方が多くいるというのが現状だと思います。そして今後、重度障害者も受け入れられるグループホームを積極的に増設していきたいという考えであるのかどうか伺いたいと思います。","respondent":"川崎障害者施策推進課長","answer":"今までお伝えしてきたとおり、出石つばさの家では１６名の定員ということで今後受け入れを行っていく予定です。品川区の総合実施計画にもありますように、今後は安全・安心に通所できる場を整備するという方向も検討してまいりますので。","id":"exchange-016"},{"speaker":"石田委員","kind":"質問・要望","question":"どういう体制のグループホームを造るのかというところでは、もうその時点で重度障害者も対応できるというところが決まってきてしまうと思います。なので、ぜひ今後、そこは重度障害者もしっかり受け入れられるグループホームのさらなる増設ということで求めていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"いながき委員","kind":"意見","question":"例えば民立のところにより重度の方を引き受けてほしいというような区からの支援はあるのかというのが１つと、より優先順位が高くなり。","respondent":"松山障害者支援課長","answer":"１点目、民間事業者への支援についてです。発作時の対応等、このように対応すればグループホームでも受入れが可能ではないかというような議論の下、推薦をしているです。","id":"exchange-018"},{"speaker":"いながき委員","kind":"質問・要望","question":"こういった方はこういった症状がありますよという資料がつけられるという意味でよろしいでしょうかという確認が１つと、それをご覧になって。そういった方たちをより優先順位を高く見ていただきたいというようなものがあるといいなと思うのですけれども、そこも教えていただけますか。","respondent":"松山障害者支援課長","answer":"２点ご質問をいただきました。障害の状況、それからマッチングを経て、入居候補者と運営事業者双方合意の上で入居契約に至るです。","id":"exchange-019"},{"speaker":"あくつ副委員長","kind":"確認","question":"先ほどのご説明を伺っていると、令和４年からは新しい審査というか、そこで推薦の可否を決めていると。そういう過程の中でどういう手順を踏んで、その辺りについては何かご説明されていらっしゃるのか尋ねました。","respondent":"松山障害者支援課長","answer":"明日報告します西大井つばさの家の定員増を含めて４名の予定で、今その４名の情報は、相談支援事業所を通じて流しております。ただし、どこかで何らかの方法で、陳情を出された方にはご説明させていただきたいと思っています。","id":"exchange-020"},{"speaker":"いながき委員","kind":"意見","question":"品川区のほうからぜひともより困難なものを抱えている方を優先的に入れてほしいというような添え書きというか、今あるのかなというところと、ないのであればお願いしたいですとの意見を述べました。","respondent":"松山障害者支援課長","answer":"民間への支援につきましては、先ほど申し上げたグループホームの運営費の助成ということはあります。有資格者を常勤配置した場合に対象となるということで、有資格者を配置するということはより支援が必要な方に対応するスキルをアップするですので。","id":"exchange-021"},{"speaker":"いながき委員","kind":"質問・要望","question":"よりプッシュするみたいなものがあればいいと思ったので、もし今現在ないようでしたら、そこの検討もしていただきたいと思っています。これはお願いです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"先ほど質問をしましたけれども、現在の状況とは異なることでのご認識があったということは、先ほどの中で確認いたしました。障害者団体の代表、そういう公正な審査過程があるということは、しっかりご説明をしていただけたらなというのが要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"石田委員","kind":"質問・要望","question":"そこは確実にそうしていただきたいですし、毎年当事者団体からは、重度の方も入れるグループホームをということは要望が出されております。整備率も２３区で２２位と最低レベルですので、そこを何としても引き上げていただきたいというところでは、さらに進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"せお委員","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いします。過程とかそういったところでの丁寧な説明をしていただいて、そこのところをご理解いただけるような流れをつくっていただきたいなと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"}]},{"id":"topic-03","title":"議案審査を改めて行います。(4)第２０号議案、品川区立健康センター条例の一部を改正する条例","agenda":"議案審査を改めて行います。(4)第２０号議案、品川区立健康センター条例の一部を改正する条例","exchanges":[{"speaker":"石田委員","kind":"質問・要望","question":"建物としてはそもそも以前の説明だと、恒久的な建物になっていくのか、暫定的なのかというのを伺いたいです。荏原健康センターだけの建物としていくのか、ほかの複合施設の中に健康センターが入るのかというのが分かっていれば教えてほしいと求めました。","respondent":"若生健康課長","answer":"それから２点目、昨年９月の厚生委員会でご説明させていただきましたところなのですが、あと３つ別々の敷地の中で分けて建てるというような想定です。ここの敷地も含めて今検討していますので、いずれ暫定建物から本施設に移るというような想定で、今検討しております。","id":"exchange-026"},{"speaker":"石田委員","kind":"質問・要望","question":"前回の９月の説明のときに、近隣住民の皆さんに工事説明をしていくとおっしゃっていたと思うのですけれども、それにはどのぐらいいらっしゃったのか。出していたところですので、そういった要望は何か出たのか、どのような説明会だったのかというのを伺いたいと思います。","respondent":"若生健康課長","answer":"それから住民説明会は、仮設の工事が始まる前の令和４年１０月６日に実施しています。そういった中で、どういった施設にしていくかというところは十分検討を深めていくというようなところで説明をしたところです。","id":"exchange-027"},{"speaker":"石田委員","kind":"質問・要望","question":"やはり近隣住民の皆さんと住民参加で、跡地としてどう活用していくかという検討をしてほしいと求めました。それで、荏原健康センターは、先ほどの質問で健康センターのみの建物になっていくのか、その辺の検討があるならば説明を求めました。","respondent":"若生健康課長","answer":"荏原健康センターの仮移転後の建物につきましては、荏原健康センター単体としての利用の目的としての建物となっています。","id":"exchange-028"},{"speaker":"いながき委員","kind":"確認","question":"確認なのですが、荏原健康センターは、改修後は今あるところにもう一回改修した施設が建つという理解でいいですか。改修後の荏原複合施設に戻るときには、今回削除された健康・体力検査ルームと保育室というのは元に戻るという理解でよろしいか尋ねました。","respondent":"若生健康課長","answer":"そちらの（１）の所在地の変更の件と、単純に移転するので所在地を変更しますという体制になっていまして、まず平成１４年度に外部委託を入れた際に。","id":"exchange-029"},{"speaker":"いながき委員","kind":"確認","question":"ありがとうございました。もともとの健康・体力検査ルームというのはカウンセリング、保育室は授乳室が代替でという理解が合っているかどうかの確認だけさせてください。","respondent":"若生健康課長","answer":"カウンセリング等々をするというような事業でございまして、それを１室、この健康・体力検査ルームと呼んでいた部屋で実施していた。部屋としての用途はもう必要なくなったということで、終了したというような経緯です。","id":"exchange-030"},{"speaker":"石田委員","kind":"質問","question":"今の質問に関連してですけれども、そうすると、ではそのときに本来は条例改正をするべきだったということですよね。区民の方からも、だからといって問題はないというふうには言えないのではないかと思うのですが、そこはどうか尋ねました。","respondent":"若生健康課長","answer":"当時なぜ改正が行われなかったのかという理由が分からず、今回そういった住所変更ということが生じたところでしたので、今回の条例改正です。必ずしなければいけないような大きい改正のタイミングと合わせて実施するというような想定だったのかもしれないのかなと。","id":"exchange-031"},{"speaker":"石田委員","kind":"質問・要望","question":"再開発のための用地などに使うのではなくて、住民参加で住民合意の下で、引き続き丁寧に聞き取りながら進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"}]},{"id":"topic-04","title":"第２８号議案、品川区国民健康保険条例の一部を改正する条例","agenda":"第２８号議案、品川区国民健康保険条例の一部を改正する条例","exchanges":[{"speaker":"石田委員","kind":"質問・要望","question":"改めてここでも質問をさせてほしいと求めましたが、品川区が要は都から納付金が示されると思うのですけれども、それが幾らなのかということです。前年度との差が１万１,８９５円、約１万２,０００円ですけれども、これだけの値上がりになった理由を伺いたいと思います。","respondent":"池田国保医療年金課長","answer":"後期高齢者支援金につきましては２７億２,９９１万円。およそ８万人ほど被保険者が減るということを見込んでおりまして、令和５年度については３２万１,５３３円になるというような見込を示しています。","id":"exchange-033"},{"speaker":"石田委員","kind":"質問・要望","question":"今、値上げのご説明をいただいたのですけれども、そうしたところで区として軽減するための特別な対策は打たれないのでしょうか。それを代表質問のほうでも取り上げさせていただいて、そこら辺の考え方をもう一度お願いしたいと思います。","respondent":"池田国保医療年金課長","answer":"この保険料の減額等、それから実際の激変緩和措置につきましても、特別区長会において２３区統一の形でやろうということで進めているところです。２３区統一の形でできれば政策的なところで、今後どのような形になるか分かりませんけれども、検討は進めているところです。","id":"exchange-034"},{"speaker":"石田委員","kind":"質問・要望","question":"１０分の１の３億円にしてきたということですので、それが毎年値上げになっているわけですから、そこの部分に当たらないと言われているのです。それと、東京都の令和５年度の保険料に対しての激変緩和としてはどれぐらい出されているのでしょうかということを伺いたいです。","respondent":"池田国保医療年金課長","answer":"ここの部分での賦課率でやりなさいということで、国のほうでもきちんと決まっておりますので、この分については変えることができないです。ですので減額を区独自でやるということについては、一律でやることは難しいと判断いたします。","id":"exchange-035"},{"speaker":"石田委員","kind":"質問・要望","question":"違法ではないということでしたので、できるものだということも確認させていただきましたので、そこは改めて今後も求めていきたいと思います。ぜひ東京都にも軽減に向けてさらなる激変緩和を求めてほしいと求めましたけれども、いかがか尋ねました。","respondent":"池田国保医療年金課長","answer":"確かに東京都全体で約１５億円という額ですので、こちらについては実際に特別区長会を通じまして、都だけでなく国に対しても要望を出しています。","id":"exchange-036"},{"speaker":"石田委員","kind":"質問・要望","question":"軽減のために１兆円の公費投入をということで国に求めているところですので、区としても国や都に求めているというところですが。その立場で、引き続き求めていきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"石田委員","kind":"意見","question":"その上に協会けんぽより２倍も高い負担率という、この負担が重くなる構造的問題は区も認めています。区民生活は追い詰められていますので、今こそ税金投入で引き下げこそすべきだと思いますので、反対ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-038"},{"speaker":"いながき委員","kind":"意見","question":"皆保険制度の必要性、その維持をうたいながら、実際には未保険者を生み出してしまうと思います。なので、この議案には反対をしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/651938?Template=document&Id=3654#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":31380,"voices":155}},{"id":"r05-20230227-8","meetingId":"r05-cm02","date":"2023年2月27日","dateIso":"2023-02-27","committee":"建設委員会","time":"午前１０時００分～午後 ２時５７分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を75件整理しています。","topics":[{"id":"topic-01","title":"会議の運営上、予定表の順番を入れ替えまして、第２５号議案、品川区立公園条例の一部を改正する条例","agenda":"会議の運営上、予定表の順番を入れ替えまして、第２５号議案、品川区立公園条例の一部を改正する条例","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"子どもたちから料金を取る、なぜそうしたのか伺いたいと思います。軟式こども野球場と同様の設定にしたということですけれども、その野球場の設定は、どういった根拠で決められているのか伺いたいと思います。","respondent":"高梨公園課長","answer":"子どもは１チーム当たり１枠５００円という料金設定ですので、過度な負担のない料金設定であると、区としては、このように考えているところです。そこと横並びという形で、今回、同額の設定とさせていただいたところです。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"そういったものを負わせるのはなぜなのか伺いたいと思います。やはり無料にすることが一番だというふうに思うのですが、その点も伺いたいと思います。","respondent":"高梨公園課長","answer":"最初に、こども野球場等の利用料金の設定の根拠といったところですが、周辺区の利用料金等を参考にし、過度な負担とならない範囲で設定したです。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問","question":"そういった子どもたちがスポーツをすることについて、子どもたちへの効果、あるいは影響というところで考えているところがあれば伺いたいと思います。親の経済力とかも関係なく、しっかりスポーツをする機会を与えていくということが私は必要だというふうに思いますけれども、いかがか尋ねました。","respondent":"高梨公園課長","answer":"一定の範囲、面積を確保しながら、専用のスポーツ場も一方で必要になってくる。一定、そういったところでのスポーツの確保といったところでも、子どもたちにとっては利用できる機会はあるのかなというふうに考えているところです。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうした考え方のところで、子どもまで取っていくのかどうか、受益者負担を子どもにまで負わせるのかという区の姿勢のところだと思うのです。そこは子どもにまで使用料を取るということはないように、無料にすべきだということを求めて、質問を終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"横山委員","kind":"質問・要望","question":"２番、具体的にどういった利用方法というか、イメージなのかを確認させてください。２点目ですけれども、ＡＥＤの場所は、どの辺りにあるのかということを教えてほしいと求めました。","respondent":"高梨公園課長","answer":"門を開け、予約関係なしに自由に出入りしていただいて、中の広場を利用していただくということを考えてあります。工事中にサッカー場の利用を開始するということで、不安全になることがないような形で整備してまいりたい、このように思っているところです。","id":"exchange-005"},{"speaker":"横山委員","kind":"質問・要望","question":"こちらは要望になるのですけれども、ＡＥＤは１０分間で取りに行けるということがとても大切になってくるかと思います。ぜひ周知を進めていただきたいというふうに思っておりますので、一言、ご答弁ほしいと求めました。","respondent":"高梨公園課長","answer":"今のご意見を踏まえまして、団体等の利用の予約を行うスポーツ推進課とも情報の共有を図りまして、今、委員からご提案がありましたＡＥＤについて、情報の共有はしっかりと進めてまいりたいというふうに考えてあります。","id":"exchange-006"},{"speaker":"芹澤委員","kind":"質問・要望","question":"大体６時ぐらいからスタートすることが多くて、住宅街ですから、今後もできないというようなイメージなのですか。その２点を確認させてください。","respondent":"高梨公園課長","answer":"スポーツの所管部署とも連携しながら、公園内で実現できるスポーツ施設については、引き続き研究を進めてまいりたいというふうに考えてあります。お話としては、周囲の方々、利用者とともに話合いを続けてまいりたいというふうには思います。","id":"exchange-007"},{"speaker":"こんの委員","kind":"質問","question":"参考までにお伺いしたいと思います。人工芝生でコートがされているということなので、参考までに、このメンテナンスはどれぐらいの頻度でされるものなのか尋ねました。","respondent":"高梨公園課長","answer":"どんどんいい製品が出てきてありますが、今までの全体改修の周期といたしましては、おおむね１０年ほどというふうになってあります。メーカーからは１０年未満ぐらいの耐用年数でといったところですが、区民の皆様に使っていただけるように努めてまいりたいと思います。","id":"exchange-008"},{"speaker":"こんの委員","kind":"質問・要望","question":"私は素人なのでよく分かりませんが、サッカーのシューズでめくれてしまったりとか、常にいい状態で借りていただきたいと思うので、そうしたことから考えると、一定の料金をいただきながら、その整備をしていくということも必要かなというふうにも考えるところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"のだて委員","kind":"意見","question":"今回の条例改正は、小中学生からも使用料を取るという有料化条例です。友達とか関係づくりにも役立ちますので、より多くの子どもたちがスポーツをする環境を保障するために無料にすべきだと考えますので、反対ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"のだて委員","kind":"質問・要望","question":"併せて、このサウンディング調査ではどのような意見が出たのか伺いたいと思います。１４事業者が参加したということで、こういった事業はどういったところが参加をするのか伺いたいと思います。","respondent":"高梨公園課長","answer":"２番目に、７公園それぞれについて分けてアンケートを実施しておりまして、１,０００件を超えるサンプル数を得ているところです。各者とも、それぞれ実施したい事業の内容は異なりますけれども、いずれかの公園につきましては。","id":"exchange-011"},{"speaker":"のだて委員","kind":"質問","question":"陳情にもありましたが、プレス発表の資料を見ると、今年１０月には事業者を公募する。１２月には事業者を認定するということで、そのところはどうなのかということと、そこも伺いたいと思います。","respondent":"高梨公園課長","answer":"先ほど説明の中でも申し上げましたとおり、３点目の事業の可否の検討といったところの質問にも関わりますが、来年度予算の計上であったり。正しく現在検討を進めているところですが、対象公園の絞り込みといった形で進めていくことを現在のところ予定しています。","id":"exchange-012"},{"speaker":"のだて委員","kind":"質問","question":"どういった形になるのかということが、そういった形になるのか、どういったことを考えているのかというところを伺いたいと思います。ビアガーデンをやっているというところもあるそうですけれども、そういったことも考えられるのか、その点を伺いたいと思います。","respondent":"高梨公園課長","answer":"検討中ですので、より多くの方に内外から訪れていただけるような公園施設となるものを設置することが望ましいというふうに考えているところです。最後に、イベント等を実施している自治体もあるというようなお話を最初にしましたが、まだ実施内容が決まった段階ではないですが。","id":"exchange-013"},{"speaker":"のだて委員","kind":"質問","question":"検討の中でも２００m2ぐらいの建築物ができるようなところで検討しているということですので、今、その辺りはどうなのか伺いたいと思います。やはり企業の利益のために公共施設である公園が利用されていくということになってしまうのではないかと思うのですが、区の考えを伺います。","respondent":"高梨公園課長","answer":"１点目の施設建築に伴って樹木が伐採されるのではないかといったところにつきましては、当然公園ですので、このように考えてあります。２点目につきましては、公園管理者として公園の主体的な運営の部分については、しっかりと管理していきたいというふうに考えているところです。","id":"exchange-014"},{"speaker":"のだて委員","kind":"提案","question":"そうした中で建物を造って公園を狭めていくということは大きな影響が出るというふうに思いますけれども、その点も伺いたいと思います。そういった現状の使用を制限するという提案が来たときには、区としては断るのか、そこを伺いたいと思いますとの意見を述べました。","respondent":"高梨公園課長","answer":"２点目の樹木等の伐採と、これも具体的に実施する公園であったり、その目的を見失わないように事業を進めてまいりたいというふうに考えてあります。その施設を建築する敷地の広場であったり、その利用の状況等を踏まえて計画は進めてまいりたい、このように考えているところです。","id":"exchange-015"},{"speaker":"のだて委員","kind":"質問","question":"こうしたことができなくなるということになれば、公園の活性化にはつながらないというふうに思いますけれども、いかがでしょうか。そうすると、ある意味、こうしたところで区民公園もPFI導入に向けて選定されるということがあるのか伺いたいと思います。","respondent":"高梨公園課長","answer":"２点目の区民公園につきましては、再整備を現在まで進めてまいりましたので、非常に魅力的な場所であることには変わりがございません。候補公園としては入れさせていただいてありますが、仮に事業実施の段となった際には、このように考えているところです。","id":"exchange-016"},{"speaker":"のだて委員","kind":"質問","question":"事業者を認定して事業内容を進めていく中で、住民や議会の意見を聞く仕組みというのはあるのか伺いたいと思います。ぜひ住民の方にも説明をしてほしいと、説明会を開いてほしいと思うのですけれども、いかがか尋ねました。","respondent":"高梨公園課長","answer":"対象公園や事業を実施する公園であったり、先ほどの資料の説明の中でも申し上げましたとおり、周辺にお住まいの方々を中心に。これから検討してまいりますが、今考えている形ですけれども、これから検討してまいりたいというふうに考えてあります。","id":"exchange-017"},{"speaker":"のだて委員","kind":"質問・要望","question":"そういった形でやらなければ区民が求めるものにはならないのではないかなというふうに思います。説明会もぜひやっていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"横山委員","kind":"質問","question":"１点、お伺いいたします。区にPark-PFI制度に関するお問合せがあった際は、現在どのように説明しているのか説明を求めました。","respondent":"高梨公園課長","answer":"まずはそういった事業そのものの概要のご説明、区のPark-PFI導入に向けた検討の状況といった形で、本課で対応させていただいているところです。","id":"exchange-019"},{"speaker":"西村副委員長","kind":"質問・要望","question":"すみません、２点、お伺いさせてください。関連で、宮下公園がPark-PFIではない手法を取り入れていると伺っておりまして、改めてどのような手法か説明を求めました。","respondent":"高梨公園課長","answer":"そういった施設の設置事例がありますので、担当職員を視察等に派遣して、事例収集と研究を行っているところです。Park-PFIは１つの事例でございまして、公園施設の設置管理制度、そういった手法を利用してやっているものと推察しています。","id":"exchange-020"},{"speaker":"芹澤委員","kind":"質問","question":"今時点では、区はPFI制度ありきに考えているものではないというようなご説明がありましたので、不採択でお願いします。それよりは、様々な手法を活用して検討していただいて、よりすばらしい公園を模索してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"こんの委員","kind":"意見","question":"具体的な事業計画は、まだ計画されていないという、こうした段階で説明するのは非常に難しいのかなと考えるところです。よって、不採択としますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"のだて委員","kind":"意見","question":"事業内容に区民の意見が反映される仕組みがない、また、責任を区がとらされるPark-PFIを導入することは反対です。しかし、このPark-PFIについて、検討プロセスや特徴を区民に説明することは、導入の有無の前に最低限のことですので、趣旨採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"松永委員","kind":"確認","question":"先ほどの質疑の中で様々確認させていただきました。事業内容についても検討中ということでしたので、まだ決定したわけではないということで、この陳情に関しては不採択といたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"横山委員","kind":"質問・要望","question":"今後、政策予算をつくる前の段階から区民の声を聞くことができるツールの導入を検討していただきたいというふうに思っております。他の自治体の導入事例の情報収集からスタートしていただくことを要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"のだて委員","kind":"質問・要望","question":"陳情第６号のほうは、書かれていることは大筋では住民追い出しの再開発の廃止を求めるものとなっています。ちょっと確認になってしまいますが、３月までというものを延伸するということですけれども、そこを伺いたいと思います。","respondent":"多並都市開発課長","answer":"令和６年３月まで延ばす予定で、その実施次第、この期間で終わることがもちろん見込まれるところです。万が一いろいろな状況があって延ばさなければいけないことがあれば、それはまたその都度の対応となるです。","id":"exchange-026"},{"speaker":"のだて委員","kind":"質問","question":"できなかったというところが１つ問題というか、いかがでしょうかということと、それが終わるまで延ばすという理解でいいのですか。この２地区についてはご説明いただきましたけれども、参加組合員のゼネコンやデベロッパーの利益が幾らになっているのか、そこも伺いたいと思います。","respondent":"多並都市開発課長","answer":"もう１つの駅前通り地区につきましては、先ほどご説明というか、その改修工事が終わるまでの期間を延伸しているということです。それが終われば、もちろん解散手続に入っていくことになりますので、そういう見込みで今進んでいるところです。","id":"exchange-027"},{"speaker":"のだて委員","kind":"質問","question":"まず私は問題だと思うのですけれども、こうした再開発はやめるべきだというふうに思いますが、いかがでしょうか。そこのところも伺いたいと思います。","respondent":"多並都市開発課長","answer":"１点目ですけれども、地域の方が地域主体でまちづくりを検討されて、進めてきているところです。先ほどご説明した補償費ということで、そういう補償金が資金計画で出てくるということで、そういう中で表現している。","id":"exchange-028"},{"speaker":"のだて委員","kind":"質問・要望","question":"再開発にこうした１００億円とかを投入していくよりも、安く広い広場などができるのではないかと思いますが、いかがでしょうか。支援のことについても詳しく説明してほしいということで書かれておりますけれども、これは恐らく事業として、その点もいかがか尋ねました。","respondent":"多並都市開発課長","answer":"事業中というか、ご自分が耐震性がなかなかない建物に住んでいらっしゃる方は、なるべく早く事業を進めたいというお話をお聞きするところです。そういう事業を進めながら、事業計画としてまとめていっていただいているのが現在の状況というふうに理解しています。","id":"exchange-029"},{"speaker":"のだて委員","kind":"質問","question":"しかし、同じ広さに住むには、新たに持ち出しをしなければならないということにもなってしまいます。こうした再開発は、やはりやめるべきではないかと思うのですが、いかがか尋ねました。","respondent":"多並都市開発課長","answer":"実際、事業実施中に起こったことについては、それはその時点でその状況に応じることかと思います。皆さんでいろいろ知恵を出しながら検討されているところでもありますので、そこの地区、地区で検討されるところかと思うところです。","id":"exchange-030"},{"speaker":"のだて委員","kind":"質問・要望","question":"いかがでしょうかということと、本組合の設立が始まったということなのか、引き続き段階についても伺いたいと思います。発起人というのはどういうふうに決められていくのか、住民への周知などはどういう形でやられているのかというところも伺います。","respondent":"多並都市開発課長","answer":"先ほど冒頭のご説明でもさせていただきましたが、これまで住民説明会、区のほうも都市計画の手続という形で住民説明会を開かせていただき。もう１つが。","id":"exchange-031"},{"speaker":"のだて委員","kind":"質問・要望","question":"様々伺いましたけれども、住民の不安にはしっかり応えて説明をしていくべきだと、これは要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"横山委員","kind":"確認","question":"１点、お伺いいたします。高齢者から、分かりにくい法律などに関してのお問合せがあった際には、区として現在どのような対応をしているのか確認させてください。","respondent":"多並都市開発課長","answer":"仕組みを説明するために、その中で細かな説明を、分かりやすく表現されてご説明していただいているところは確認させていただいています。もう少し丁寧に、どうしてそういうご質問なのかとよくお聞きして、丁寧に対応させていただいているところです。","id":"exchange-033"},{"speaker":"こんの委員","kind":"質問","question":"本日結論を出すでお願いいたします。今の質疑を伺っていて、事実として認識がちょっと違うというようなところが見受けられましたので、本陳情については不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"のだて委員","kind":"質問・要望","question":"本陳情の大筋は、住民を追い出す再開発の廃止を求めるものであり賛同できます。その下で住民には様々な不安があるわけですから、可能な限り丁寧な説明は必要だと考えますので、趣旨採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"松永委員","kind":"質問","question":"先ほど他の会派からもありましたように、事実と認識が違うのかなというふうに感じました。そのため、不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"芹澤委員","kind":"意見","question":"品川区が主体というよりは、住民主体であるべきだと思っていますし、この再開発についてもそのように行われているかと考えていますので不採択で。不採択でお願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-037"},{"speaker":"こんの委員","kind":"意見","question":"本日結論を出すでお願いします。これからも情報提供をしていただくというところが大事なのかなと思うところで、本陳情については、不採択としますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-038"},{"speaker":"のだて委員","kind":"確認","question":"本日結論を出すということで、採択を主張します。アンケート調査は準備組合の賛否の確認が曖昧なもとで、今こそやるべきですので、採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"松永委員","kind":"意見","question":"本日結論を出す、不採択でお願いいたします。地元の住民と、そして有識者の方々が集まって意見を出し合ってつくられた事業だと認識しておりますので、この件に関しては不採択としますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"},{"speaker":"のだて委員","kind":"質問","question":"制度について伺いたいのですけれども、どこに申請すればいいのか、そこの手続の仕方を伺いたいと思います。夫婦別姓の方は、このパートナーシップ制度を受けられるのかどうか、そこを伺いたいと思います。","respondent":"竹田住宅課長","answer":"今回、子どもの名前も記載されるようになっておりますので、子どもも含めて区の制度を利用できるということです。それから、別姓ということですが、その証明は戸籍、住民票等には影響を及ぼさないものですので、姓は別々でも差し障りないものと考えています。","id":"exchange-041"},{"speaker":"のだて委員","kind":"質問","question":"３つの住宅について改正されるわけですけれども、今回、どういった仕組みになっているのかというところを伺いたいと思います。改正されているわけですけれども、そういったことに至った経緯と、どのような議論が行われたのかというところを伺います。","respondent":"竹田住宅課長","answer":"都立病院で、通常は親族にしか病状の説明などをしませんが、病状の説明などもするというようなことを聞いてあります。地方自治法第２４５条の４第１項に基づく技術的な助言がございましたので、今回、文言を削除するものです。","id":"exchange-042"},{"speaker":"のだて委員","kind":"質問・要望","question":"他の住宅施策で適用することは、ほかに考えているところがあるのかどうか伺いたいと思います。今、区民住宅の申込みの状況ですとか、入居の状況はどうなっているのか伺います。","respondent":"竹田住宅課長","answer":"居住する方のご家族のライフスタイルの考え方も様々ですので、そういった多様な考えに対応できるように、住替えの要件に追加したものです。","id":"exchange-043"},{"speaker":"のだて委員","kind":"質問・要望","question":"建設委員会にも陳情が出されておりましたので、そういったところでできるようになったというのは、よかったなというふうに思っています。そうした形で、適用できるところには、ぜひ積極的に適用していっていただきたいというふうに要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"こんの委員","kind":"質問","question":"参考までにお伺いしたいと思います。参考までにお伺いしたいのは、今回これが追加された背景などがありましたら、参考までに伺いたいと思います。","respondent":"竹田住宅課長","answer":"今までどうだったのかということですけれども、特段、里親として入居したいというご要望は、ほとんどなかったという状況です。児童というのが里子を差すのですけれども、改正されましたので、区も条例改正を行うものです。","id":"exchange-045"},{"speaker":"こんの委員","kind":"質問・要望","question":"区の制度として、私としては非常に前向きに考えて進めていただきたい、このように思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"横山委員","kind":"質問","question":"２点お伺いいたします。改正に当たりまして、応募倍率ですとか、どういった変化があるというふうに区として考えているのかというところを説明を求めました。","respondent":"竹田住宅課長","answer":"募集の際に、募集要項、あるいはホームページにパートナーシップ制度等を記載して周知していきたいと考えております。たびたびお問合せをいただいておりましたので、要件拡大に伴いまして、住替えのニーズは従来より増えていくものと考えています。","id":"exchange-047"},{"speaker":"のだて委員","kind":"意見","question":"多様な家族の形を認め、同性のパートナーなども、異性の婚姻関係にあるパートナーと同等の対応をするために必要なことで、ジェンダー平等を進めるものであり、また、合理的配慮の主旨を踏まえてということで、介護が必要な単身障害者の除外をなくすということですので、賛成ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-048"},{"speaker":"のだて委員","kind":"質問・要望","question":"住替えについては、住民の声から始まって要望が実現したもので、住民の利益になるものですので、賛成です。ほかのものも区民の利益になるものですので、賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"}]},{"id":"topic-02","title":"第２３号議案、品川区手数料条例の一部を改正する条例","agenda":"第２３号議案、品川区手数料条例の一部を改正する条例","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"マンション管理計画等のほうを伺っていきたいと思うのですけれども、そこのところを伺いたいと思います。そして、これはどういったもので、現在はどういう形で運用されているのかということを伺いたいと思います。","respondent":"竹田住宅課長","answer":"今回、この４月より、計画の施行および認定をスタートさせるものです。所得税、都民税、区民税などの税率の軽減などを受けることができるというものです。","id":"exchange-050"},{"speaker":"のだて委員","kind":"質問","question":"そうした適切に管理していくということは必要だと思います。外壁等剥落の恐れがあるマンションも追加されたわけですけれども、そういった変更になった背景を伺います。","respondent":"竹田住宅課長","answer":"そういった考えから、区としては、税の優遇を受けられるための証明書を発行する要件を条例改正で追加するものです。","id":"exchange-051"},{"speaker":"のだて委員","kind":"質問","question":"今までは住戸ごとにやっていたわけですけれども、そのやっていた理由と、今回変更した理由を伺いたいと思います。太陽光は再生可能エネルギーですから重要なものだと思うのですけれども、考慮されないというのはどういうことなのか伺います。","respondent":"竹田住宅課長、長尾建築課長","answer":"マンション建替円滑法改正に伴う対象物件が区内にどれぐらいあるかというお話ですが、正確な数は把握してございません。ただ、既にお住まいになっていないようなマンションも見受けられることから、一定数あるものと考えています。それに対応する形で、建物全体の低炭素化を推し進めていくために、住戸ごとの申請が廃止されております。","id":"exchange-052"},{"speaker":"のだて委員","kind":"意見","question":"老朽化したマンションの管理ですとか、脱炭素化は進めるべきものですので、賛成ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-053"}]},{"id":"topic-03","title":"請願・陳情審査を再度行います。 それでは、(1)から(14)に記載の請願・陳情１４件につきましては、関連する内容のため、一括して議題に供します。…","agenda":"請願・陳情審査を再度行います。 それでは、(1)から(14)に記載の請願・陳情１４件につきましては、関連する内容のため、一括して議題に供します。…","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"夕方３時間、あるいは４時間というところで飛んでくるということですから、おのずと値が小さくなってしまいます。請願にも書かれておりましたが、飛行機はそれを超えて発生しているということで、そこの考え方を伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"それから２点目でお尋ねいただいた、こちらに書かれているところは、主に工場等に対する音が請願のほうでは書かれております。基本的には、航空機騒音、それぞれの音に対して、何か条例で規定が定められているものではございません。","id":"exchange-054"},{"speaker":"のだて委員","kind":"質問","question":"そうした下でＬｄｅｎ基準に当てはまっているのでいいですよということでいいのかというところを伺いたいと思います。これは問題ではないかと、生活を実際に壊しているわけですけれども、壊すものではないかというところを伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"夕方の３時間、ご説明したのは、公表している事実をご報告させていただいたです。電車の音ですとか、そうした１つ１つの実際の音は、示されている環境確保条例に当てはまるものではないというところを先ほどご説明したところです。","id":"exchange-055"},{"speaker":"のだて委員","kind":"質問","question":"それと同等以上のことが飛行機によってもたらされているということですので、住民は大きく生活が脅かされているということだと思います。品川の場合は短時間なわけですから、品川の実態にはそぐわないというふうに思うのですが、改めて伺います。","respondent":"鈴木都市計画課長","answer":"これでいい悪いというよりも、その事実を先ほどからご報告、ご説明しています。これも繰り返しになりますが、運用開始後、今後も国のほうには環境負荷軽減に向けた取組を区としてもしっかり強く求めていきたいです。","id":"exchange-056"},{"speaker":"のだて委員","kind":"質問","question":"コロナで減便になっているという状況ですが、現在の国際便の便数、コロナ前と比較してどれだけの割合になっているのか。そこを伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"２社が公表している令和４年度第３四半期までの状況ですが、２０１９年比で言いますと、コロナ前の７１.５％程度というような状況。あるいはＡＮＡ（全日本空輸）が、コロナ前、２０１９年比で５７.１％というような状況です。","id":"exchange-057"},{"speaker":"のだて委員","kind":"質問","question":"収入というところですけれども、７１％と５７％ということで、恐らく便数としても回復していないのだろうというふうに思います。そうした中で、この羽田新ルートを実施していく必要性はないというふうに思いますけれども、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"運行開始当時、そうしたコロナ禍での状況も鑑みながら、内容を含めた要望書を国のほうに直接届けてきたです。これは国策の中で行われていることですので、基本的には、その必要性は国が判断し、考えていくというところだと区としては考えているところです。","id":"exchange-058"},{"speaker":"のだて委員","kind":"質問","question":"区長が国に赴いて声は届けてきたということですけれども、その中で区長は、反対だということは一言も言っていないということですよね。やめてほしいと、反対だということを言っていくことが必要だと思いますけれども、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"羽田新ルートにつきましては、国策として国の責任において進められているものです。今後も、継続し、こうした申入れをしっかり行うとともに、固定化回避に向けた一刻も早い検討内容の公表を国に求めてまいりたいです。","id":"exchange-059"},{"speaker":"のだて委員","kind":"質問","question":"やはり区民の生活が壊されているものですから、そういった立場をとることが必要だというふうに思いますけれども、なぜ反対しないのか伺います。空港に一番近い自治体の１つである品川が、着陸するときには直線が必要になりますので、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"いろいろな多角的な検討の中で、全く何ら検討が加えられなく、検討は継続して行っていただきたいと。そこは検討を、継続して行っていただきたいというところを国のほうに伝え、検討いただいているというような状況です。","id":"exchange-060"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ住民の立場に立って、品川区としても国に撤回を求めていくという姿勢に立っていただきたいというふうに思いますけれども、いかがでしょうか。海上ルートに戻していくという意見書を提出すべきだと私は思いますが、皆さん、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"品川区のほうでこうした固定化回避に向けた検討を求めていなかった場合、これは正にそのまま何の検討も加えられずに進められてきているものです。区としても、今後も強く求めていきたいです。","id":"exchange-061"},{"speaker":"のだて委員","kind":"質問","question":"固定化回避では、品川上空を飛ぶことは回避できないということは強く言っておきたいと思います。もう３年もずっと続いて結果が出ていないわけですから、区議会としても出していくべきだと思いますけれども、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"},{"speaker":"のだて委員","kind":"質問・要望","question":"この請願・陳情は全て廃案になってしまうということですから、結果を出していただきたいというふうに、これは強くお願いしたいと思います。この請願の中にも結果を出してほしいということで求められていますので、結果を出していくということで、皆さんの姿勢を求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"},{"speaker":"芹澤委員","kind":"質問","question":"それ以外にも議会の場で立場を述べようということで、皆さんにもお願いして、全会一致で決議をさせていただいたところであります。新たな動きがかかるということでお話を伺っておりますので、区議会だけではなくて、継続でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"},{"speaker":"こんの委員","kind":"質問・要望","question":"これは私どもも区議会として求めてきた中で行われている検討会で、まだ結論が出ていないという、こういう状況です。もう１点が、結論を出すのであればそうしたことも状況が必要かなと考えるところから、継続とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"のだて委員","kind":"質問","question":"結論を出さずに採決さえしないというのは、職責を果たしていると言えるでしょうか。結論を出すべきです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"のだて委員","kind":"意見","question":"昨年３月、渋谷区で氷塊落下があり、羽田新ルートにおいても落下物の危険性が現実のものとなっています。以上のことから、この羽田新ルートは撤回すべきだと考えますので、採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-067"},{"speaker":"松永委員","kind":"意見","question":"リモートワークや学習等が騒音に悩まされて集中できない、落下物に関しましても、事故が起こる前に対策をとるべきであるという声も届いております。海上ルートに戻す方法しかないと考えておりますので、我が会派は、この請願に対し採択いたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-068"},{"speaker":"横山委員","kind":"確認","question":"第６回固定化回避に係る技術的方策検討会は、本年夏から秋頃の開催が予定されているとの説明がありました。引き続き区民の方々のお心に寄り添い、丁寧に説明、確認していく必要があると考えますので、継続でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"のだて委員","kind":"質問・要望","question":"町会長、自治会長の過半数を超える１０１名の署名があったもので、運用停止を求める声が区内に広がっているあらわれです。住民の被害を取り除くために、区議会としても運用停止を求める意見書を提出すべきですので、採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"},{"speaker":"のだて委員","kind":"意見","question":"住民への騒音や落下物など被害は甚大であり、国の検討会では、品川上空を飛行回避することはできないため、羽田新ルートは中止すべきです。こうした住民の声を区議会から国に届けるために、一旦海上ルートに戻す意見書を提出すべきですので、採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-071"},{"speaker":"のだて委員","kind":"質問・要望","question":"本日結論を出すということで、採択を主張します。羽田新ルートは撤回すべきだと考えますし、被害の多い品川区が国に求めることが撤回への力になると考えますので、採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-072"},{"speaker":"のだて委員","kind":"質問・要望","question":"本日結論を出すということで、採択を主張します。一時凍結を求めるというものですけれども、少なくとも一旦中止すべきだと考えますので、採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-073"},{"speaker":"のだて委員","kind":"意見","question":"この状況を一刻も早く改善する必要がありますので、採択です。ほかの理由は、令和４年陳情第４号と同様ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-074"},{"speaker":"のだて委員","kind":"意見","question":"国の検討会では品川上空を回避することはできず、結論が出るまで待っていることが固定化になっています。この羽田新ルートは撤回こそすべきですので、採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-075"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/372951?Template=document&Id=4372#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":61716,"voices":313}},{"id":"r05-20230227-9","meetingId":"r05-cm02","date":"2023年2月27日","dateIso":"2023-02-27","committee":"文教委員会","time":"午前１０時００分～午後 ２時１１分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を62件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"田中委員","kind":"確認","question":"西村直子議員の２月２２日の質問の中で、品川区教育委員会とアンケート内容を確認していくといったご答弁があったと思うので、今の品川区教育委員会とのアンケートの調整の状況などをお知らせいただければと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"}]},{"id":"topic-02","title":"第２６号議案 品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","agenda":"第２６号議案 品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"確認なのですが、現在非常勤ということだということなのですけれども、どんな仕事を週にどれぐらいされているのか。どれぐらいお支払いされているのかというのと、あと、各学校にどれぐらい配置されているのかという配置状況などを説明を求めました。","respondent":"勝亦学務課長","answer":"薬剤師を各小中学校各１名、義務教育学校等、大きな学校につきましては内科医と歯科医を１名ずつ加配しています。現在、学校を兼ねている方もいらっしゃいますけれども、２１７名の方に従事いただいている状況です。","id":"exchange-002"},{"speaker":"田中委員","kind":"確認","question":"ほかの１５年以上の方たちに対しては、どうして都の条例でも変わらなかったということは、特に都からの説明などはなかったということですか。確認させてください。","respondent":"勝亦学務課長","answer":"こちらの学校医の条例に関しての引上げがなかった部分については、都からの説明はございません。東京都の人事委員会勧告が、若年層について引上げをしまして、それ以上の方については改定されていませんので、現状維持という形になってあります。","id":"exchange-003"},{"speaker":"田中委員","kind":"意見","question":"ごめんなさい、１点だけ。何で義務教育学校だけ多く配置されているのかという部分を知りたいですとの意見を述べました。","respondent":"勝亦学務課長","answer":"義務教育学校につきましては、小中学校、９年間が同居して生徒数が多うありますので、内科医と歯科医を１名ずつ多く配置しているです。","id":"exchange-004"}]},{"id":"topic-03","title":"区立学校における３月１３日以降の教育活動","agenda":"区立学校における３月１３日以降の教育活動","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"１つ、まだ４月１日以降は詳しい国の方針が出ていないので、これからそれを見て考えるということなのでしょうかというのが聞きたい。裏のチラシなのですけれども、具体的にはどのような規模でどういう感じで周知して、どれぐらい徹底されていると感じているのか伺いたいと思います。","respondent":"矢部教育総合支援センター長","answer":"そんなにゆっくり出てこないとは思っていますので、こちらも構えてはおりますけれども、国の方針を大事にしたいというところが１点目です。その辺りの配布の仕方は学校によりますけれども、全校が保護者に伝わるように連絡する予定で指示しております。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問","question":"１つ伺いたいのは、その両立というのですか、学校での感染を防ぐ対策というのはどういうふうにしていくのか伺いたいのが１つです。特にコミュニケーション等の心理的な影響、発達への影響というのはどのように考えていらっしゃるのか、伺いたいと思います。","respondent":"矢部教育総合支援センター長","answer":"せきエチケットとか、３密を防ぐというのは、これまでどおり進めてまいりたいと考えています。観察を進めて、声はかけたり相談に応じてきたりということで、ケアをしてきたつもりです。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問","question":"私が伺ったのは３月３１日以降の話なのですけれども、それ以降の感染対策はどうするお考えなのかというのを伺ったので、もう一回聞きます。ある程度していく必要があるのではないかなと思うのですけれども、その辺については具体的にはどのようなことを行うのか伺いたいと思います。","respondent":"矢部教育総合支援センター長","answer":"３点目、地域の方たちの集まりが年６回ありますので、また町会長などにお願い申し上げまして周知していくということは大切かと思います。時間がたつと理解も進んでいくのかなとは思っておりますので、そこは大切に、４月以降もしっかりやってまいりたいと考えています。","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問・要望","question":"陳情者の方にもお話を伺ったのですが、黙食について、給食のルールは今どうなっているのか。各学校によっての現状というのですか、実際どうなっているかというのは、分かる範囲でいいけれども教えてほしいと求めました。","respondent":"矢部教育総合支援センター長","answer":"学校によっては、お声でもう、そんなことを全校で周知したということも保護者から聞いておりますので、できていると認識しております。２月９日に校長連絡会があったのですが、少なくとも学校の中で隣のクラスと対応が違うようなことがないようにと、改めて伝えたところです。","id":"exchange-008"},{"speaker":"安藤委員","kind":"質問","question":"この陳情者の方が在校生の保護者から聞き取りをしたそうなのですが、３８校中のうち２７校の聞き取りができて、３校しかないということらしいのです。その辺はフォローアップというか、品川区教育委員会としてはどこまで把握しているのかというのは、再度お伺いしたいと思います。","respondent":"矢部教育総合支援センター長","answer":"２月９日の時点では、その後についてはしっかりできていると認識しておりますし、このとおりに進むと認識しております。個々に対応がございましたら、我々のほうできちんと受けて対応してまいりたいと考えています。","id":"exchange-009"},{"speaker":"田中委員","kind":"質問・要望","question":"配布するときにきちんと説明が、先生から子どもたちに対して、そういったお話があったのか。「きちんと説明をして、このチラシを渡してください」といったお知らせがあったのかという部分を、まず確認させてほしいと求めました。","respondent":"矢部教育総合支援センター長","answer":"学校には少し詳しい説明資料と、保護者宛てにきちんと配られておりますので、このチラシだけが単独で行くということはございません。繰り返しますが、個別にもしも足らないところがありましたら対応したいと思いますけれども、ただ配布ということではないと認識しています。","id":"exchange-010"},{"speaker":"田中委員","kind":"確認","question":"確認したいのですけれども、こういった暴力が本当にあった事実があるのかというところを確認したいのと、これは絶対やってはいけないことですよね。それで、学校や教育委員会に個別に相談しても解決に至らないケースがあるということも書かれているのですが、ここの事実関係を伺いたいと思います。","respondent":"矢部教育総合支援センター長","answer":"ただ、全て全件、センターでお預かりしているということではございません。調べられる範囲のところで確認しています。","id":"exchange-011"},{"speaker":"田中委員","kind":"質問・要望","question":"やはりそれはどうなのだろうと思いますし、あした体罰調査のことも出ますけれども、やはり席替えなども子どもたちはあるじゃないですか。そういったところを、もう一回確認させていただきたいのですけれども、いかがか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"保護者から、窓際や廊下がいいという方もいらっしゃるので、当然、保護者やご本人には聞いているものと認識しています。基本的にはそういう理解を促した中で進めていくと考えておりますので、急に「あなたはここ」ということはないと、どう考えても思っております。","id":"exchange-012"},{"speaker":"田中委員","kind":"質問・要望","question":"１点、ここは矛盾しているのではないかなということを感じたので伺いたいのですけれども、どうなのでしょう。４月頃にまたピークが来るという予測も立てられていますし、そういったことも考えて、どうなのかなというところを伺いたいと思います。","respondent":"矢部教育総合支援センター長","answer":"基本的な考え方は、式全体を通してマスクを外すことを基本とするということですので、その場合は外していいと。ほぼ隣でおしゃべりするような指導はしないので、厳粛な雰囲気の中でやることになっていることから、このような対応をしております。","id":"exchange-013"},{"speaker":"渡部委員","kind":"質問・要望","question":"もう５日はちょっと間に合わないかもしれないから、３月２０日にぜひ、私はこのままでいいと思います。それがいいかななどと勝手に思うのですが、ちょっとその辺を考えていただきたいと思うのですが、お答えだけすみません。","respondent":"矢部教育総合支援センター長","answer":"１点目、配布時期ですが、各学校には今月末までということで、あしたまでに配布することになってあります。２点目につきましては、ご意向を理解しましたので、関係の課と連携して検討したいと思います。","id":"exchange-014"},{"speaker":"若林委員","kind":"質問・要望","question":"コロナが３年前に発生して、学校の中で、マスクについての様々なこういう事案が発生していると。子どもにも保護者にも理解していただくということを、いま一度確認させていただきたいなということで、では一回答弁を。","respondent":"矢部教育総合支援センター長","answer":"委員がおっしゃるとおり、これはいじめの防止または解決ということに向けての通知で、特にこのパンフレットについては、そのとおりです。いろいろな形で、いじめ防止については進めていかなくてはいけませんので、また発生した場合は解決に力を入れていきたいと考えています。","id":"exchange-015"},{"speaker":"若林委員","kind":"質問","question":"もしあるのであれば、それは払拭しないといけないという意味で、１問目の質疑をさせていただきました。何ですか、１つあるのかなと思いましたので、もし何かございましたらご答弁ほしいと求めました。","respondent":"矢部教育総合支援センター長","answer":"学識経験者の大学の先生や町会長、また民生委員、またそれぞれの専門的な見地を持った方もいらっしゃいます。人権擁護委員の方とも連携していますので、様々な視点でご意見を頂きながら、子どもたちの安全安心を守れるように努めてまいります。","id":"exchange-016"},{"speaker":"松澤副委員長","kind":"質問・要望","question":"緑のおじさんというのですか、「どういう感じですか」と言うと、知っている方がいらっしゃらなかったというのが現状なのです。地域でこういうふうにやっていただきたいというのを、強く要望していくというのですか、改めてさらにやっていただけたらと思います。","respondent":"矢部教育総合支援センター長","answer":"地域の方にもご理解が必要かなと考えていますので、関係課と連携して検討いたします。","id":"exchange-017"},{"speaker":"江野下委員","kind":"質問・要望","question":"連合会や総会などがあるので、そういうときにも周知していただいたり、中学校ももちろんそうです。今、啓発で地域の学校と連携している広め方もありますので、そういったところも要望をお願いいたします。","respondent":"矢部教育総合支援センター長","answer":"様々なお知恵を頂きましたので、関係課と連携して進めてまいります。","id":"exchange-018"},{"speaker":"渡部委員","kind":"意見","question":"私どもの３名からもお話しさせていただきましたが、地域の見守りの中でどうしていくかというステップに移行もしていくのかなというところもあります。もう３月１３日以降、品川区では４月１日以降、不採択でお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"若林委員","kind":"質問","question":"陳情の要旨、趣旨、それから、私も含めて各委員から、様々な具体的なこと、また本質的なこともご指摘させていただきました。教育委員会にはしっかりと受け止めていただいて、今後、着実な、確実な運用・施策が進んでいくと理解いたしますので、そういう理由です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問","question":"やはりこういう内容というのは、今後も何度も発信すべきことだと私は思いますし、啓発を強めるべきだと思います。もっとさらに徹底してもらいたいわけですから、ありなのではないか、そうあるべきなのではないかなと私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"田中委員","kind":"質問・要望","question":"教育委員会でもお知らせをしていただいているというのも確認はできていますが、やはり、それをもっと進めていく。一緒に、その必要性ということを、品川区教育委員会としても区としても、持っていただきたいなということを強く求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"第１２号議案ですけれども、運営を委託していると思うのですけれども、これは区になるのでしょうかということを伺いたいというのが第１２号議案。第１６号議案ですが、第１６号議案のほうですけれども、具体的には何が含まれているのか伺いたいと思います。","respondent":"廣田子ども育成課長、中元保育支援課長","answer":"取り組むことについては同様で、今、準備しているところです。２つ目の、責任は区にあり、責任を持って委託事業者にやっていただくというような形となっています。 懲戒権の改正の理由と背景ですが、まず民法改正のところから説明します。こちらは、懲らしめ戒めるという強力な権利であるとの印象を与えるというところもあったところで、そこを改正するということで説明を受けてあります。","id":"exchange-023"},{"speaker":"田中委員","kind":"質問・要望","question":"これはとても、せっかく計画を立てるのであれば、これは保護者などにも見えるような形にすることは可能なのかというところを伺いたいと思います。保護者に対してもきちんと周知していただきたいなというところと、削除をずっと求めていた側は、どうしても本当によかったということを思っています。","respondent":"廣田子ども育成課長","answer":"そこに安全の部分は規定されていたので、なかったわけではなくて、これまでも安全に対する規定は定められていたというところが１つです。","id":"exchange-024"},{"speaker":"田中委員","kind":"確認","question":"この安全計画の周知について、今どういったことが想定されるのか。それともホームページなどでも広く公開されるものなのかといったところも確認できたらと思うのですが、いかがか尋ねました。","respondent":"廣田子ども育成課長","answer":"まだ策定が令和５年度４月、令和６年４月からが義務づけになりますので、具体的にはこれから検討しようと考えています。","id":"exchange-025"},{"speaker":"渡部委員","kind":"質問","question":"委員長、すみません。ある程度、同程度の内容のことが日本全国で起こっているのか、分かればでいいので説明を求めました。","respondent":"廣田子ども育成課長","answer":"届出をしたところに関しては縛られるはずなのですけれども、区の中で届出をして持ってきた民間業者は１個だけです。調べ切っていないので、断言していいかはあれなのですけれども、ここでは該当ではないです。","id":"exchange-026"},{"speaker":"田中委員","kind":"質問","question":"第１６号議案のところで、先ほど対象について質疑があったと思うのですけれども、不勉強でごめんなさい。伺いたいのですけれども、今回の条例のところも反映されるのかどうかというところを伺いたいのですが、いかがか尋ねました。","respondent":"中元保育支援課長","answer":"ぷりすくーる西五反田も対象となります。","id":"exchange-027"},{"speaker":"安藤委員","kind":"提案","question":"それと、プレス発表では、認証保育園も同程度の助成とありましたけれども、いつ頃どのような手だてで助成するのでしょうかというのが２点目です。","respondent":"立木保育課長、中元保育支援課長","answer":"今回の条例改正によりまして、４月から９月までの間に関しては歳入が減という形になる予定です。第１子のことに関しまして… 認証保育所の部分につきまして、私からご説明申し上げます。ただし、残りの４,０００円分につきましては保護者の方に負担いただくという形になってまいり… ちょっと補足をさせていただきたいと思います。","id":"exchange-028"},{"speaker":"安藤委員","kind":"質問","question":"そういうことを伺うと、なぜ第１子から保育料を取るのでしょうか。伺いたいと思います。","respondent":"立木保育課長","answer":"そこへの充当が４億６,８００万円分、いわゆる、それが持ち出しという形にはなるかとは思っております。第１子の無償化につきましては、今のところは検討はされておりませんが、今後の社会情勢等を見ながら、注視していきたいと考えているところです。","id":"exchange-029"},{"speaker":"安藤委員","kind":"質問・要望","question":"お金がかかって、産みたくても産めないという方がたくさんいらっしゃるということです。ですから、ぜひさらなる強化へ、第１子保育料の無償化に向けてもぜひ検討してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"}]},{"id":"topic-04","title":"令和５年請願第１号 一人ひとりの子どもが大切にされる品川区を求める請願","agenda":"令和５年請願第１号 一人ひとりの子どもが大切にされる品川区を求める請願","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"改めて、一人ひとり子どもたちを大切にする保育環境をさらに進めてほしいという、区民の皆さんの強い願いなのだなということを実感しています。保護者の声で、伊藤幼稚園については応募が１年延長されましたけれども、新年度の伊藤幼稚園の応募人数の現状について説明を求めました。","respondent":"立木保育課長","answer":"保育園の在り方の検討のところですが、今、庁内のプロジェクトチームのような形でスタートしています。来年度、検討委員会という形でやっていきたいなと思っているところです。","id":"exchange-031"},{"speaker":"安藤委員","kind":"質問・要望","question":"それと、区立幼稚園３園の閉園方針なのですけれども、確認したいのですけれども、森澤区長に一応、区長が替わったわけです。その辺は指示などはないのですかというのを確認させてください。","respondent":"立木保育課長","answer":"在り方検討のプロジェクトですが、今のところ３回ほどやってあります。区立幼稚園３園の閉園方針につきましては、区としましては今のところ、変更の予定はございません。","id":"exchange-032"},{"speaker":"安藤委員","kind":"質問","question":"私が伺ったのは、最後の質問ですけれども、変更がないということは、つまり新しい子育て支援を大きく打ち出す新区長になったとしても、その新区長から、区立幼稚園の閉園するという方針について、見直してくださいとか検討してくださいということはなかったということなのか、伺いたいと思います。","respondent":"立木保育課長","answer":"繰り返しになってしまいますが、区の方針としましては、今のところ変更はございません。","id":"exchange-033"},{"speaker":"安藤委員","kind":"質問","question":"区として実態を把握されているのでしょうか。伺いたいと思います。","respondent":"初貝保育教育運営担当課長","answer":"基本的には大きな変更がないような形で、まずは進めさせていただいて、徐々に独自の色を出していくというような形で進めているところです。","id":"exchange-034"},{"speaker":"安藤委員","kind":"質問・要望","question":"さらに保育士の待遇にも関わるのですけれども、給食の費用をちょっと削ってしまおうというふうなことになり得るということなのでしょうか。そうすると、すごく心配なのですけれども、伺いたいというのがあります。","respondent":"初貝保育教育運営担当課長","answer":"区でもきちんと把握した上で、必要であればきちんと内容を確認して適切に対応していくというような形で、保護者にも不安を与えないような形で進めていっているところです。","id":"exchange-035"},{"speaker":"安藤委員","kind":"質問・要望","question":"どうなっているのかというのを伺いたいというのが１つ思います。私は、この請願が求めているように、独自の手厚い基準というのをつくって、さらなる保育環境の改善をすべきだと思いますけれども、いかがか尋ねました。","respondent":"立木保育課長、中元保育支援課長","answer":"弾力化の部分に関しましては、認可保育園に関しましては、ほぼ弾力化は解消している状態です。ほぼ全ての園で弾力化は解消の方向で、今、進んでいるところです。 平均約２名ぐらい多く配置していますので、平均して国基準より２名多く配置しているところもありますので、国の動向等を注視してまいりたいと考えているところです。","id":"exchange-036"},{"speaker":"安藤委員","kind":"質問・要望","question":"様々いろいろお声を伺って造っていると言いますが、様々たくさん増えた保育園の乳幼児の遊びの場としての確保という点では十分だとお考えなのか。そこを最後、３点目で伺いたいと思います。","respondent":"中元保育支援課長","answer":"土地利用の状況と、ここまで待機児童ゼロに行くまでの保育園の充実は難しかったのかなというのが現状にあるというところを認識しています。今、保育園同士でもきちんと時間など相談しながら活用していますので、乳幼児が行けないということはないという認識です。","id":"exchange-037"},{"speaker":"田中委員","kind":"質問","question":"正しいというか、正当であるかというところについて、区としてのお考えを伺いたいと思います。区内の保育園の何園でそういったことがされているのかということを伺いたいと思います。","respondent":"中元保育支援課長","answer":"２名加配の部分は、ほぼ全園で配置されております。安全に関して、園庭、様々な形で現場の充実・拡充に努めてまいりたいと考えているところです。","id":"exchange-038"},{"speaker":"田中委員","kind":"質問・要望","question":"手が足りておらず、ぜひ区としての配置基準を打ち出すということは、本当にしていただきたいなということを強く求めたいと思います。いろいろな方、保育に関わっている方たちが参加できるような検討委員会にしていただきたいと思うのですが、伺いたいと思います。","respondent":"立木保育課長","answer":"丁寧な説明をしながら進めていくということで考えておりますので、そのような形でやらせていただきたいと考えています。今のところ、今後いろいろな状況等を見ながら、そういったところも検討してまいりたいと思います。","id":"exchange-039"},{"speaker":"田中委員","kind":"質問・要望","question":"今の３回の検討状況は、あと委員会でも資料提供をしていただきたいと思うのですけれども、そこについても伺いたいと思います。遊べる、公園の確保というのは進めてほしいと求めましたが、いかがか尋ねました。","respondent":"立木保育課長、中元保育支援課長、高梨公園課長","answer":"今のところ、まだ詳細を詰めておりませんので、今の段階でお話しできるところはございません。今のところ難しいかなと考えていますが… 実態はつかんでいるのですが、手持ちで補助の実績を現在持ってございませんので、回答を差し控えします。 昨年１２月にオープンした旗の台六丁目の旗六公園におきましては、あと、現在設計中で来年度から整備を予定しております西五反田公園におきましては。","id":"exchange-040"},{"speaker":"田中委員","kind":"質問・要望","question":"旅と言っていいのかあれですけれども。ぜひ広い範囲で保育園の方たちにお知らせしてほしいし、ご意見を聴取していただきたいと思うのですが、いかがか尋ねました。","respondent":"高梨公園課長","answer":"公園におきましては、その公園の規模に応じて、小さい公園であれば周辺の近所の方々に使っていただきたい。高齢者の方も利用するといったところもありますので、公園の規模に応じて、意見収集の範囲というものは適宜定めてまいりたいと考えております。","id":"exchange-041"},{"speaker":"田中委員","kind":"質問・要望","question":"ぜひ細かな情報発信をしていただきたいと思うのですけれども、その情報の発信の在り方とか、スケジュールについても再度伺いたいと思います。そもそも民間事業者の選定基準というのが、どうされているのかという部分を伺いたいのですけれども、いかがでしょう。","respondent":"高梨公園課長、立木保育課長、初貝保育教育運営担当課長","answer":"最初のご質問ですが、やはり小さな１区画ぐらいの公園で、区内全域の保育園から聞くなどというのは、なかなか難しいこともあります。周辺の皆様の声… 進め方につきましては、丁寧な説明等を心がけて、検討はしっかりやっていきたいと考えています。 もちろんその中で保育の質や、あとは今までの実績など、様々な視点で業者の方を選んでいるというような状況です。","id":"exchange-042"},{"speaker":"田中委員","kind":"質問・要望","question":"保育の質という視点で、どういった保育の質を品川区として求めているのか。そうではなくて、とても保育に手厚いなどといった調査がきちんとされて選定がされているのかという部分を伺いたいと思うのですが、いかがか尋ねました。","respondent":"初貝保育教育運営担当課長","answer":"品川区では、品川区の今までやってきた保育というところをきちんと引き継いでいただけるような事業者というところで選定しております。後段の説明のところで言いますと、そういった視点で事業者をお選びさせていただいているというような状況です。","id":"exchange-043"},{"speaker":"田中委員","kind":"質問・要望","question":"最後、要望にとどめます。それで、そういった選定基準をきちんと設けていただきたいということを強く求めて終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"渡部委員","kind":"意見","question":"では３歳児・４歳児がどうなのかという話もありますけれども、皆さん、保護者の方が選ばれていますからね。それはそれとして置いておいて、この請願自体はそういうことで、不採択でよろしいかと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-045"},{"speaker":"若林委員","kind":"意見","question":"３番については、本当に１年で１,０００人単位の拡大を、もう真っ先に手を挙げてやろうと。引き続き、できる限り今後とも健全保育に向けてご努力は賜りたいなと申し上げて終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"},{"speaker":"安藤委員","kind":"意見","question":"やはり、基準についても現状維持で、これ以上やるつもりはないというようなところが出てまいりました。これは採択して、しっかり区の姿勢を政策に反映させていきたいと考えていますので、採択を主張しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-047"},{"speaker":"田中委員","kind":"質問・要望","question":"これまでの不採択の理由なども伺ったり、今の基準がいいとは思ってはいないだろうなということが、とても共通認識だと思うのです。子どもも含めた品川区民、ぜひ庁内での連携を強めていただきたいなと強く要望して、この請願は採択を主張します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"}]},{"id":"topic-05","title":"令和２年陳情第４７号 離婚等のこども養育支援にかかる陳情","agenda":"令和２年陳情第４７号 離婚等のこども養育支援にかかる陳情","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"それで、これは何か事業名というのはあるのでしょうか。相談件数と、うち面会交流の相談というのは大体、年間なのか、どれぐらいあるのか伺いたいと思います。","respondent":"飛田子育て応援課長","answer":"こちらの元家庭裁判所の調査官というのは、たしか令和２年か令和３年、はっきり申すことはできないのですが。令和３年度は６件だったのですが、令和４年度は、既に１２件の方がこの制度を使っているというような数字となっております。","id":"exchange-049"},{"speaker":"安藤委員","kind":"質問・要望","question":"支援を拡充したことで、表に相談になっていなかったものが、実は結構あったのだなということが目に見えるようになったのかなという印象を受けました。８８件、面会交流の支援を行ってほしいというような相談というのは、もしあればということを教えていただきたいのと。","respondent":"飛田子育て応援課長","answer":"行政の一般職員が支援を実施して、室長と係長は弁護士の資格のある人ということです。これは令和２年度より開始したということですが、今年度は１件だけで、そういうことと聞いています。","id":"exchange-050"},{"speaker":"安藤委員","kind":"質問・要望","question":"まさにそういうことを求めているのかなということで、具体的な事例として、要望として議会にかかっていると私は認識しております。ただ、品川区としても交流支援をさらに進めるような体制充実を行っていっていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"飛田子育て応援課長","answer":"本当に、面会交流は子どもにとってはとても大事なのは、しっかり認識しているところです。そういうのを見てしまうと、なかなか一歩、踏み出せないのが現状です。","id":"exchange-051"},{"speaker":"安藤委員","kind":"質問・要望","question":"大変慎重な対応が求められるのは間違いないので、すごく、そういう意味では専門性というのを積み重ねていかなくてはいけない事業だと思います。進めていくべき事業だと思いますので、しっかりした体制をつくることを前提に、進めていっていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"田中委員","kind":"確認","question":"区の今の養育費相談支援事業については確認できました。この３つで、拡充していくという考えがあるのかどうかを、まず確認させてください。","respondent":"飛田子育て応援課長","answer":"今のところ、まず国も審議が止まってしまっている状態なので、そこのところを見ながら、ある程度、国で法整備などが整ったら、またそこは、それを見て考えていきたいと考えています。","id":"exchange-053"},{"speaker":"田中委員","kind":"質問","question":"月曜日の午前９時から午後１時まで、木・金曜日の午後１時から５時までで、今後検討というところでしょうか。相談したいけど、なかなかこの時間帯では行けないという方もいらっしゃるのではないかなということを思うのですけれども、いかがか尋ねました。","respondent":"飛田子育て応援課長","answer":"相談を受け付けている時間はこの時間ですよ」というご説明はしていますが、時差出勤など、そういうところで対応しています。","id":"exchange-054"},{"speaker":"田中委員","kind":"質問・要望","question":"確認されました。今後はきちんと整備していっていただきたいなと思うのですけれども、もしお答えできれば、していただければと思うのですが。","respondent":"飛田子育て応援課長","answer":"子どもだと子ども家庭支援センターで、そういう状況を聞き取ったりキャッチした場合、そういうところで連携を取りながらやっています。そういうところをする予定なので、そういうところで連携をより強めて、図ろうと考えております。","id":"exchange-055"},{"speaker":"田中委員","kind":"意見","question":"そういった聞き取りなどもきちんとして、拡充していただいてということ、子どもたちのための制度になることを本当に願っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-056"},{"speaker":"渡部委員","kind":"質問・要望","question":"先に意見を述べしますけれども、冒頭、この陳情に関して、過去２度ですか、今回３度目になるのでしょうか。確かに、会わせろと求めたところで会わせられないケースというのも多々生じることがあるわけですから、少し違うと思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"若林委員","kind":"質問","question":"実績もお聞きして、今ここで品川区が踏み込むということはちょっと判断できないのかな。ただ、ここまで継続してきて、今後の推移も、いわゆる国や都の動向も注視しながらという意味では、継続扱いということで、私は結構だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"安藤委員","kind":"質問・要望","question":"過去２回も私たちはそういうふうに求めているのですけれども、子ども自身の意思をきちんと尊重できる体制をつくらなくてはいけないと思っています。ぜひ品川区としても、その努力に踏み出していただきたいという思いがありますので、採択を主張したいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"田中委員","kind":"質問","question":"これまでも、特に子どもの声をきちんと聞き取って、そういった仕組みを整備していってほしいなという願いも込めての採択を主張したいと思います。区でもご両親にお話を伺うなど、やはり子どもたちの声もきちんと聞いていただける仕組みがもっと充実できたらいいなという願いを込めてです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"}]},{"id":"topic-06","title":"その他","agenda":"その他","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"子ども食堂ネットワークにお渡しして、そこからというところをもう一回確認したいのと、あと区内商品券を使える場所というのが拡充されたのかなと。その状況も確認させてほしいと求めました。","respondent":"飛田子育て応援課長","answer":"区が商品券を購入して、子ども食堂ネットワークを通じて、各子ども食堂に配ったということです。そういうところで、逆にウィン・ウィンみたいな感じで、商品券という声があったのかなと考えています。","id":"exchange-061"},{"speaker":"田中委員","kind":"質問","question":"商品券を使った子ども食堂からの利用の状況とか、実績というのですか、もしあれば説明を求めました。","respondent":"飛田子育て応援課長","answer":"実績は３月末に報告してくださいということですので、まだこちらには来ていないのですけれども、非常に評判がいいです。","id":"exchange-062"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/106437?Template=document&Id=5092#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":52968,"voices":222}},{"id":"r05-20230227-5","meetingId":"r05-cm02","date":"2023年2月27日","dateIso":"2023-02-27","committee":"総務委員会","time":"午前１０時００分～午後 ０時３３分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を56件整理しています。","topics":[{"id":"topic-01","title":"冒頭に申し上げましたとおり、取り上げる順番を変更して行います。 初めに、(2)第２７号議案、ファミーユ西五反田西館高層棟ほか外壁改修その他工事請負契約","agenda":"冒頭に申し上げましたとおり、取り上げる順番を変更して行います。 初めに、(2)第２７号議案、ファミーユ西五反田西館高層棟ほか外壁改修その他工事請負契約","exchanges":[{"speaker":"吉田委員","kind":"質問・要望","question":"それを活かしてきちんとその次につなげてほしいという趣旨で質問などをしたつもりだったのですが、よく理解していただけなかったのです。そのような周知もしていただきたいと思うのですけれども、それとも区のほうの責任になるのか、その辺のことについて伺いたいと思います。","respondent":"小林施設整備課長","answer":"まず、住まわれている方に対する周知につきましては、この２月に一度説明会等を開催しています。この後、契約が終わり次第、また４月に改めて説明をする予定です。","id":"exchange-001"},{"speaker":"吉田委員","kind":"意見","question":"ただ、その事故が起きた当時も、そのようなことはされていたのではないかと思うのです。金額としてその中に入っているのだと思いますが、それに上回って、ぜひきちんと区としてもその辺を徹底してほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"須貝委員","kind":"意見","question":"今回、外壁改修工事で浮きおよび欠損が見受けられた箇所があったというような話なのですが、築何年で、メンテナンスというものは定期的にやられていると思うのですけれども、何年ぐらいでやっているのか、説明を求めました。","respondent":"小林施設整備課長、竹田住宅課長","answer":"私のほうから、築年数についてご説明いたします。本施設につきましては、資料に記載のとおり、平成１５年１２月に竣工していますので、およそ２０年弱が経過した建物だと考えています。 点検についてご説明いたします。定期的な点検によって不具合等が発見される場合もありますので、計画的な修繕等に活かしています。","id":"exchange-003"},{"speaker":"須貝委員","kind":"確認","question":"１０年に１回ぐらいは全体を見て確認をして、外装も確認していると思うのですが、ちょっといかがなものかなと私は思うのです。やはりタイルというものはあくまで接着しているわけですから、浮きが出てくれば、もちろん落下するおそれというものは可能性は高いわけですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"大倉委員","kind":"確認","question":"確認なのですが、先ほども築２０年と。タイルがいい悪いということではなくて、こういったものを確認をしながら箇所数を数えていくのだと、積み上げていくのだと思うのです。","respondent":"小林施設整備課長","answer":"いずれ何か地震があったり、あるいは何か挙動があったときに落下するおそれがあるということで、今回施すものです。１０年に一度、これは建築基準法上決まってありますので、そういったタイミングの中でしっかりと対応していくことになるかと考えています。","id":"exchange-005"},{"speaker":"大倉委員","kind":"確認","question":"効果的に、効率的に、修繕するところをきちんと選びながら行っていくということでよろしいでしょうか。確認です。","respondent":"小林施設整備課長","answer":"おっしゃるとおりで、一番合理的に、計画的に進めていきながら、修繕を行っていくというふうに考えてあります。","id":"exchange-006"}]},{"id":"topic-02","title":"専決処分の報告","agenda":"専決処分の報告","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"５の変更概要というところで少し具体的に伺いたいのですが、工期内の賃金というのは、上がったということなのでしょうか。そこの賃金がどうなったのかということを教えていただきたいということと、また、これは様々な資材の高騰ということなのか尋ねました。","respondent":"森学校施設担当課長、東野経理課長","answer":"もともとはコストの低いタイプを考えていたのですけれども、かなり頑丈な土留め工法に変更して安全性を高めたという工事を行っております。地下通路撤去で３,０００万円ほど… 工事請負契約条項第２５条に、契約の変更の仕方について触れている条項があります。こちらの案件につきましては、賃金の上昇、大体この２月から３月ぐらいに、国のほうから設計労務単価の変更について発表があります。","id":"exchange-007"},{"speaker":"須貝委員","kind":"質問","question":"非常に違和感があるのですが、その辺はどうですか。その辺の見解を教えていただけますか。","respondent":"森学校施設担当課長、東野経理課長","answer":"そのときに既に支払いが、インフレスライドしてほしいということで申告があって加配をしている、そのようなことになります。そのようなことを強く言うことも恐らくはできませんので、工事を止めることなく進めていくためにも… 先ほどお話しさせていただきました設計労務単価、国が発表するものを受けた形でのスライドという形を取ってあります。","id":"exchange-008"},{"speaker":"須貝委員","kind":"質問・要望","question":"区でもこのように承認しているわけですから、やはりできるだけ工事費が上がらないような工夫を業者に求めることは、私は大事ではないかなと思います。これは議論してもしようがないので、一応これで意見だけ言わせていただきます。","respondent":"東野経理課長","answer":"今委員がおっしゃったところにつきましては、恐らく単品スライドのことかなと思われます。一定の資材につきまして単品スライドの適用ということがありますので、それにつきましては、区としては適正に対応をしてまいりたいと思います。","id":"exchange-009"},{"speaker":"吉田委員","kind":"質問","question":"この地下通路についての資料があるとしたら、いずれ工事というものは必要になるわけですから、どこが用意しておかなければいけないのかなと思って。その辺についてちょっと伺いたいと思います。","respondent":"森学校施設担当課長","answer":"この地下通路が造られましたのが、恐らく昭和３０年前後ぐらいだなとは思っておりまして、とても古いものだと思われます。資料がないことも多くございまして、できる限りいろいろ調査はしているのですけれども、この地下通路については何も資料がなかったです。","id":"exchange-010"},{"speaker":"吉田委員","kind":"質問・要望","question":"それはもう今の職員の方の責任ではないので、今後このようなことが起きないように、ぜひその辺はしっかりしていただきたいなと思います。これは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"}]},{"id":"topic-03","title":"専決処分の報告について（報告第２号）","agenda":"専決処分の報告について（報告第２号）","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問","question":"このような場合は、建設発生土は産業廃棄物になるということでいいのでしょうか。それが水分を多く含んだことで、どのような処分になってどれぐらい費用が増えたのかを説明を求めました。","respondent":"森学校施設担当課長","answer":"ですから、校庭に２０cmぐらい水をためて浸透させていくということをずっと、今も行っている状態です。それから滞水しやすい場所だったのだろうということから、含水率が高い影響で第４種建設発生土というように変更されて、搬出しております。","id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"どのようなところでこの建設発生土というものが出るのかよく分からないのですけれども、下水道などは産業廃棄物になるというようなことで聞いたのですが、これは産業廃棄物にはならないということですと、どのような形でどれぐらいの土が出て、どのように処分されるのかということを説明を求めました。","respondent":"森学校施設担当課長","answer":"ただ、その搬出するときや受け入れるときに時間がかかったりしますので、発生処分代が高いということになります。そのまますぐ転用はできませんので、置いておく分等だと思うのですけれども、処分費として６,０００万円ぐらい増になったということです。","id":"exchange-013"},{"speaker":"大倉委員","kind":"確認","question":"いろいろお話聞いた中で、これによる工期の遅れや工期への影響などというものがあるのでしょうか。そこだけ確認をさせてください。","respondent":"森学校施設担当課長","answer":"工期の影響はないように、今工事を進めておりますので、全体の工期の中で調整していくような状況です。工期の延伸は基本的にはございません。","id":"exchange-014"}]},{"id":"topic-04","title":"第１０号議案、品川区職員定数条例の一部を改正する条例","agenda":"第１０号議案、品川区職員定数条例の一部を改正する条例","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"児童相談所について伺いたいと思います。それとも全て民間活用しないで、直営の職員の人員の確保ということでいくのか、その点について伺いたいと思います。","respondent":"崎村人事課長","answer":"例えば児童相談所を先行して設置した区については、児童相談所とは別に設置をしてやっていたりもしますので、事務職が何人。一概に民間委託をどこで進めるかというところで、委託については、また別途考えていく必要があるのかなと考えているところです。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この基本方針のところでは、結構重要なところを、民間に委託できるところは委託を検討するというような内容だったのです。それから虐待通告を受けたあとの安全確認、効率的、この考え方がどのようなことになっているのかなということを伺いたかったのです。","respondent":"鈴木（真）委員長","answer":"それは文教委員会の所管にかなり深く入っていく部分があるので、人事課として答えられる範囲で。細かく入ってしまうと答えられない部分だと思いますので。","id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"民間委託できるところは民間を検討するというようなことでの前の答弁があって、気になっていたところだったので確認をさせていただきました。ちょっとそのスケジュール感というか、達成度合というか、その辺をお聞かせいただけたらと思います。","respondent":"崎村人事課長","answer":"令和６年度、令和６年４月１日に採用する分で、児童相談所の開設に向けた職員の確保は図られるものというふうに考えております。大体１５名程度、大体５名ぐらい採用できる予定ですので、予定どおり採用できてきているというふうにはお話しできるのかなと考えています。","id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それから保育園の民営化で、今回保育士が１４名、定数が削減になるということなのですけれども、その点について伺いたいと思います。人件費がどれだけ削減されたのかとか、そのような検証がされているのか、その点についても伺いたいと思います。","respondent":"崎村人事課長","answer":"令和３年度、令和４年度については、まずございませんでした。保育課のほうで検証されているかと思いますが、特に人事課のほうで何か把握しているというものではございません。","id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"でも、区としての保育士の定数というのは何名になるのかということが分かったら教えてほしいと求めました。そこの委託先の保育士の賃金がどうなるということは、区としては把握されているのか、その点も伺いたいと思います。","respondent":"崎村人事課長","answer":"この５年間で５園、そういったところの検証の途中経過や結果について人事課と共有して、今後について検討していきたいと思っています。約６００名ほどいる中で、今回定数を６８人減していく中で、大体５３０人か５４０人ぐらいまで減になるというところだったと記憶しています。","id":"exchange-019"},{"speaker":"須貝委員","kind":"質問・要望","question":"私はそれなりに増員していい時期に来ていると思いますので、今後とも、そのようなことも検討して進めてほしいと求めました。意見だけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"吉田委員","kind":"質問・要望","question":"繰り返しの質問になってしまうかもしれませんが、児童センターの職員が、その辺をもう１回教えてほしいと求めました。その辺、現場からの声がどのように反映されているのか、伺いたいと思います。","respondent":"崎村人事課長","answer":"保育士につきましては、説明が足りずに申し訳ございません。これまでも説明してきたとおり、子どもたちに対して特に影響がある、先生方の業務に影響があるということではないのかなと認識しています。","id":"exchange-021"},{"speaker":"吉田委員","kind":"質問","question":"それから先ほど聞き忘れたのですけれども、それによって見守りが目的というようにこの間伺ったように思うのですが、それはどのような方が担うのか。来ていなかったら、私はその所管のほうの問題かなと思うのですが、把握していることがあったら説明を求めました。","respondent":"崎村人事課長","answer":"保健センターで実施を来年度予定している見守り、おむつ宅配の部分と伴走型相談支援というところのご質問かと思うのですけれども、増員することについては人事課として了としています。","id":"exchange-022"},{"speaker":"吉田委員","kind":"質問・要望","question":"はその辺の確認をさせてください。お互いの人員をどのように配置するかという話合いの中で、そのようなものは人事課としてはどのように把握されているか、伺いたいと思います。","respondent":"崎村人事課長","answer":"その伴走型支援についても、令和６年度以降、人事課としてもしっかりと受け止めて検討していきたいなと考えています。特に障害者支援課の部分の福祉職というお話ですけれども、あと超短時間就労の検討などについて本格的に進めていくというところもございましたので。","id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"児童センターのところで伺いたいのですけれども、児童センターをどうしていくという、どこかに示されているものがあるのでしょうか。もう１０年くらいは経つわけですけれども、そこの１０年ぐらい経っているところでの、ちょっとその点についても伺いたいと思います。","respondent":"鈴木（真）委員長、崎村人事課長","answer":"前段の部分や業務委託の部分だと、かなり子ども未来部の所管に関わってくると思うので、その辺は答えられない部分があるかと思うのですが。そういった方針がどこで決められているのかというところなのですけれども、その中で業務委託の拡大についても言及がなされているところです。","id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"文言としては少し出ているのですが、ではこれからどうするのかという、具体的なところは書かれていなかったと思うのです。今回のその１４館で終わりなのか、それとももっと進めていくのか、そのようなところが分かったらとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これからその定数をせめて２３区平均まではもう本当に速やかに持って行っていただきたいなと、ずっと求めてきたのですが、いかがでしょうか。それから、改めて保健センターと保健所の保健師というものは、定数としては何人なのかということを伺いたいと思います。","respondent":"崎村人事課長","answer":"採用を継続していますが、育成というところを考えると、少し考えなければいけないというところで言われているところです。保健予防課、また子ども家庭支援センターや児童相談所などにも、採用についてはこれからも続けていきたいというふうに考えているところです。","id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"でも、５年間で１４名採用しても２３区で２２位というところでは、そのような保健師の体制だったということではないかなと思うのです。保健センターも３保健センターがあるわけですから、ぜひとも１名で終わらせるのではなくて、ぜひこれからも努力をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"大倉委員","kind":"質問","question":"児童センターとか、保育園とか、その他小学校のところは分かったので、ほかのところで。今回から１００になるということで、どのような過程で１００になったのか、理由等があれば説明を求めました。","respondent":"崎村人事課長","answer":"来年度３０人増しているというのは、来年度から定年年齢が１歳引上げになりまして、２年ごとに出てくることになります。当分の間、この定数外の人数について、７０人から１００人に３０人ほど増やさせていただいているです。","id":"exchange-028"},{"speaker":"大倉委員","kind":"質問","question":"そうすると、今後も少しずつ増えていくという理解でいいのですか。定年が上がってくるという意味では、また増えていきながら、全体の数としては増えていくように見えるということでいいのか尋ねました。","respondent":"崎村人事課長","answer":"定年年齢が大体６５歳になります令和１３年度頃までは、人数で定数外として取り扱わせていただければということで出しています。これまでも増員を図ってきたところですし、効率化を図りながらも、毎年度この時期に定数条例として提案させていただければと考えているところです。","id":"exchange-029"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"児童センターとか、保育園とか、やはりこれは区立で直営で、職員にしっかりとやっていただきたいと考えています。退職不補充でどんどん民間になっていますけれども、それもぜひ職員でやるべきだというところが共産党の意見ですので、この定数条例は反対です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"吉田委員","kind":"質問・要望","question":"質問でも言いましたが、おむつ宅配とか、そのようなことも非常にいい事業だと思うのですけれども、やる以上は丁寧にやっていただきたい。全体としての人員は１３名増えていますが、それは児童相談所に関わることが大きいということが確認できました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"}]},{"id":"topic-05","title":"請願・陳情審査","agenda":"請願・陳情審査","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今回の防衛費２倍化、この内容も、ぜひ皆で一致して国に求めていけたらいいなと思っています。ここまで意見を述べさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"吉田委員","kind":"意見","question":"本当に国を守る気があるのだったら、経済対策の中に真っ先に食糧の自給とエネルギーの自給を最優先に政策として掲げるべきだと思っています。本当に、それなくしてどのようにして生きていけるのかなと思いますので、この請願には賛成したいと考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"},{"speaker":"須貝委員","kind":"意見","question":"生きていくために、どのように国は支援するのだということを、今の時点で私は考えるべきだと思います。本当に何とか自分たちの生活を守ってくれということを必死に思っていると思うので、そのような意味合いをもって、私はこの請願には賛成しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"},{"speaker":"せらく委員","kind":"意見","question":"トマホークを購入するとか、日本を守り抜く力が必要だと思いまして、防衛費の増額には反対はできません。意見ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"米軍の先制攻撃に自衛隊が一緒になって参加をしていくというようなことになって、日本からトマホークを打ち込むということになったらどうですか。国民の、社会保障も、それからこのような物価高対策も削って、本当にそのようなところに、軍備に持っていくわけですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"湯澤委員","kind":"質問・要望","question":"引き続き、この国民の生命と生活を守る最善策を国会にてぜひ議論してほしいと求めました。引き続き行ってほしいと求めましたし、その際には、ぜひ政府には国民に分かりやすい丁寧な説明を求めていきたいというふうに考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"つる副委員長","kind":"意見","question":"我が党においては、ここに触れてあえて発言をするのであれば、そうした３文書等にもしっかり目を通して発言されることが必要なのかなと思います。本請願については、趣旨は非常に大切な声だと思いますけれども、不採択としますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-038"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"医療や介護の現場は、もう本当に大変な状況なので、そのようなところにこそお金を使うべきです。ここにこそ税金を使うべきだと思いますので、この請願はぜひとも採択をして、国に求めていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"大倉委員","kind":"質問・要望","question":"本日結論を出すということで、不採択でお願いしたいと思います。ご意見をいただいた中で、品川区議会として意見書等を国に提出していくということは難しいというところで、不採択とさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"吉田委員","kind":"意見","question":"日本は結構、第２次世界大戦のときからも、エネルギーや食料について軽く見るというような傾向があったのかなと思います。そちらの食料とエネルギーの自給というものはまず最低限目指さないと、この請願については採択でお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-041"},{"speaker":"須貝委員","kind":"意見","question":"先ほども申し上げましたが、本日この請願に関しては、結論を出すということでお願いしたいと思います。この３年、国家は国民のことを考えるならば、今回この請願に関しては採択でお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-042"}]},{"id":"topic-06","title":"令和５年請願第３号、「消費税インボイス（適格請求書）実施中止を求める意見書」を国へ提出を求める請願","agenda":"令和５年請願第３号、「消費税インボイス（適格請求書）実施中止を求める意見書」を国へ提出を求める請願","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"前のときに、１０月３１日でしたでしょうか、この総務委員会に、この請願と同じインボイスの中止と消費税の減税を求める請願が出されたと思うのです。この委員同士の議論というだけではなくて、ぜひそのようにやっていただきたいなと思うのですけれども、その点はどうか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"区民がどれほど大変な状況になるのかというようなことになっていくわけですから、特に、そのようなことというのもいろいろ発生してくるのです。シルバー人材センターのことをどうするのかなどということもあるわけではないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"鈴木（真）委員長","kind":"質問","question":"表現は悪いけれども、全然話がかみ合わないというか、質問していても区としては答えられない部分を質問なさっている状況がありました。ですから、その観点から、理事者をお呼びしないで委員間の討議ということにしています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"いよいよ今年の１０月からインボイス制度が実施されるというようなところになってくるわけですから、そのような点では。今後の付託のときには、そのようなことも踏まえた上で、ぜひご検討いただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"吉田委員","kind":"質問・要望","question":"請願の最後の１行に「税制で商売をつぶすな」ということですが、結果として地域の人的な資源である市民事業を潰すことになりかねません。再考を求めたいなと考えていますので、品川・生活者ネットワークとしても、この請願については賛成したいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"須貝委員","kind":"質問・要望","question":"それなりにどう考えているのか、この中止を求める請願に関しては、私はそこまで求めるというのは違うのかなと考えています。一応意見だけ言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"はインボイス導入で新たに納税業者になる事業者の平均年間課税売上げというものは５５０万円で、粗利益は１５４万円だというのです。取りあえず意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"湯澤委員","kind":"質問・要望","question":"引き続き国において審議を進めていただきたいと考えていますし、制度が始まる前、そういったものの実施はお願いしていきたいと思います。請願については、不採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"つる副委員長","kind":"意見","question":"消費税が導入された１９８９年のときに本来は導入されてしかるべきというものの中で、３４年経って今年の１０月、消費税という。このインボイス制度は非常に重要な、大切なものだという認識でおりますので、本請願については不採択ということですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-051"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"インボイスは中止、消費税減税こそすべきです。ということで、意見書もぜひ出していきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-052"},{"speaker":"大倉委員","kind":"質問・要望","question":"今聞いている声としては、この点はしっかり、この後制度が導入される際には対応していっていただきたいなと思っているところであります。消費税についての、認識をしているところでありますので、この請願については不採択でお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"吉田委員","kind":"意見","question":"これだったら、もう１,０００万円を超えないようにしようよというような感じで気持ちは働いてしまいかねない。ぜひこの請願については採択して、意見書も提出したいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-054"},{"speaker":"須貝委員","kind":"質問・要望","question":"再度免税事業者への配慮、そして増税にならないように、そして事務量を減らしていくように、国にはもっと考えてほしいと求めました。まだまだ施行されていないわけですから、私は国へ何とか、大きな変換、改定をしていただけるとありがたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"せらく委員","kind":"意見","question":"今年の１０月から始まるということで、区として専門家の力を借りてのサポートなどがあってもよいのかなというふうに考えています。インボイス制度に対しては、消費税の公平を期すためにも、適切に申告するべきだと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-056"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/246119?Template=document&Id=2260#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":46480,"voices":158}},{"id":"r05-20230228-6","meetingId":"r05-cm02","date":"2023年2月28日","dateIso":"2023-02-28","committee":"区民委員会","time":"午前１０時００分～午前１１時１９分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を27件整理しています。","topics":[{"id":"topic-01","title":"令和４年度、マンション管理組合等実態調査報告書","agenda":"令和４年度、マンション管理組合等実態調査報告書","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"区分所有者ではなくて、２０８棟の分譲マンションを選び出したという認識でよろしいのでしょうか。ですから、築４０年のマンションですけれども、以上２点をお伺いしておきます。","respondent":"川島地域活動課長","answer":"少し漏れ等もあるかもしれませんが、ほぼ網羅しているデータと考えています。今回管理組合としての加入となっている部分に、今回の質問ではそこを聞いているところではございませんので、よろしくお願いいたします。","id":"exchange-001"},{"speaker":"おくの委員","kind":"質問・要望","question":"あるのだとしたら、それはなぜなのかというか、どういったものなのでしょうか。ほかでも伺ったように思うのですけれども、今どのぐらいなのか、どういう傾向にあるのかということをお伺いしておきたいと思います。","respondent":"川島地域活動課長","answer":"支援を進めてきたところです。これがここ数年６割を少し切るぐらい、６割を切る程度、６割前後で推移ということで、ほぼ横ばいの状態で来ているところです。","id":"exchange-002"},{"speaker":"おくの委員","kind":"質問","question":"当初は加入していたけれども、後で脱退になるというケースがそれなりにあるということなのですが、それはなぜなのか尋ねました。","respondent":"川島地域活動課長","answer":"管理組合の総会で、まとめて加入というのはおかしいという意見があるということで、否決になる場合が多いと聞いております。","id":"exchange-003"},{"speaker":"おくの委員","kind":"質問・要望","question":"区としては町会の要望もあって、どういう対策、どういうふうにしていったらいいかということを考えていらっしゃるのでしょうか。まとめておっしゃっていただければありがたいのですが、いかがでしょう。","respondent":"川島地域活動課長","answer":"本当に１棟まとめて入るというのは、条例に定める町会・自治会というのは、ぜひ加入してくださいというお話をするということ。やっていただけるような部分というのを、当然共有するような形で考えておりますので、進めていく必要があるのかなと思ってあります。","id":"exchange-004"},{"speaker":"おくの委員","kind":"質問・要望","question":"ですから、町会と管理組合、あるいはマンション居住者との接触の機会、話し合いの機会というのはなるべく自然な形でつくってほしいと求めました。ウィン・ウィンなのだよというのが実際にはあるわけですから、区の方は両方とも知っているはずですから、いかがか尋ねました。","respondent":"川島地域活動課長","answer":"町会にとっても、マンションにとっても、いろいろな担い手の方も参加してくれると思います。よく聞く話ですと、今後も、今おっしゃられた町会とマンションの住民がウィン・ウィンの関係になるような支援を続けていきたいと考えています。","id":"exchange-005"},{"speaker":"おくの委員","kind":"質問・要望","question":"これは１００戸以上のマンションということでしたけれども、そういうマンションが多いわけですから、やってほしいと求めました。そういうふうに広げていってほしいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"藤原委員","kind":"意見","question":"回答率が２２.６％ということで、４分の１しか回答されていないということなのですけれども、これについてはどう思いますかとの意見を述べました。","respondent":"川島地域活動課長","answer":"そちらでも回答率が２５.１％だったということで、私どもももっと回答していただけるように努めたところではありますが、回答率の低さというのは。","id":"exchange-007"},{"speaker":"藤原委員","kind":"質問","question":"こうやってアンケートをして出ているわけですから、どうなってここ、回答を考えていくのか。多分２２.６％の回答の中でこれが多かったから、町会に入ればこういうふうにできますよと、その辺はどういうふうに対策していくのか教えてほしい。","respondent":"川島地域活動課長","answer":"地域との交流ということで、イベント等だけではなくて、いろいろな交流が進んでいく。町会独自で簡単に課題が解決するわけではないのですけれども、そういった部分も考慮しながら、支援策を進めていく必要があると思ってあります。","id":"exchange-008"},{"speaker":"藤原委員","kind":"質問・要望","question":"そして今、品川区の重要施策だと私は思うのですけれども、福祉で重層的というのをやっているではないですか。情報は、もう少し具体的な政策をしていっていただきたいと思うのですけれども、その辺についてはいかがか尋ねました。","respondent":"川島地域活動課長","answer":"私のほうで答弁しています防災訓練の共同実施とかという話もございまして、報告書の情報提供をして、しっかり施策として連携できる部分は連携してやっていきたいと思ってあります。","id":"exchange-009"},{"speaker":"本多委員","kind":"質問・要望","question":"高齢者はその一つだけれども、何かあったときには助けてもらいたいとか、必ず要望があると思うのです。町会が推薦しての民生委員、そこに助けを求める等々、本当に関連性がすごくあると思うのです。","respondent":"川島地域活動課長","answer":"こういった実態を知っていただく必要があると考えていますので、それから何か連携してできる部分があれば、そちらも進めていくような検討も進めていきたいです。","id":"exchange-010"},{"speaker":"松本委員","kind":"質問","question":"今の話を伺っていても、今のご答弁を聞いていても、何があるのかなというのがなかなか見えてこない。マンションに住んでいる１人の人間としてなかなか想像できないのですけれども、そこの部分を、そこはどうなのか尋ねました。","respondent":"川島地域活動課長","answer":"地域の人たちと顔見知りになることで、災害時等、いざというときに助け合いがスムーズに進みますというようなことを一応うたっております。","id":"exchange-011"},{"speaker":"松本委員","kind":"質問・要望","question":"その前に１個伺っていきたいのが、恐らく今の品川区の方針って、災害が起こったときも避難所はそんなにお勧めされていない。なので、その辺りは部門間のやり取りとか、これからこういうふうに進めていきましょうというふうな方針は何かあるのか尋ねました。","respondent":"川島地域活動課長","answer":"そこが１つの肝の部分であるというのは私どもも認識しておりまして、あわせてもっとそういう支援が区でいろいろできるのではないかということもあるので、検討していきたいと考えています。","id":"exchange-012"},{"speaker":"松本委員","kind":"提案","question":"区のほうからマンション側に提案とかというのは、まさに横断的に取り組んでいただきたいのですけれども、一緒に防災訓練をやりませんかと。そういうふうなことというのはこれまでやったことがあるのか、あるいはこれからやられるのか、お願いいたしますとの意見を述べました。","respondent":"川島地域活動課長","answer":"関係が円滑に進む１つの肝の部分だと私どもも考えておりますので、そういった部分からも後押しというか、支援をしっかりしていきたいと思ってあります。","id":"exchange-013"},{"speaker":"松本委員","kind":"質問・要望","question":"質問はもう以上にして、今のところをやはり進めていただきたいなと思うところで、ぜひそこをお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"塚本委員","kind":"質問・要望","question":"そんな中でもそういうものを求めている人が地域の話し合いとか、行政としては公平性みたいなことを常に問われる中で、難しいかもしれないのですね。そこは少しプライオリティをつけてやっていくほうが、きっと結果的には実績が上がるのではないかと思うのですけれども、その点はいかがか尋ねました。","respondent":"川島地域活動課長","answer":"もう８割以上になっていまして、避けては通れない話だと考えていますので、しっかりポイントを絞って施策のほうを行っていく必要があると思います。支援するのかというところ、共同でのイベントの実施ですとか、そういったところから始めていければと思ってあります。","id":"exchange-015"},{"speaker":"塚本委員","kind":"質問","question":"地域のコミュニティをどうするのだという話は避けて通れない話、住んでいる人も否応なく、そういうのは行政の課題として出てくるかもしれないです。加入しなければ駄目よという、町会側とか地域側がどう考えていかなければいけないか、そういった点での今のご見解を最後に伺いたい。","respondent":"川島地域活動課長","answer":"今後区として何ができるのかというところも、なかなか簡単ではございませんが、しっかりポイントを絞って支援をしていきたいと考えています。","id":"exchange-016"},{"speaker":"小芝副委員長","kind":"質問","question":"なかなか行きづらい、訪問しづらいという声も聞いておりますので、何かその辺りの考えを教えてもらえますか。そういう方向性があるかどうか。","respondent":"川島地域活動課長","answer":"うまくいった事例等をしっかり情報共有しまして、全ての町会長に知っていただいて、手法を活用できるようにという形で私どももお手伝いしていきたいと思ってあります。","id":"exchange-017"},{"speaker":"小芝副委員長","kind":"質問・要望","question":"その辺りは地域活動課としても、どこに偏ることはなく、ぜひ広めていってもらいたいなと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"中塚委員長","kind":"質問・要望","question":"私も１点伺いたいのですけれども、議論がありましたけれども、区役所の各部や各課との横の連携が必要なのかなと聞いていて思いました。様々に広がってくると思いますので、区役所の中でもぜひ横の連携をしっかり構築していただきたいと思うのですが、その点はいかがか尋ねました。","respondent":"川島地域活動課長","answer":"お話にありました町会・自治会支援というのを、きちんと情報提供しまして、活用して今後の施策に活かせるようにしていきたいと考えています。","id":"exchange-019"}]},{"id":"topic-02","title":"八潮みらい懇談会の進捗状況","agenda":"八潮みらい懇談会の進捗状況","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"４回目はこれからでしょうかという単純な質問がまず１つと、子育て世代、若い世代が参加しやすい団体活動になるとよいという意見が出ています。検討内容や議論の内容によっては、そこら辺を区はどう考えているのかというのが３点目としてお伺いしたいのですけれども、いかがでしょう。","respondent":"中西八潮まちづくり担当課長","answer":"２点目と３点目をあわせてのご回答になりますが、希望者をというところで、まずはそこから今始めているところです。将来的に議論が進む中では、公募とかそういった部分、住民アンケートも含めて検討はしてまいりたいと考えています。","id":"exchange-020"},{"speaker":"おくの委員","kind":"質問・要望","question":"この八潮みらい懇談会は、八潮地区とあるのですけれども、この地区というのは八潮団地外も含んでいるのでしょうかというご質問をいただいたのです。年齢バランスの取れたまちづくりをすべきだと思いますけれども、そこら辺はどういうふうに考えているのかということをお伺いしたいと思います。","respondent":"中西八潮まちづくり担当課長","answer":"八潮みらい懇談会の検討のエリア的なところになるのですが、特にエリアというものを区切って今考えているところではございません。八潮にお住まいの方々が八潮で生き生きと過ごしていただけるためにどうしていったらいいかというところで検討していますので、団地内だけとか。","id":"exchange-021"},{"speaker":"おくの委員","kind":"質問","question":"地区にこだわっていないということから、逆に言えば、要するに団地には限っていない。そうすると、場合によっては、新駅やそれに伴う開発計画というのが視野に入ってくることもあり得るというふうな理解でいいのか尋ねました。","respondent":"中西八潮まちづくり担当課長","answer":"今、皆様と議論している中では、やはりソフト面の中でこの団体をどうしていこうか、八潮の皆さんが元気に過ごしていくにはどうしたらいいかというところでご議論いただいておりますので、まずはそういったところから進めていきたいと思ってあります。","id":"exchange-022"},{"speaker":"おくの委員","kind":"質問","question":"温水供給で、八潮のまち全体の構造のリニューアルも検討する必要があると思っているのだと伺ったのですが、この辺りのことはいかがなのでしょうか。それも伺っておきたいと思います。","respondent":"中西八潮まちづくり担当課長","answer":"視察に行ってみて、いい例があるかというのは、これからもまた提供していきたいと考えています。高齢者と防災と地域行事というところで１回やらせていただきましたので、そういった中で少し議論が出てくるかなと思ってあります。","id":"exchange-023"},{"speaker":"おくの委員","kind":"質問・要望","question":"かなり財布に響いてくるというか、暮らしに響いてくる深刻な問題みたいなので、しっかり答えてあげてほしいと求めました。よろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"藤原委員","kind":"質問・要望","question":"なぜすばらしいと思うかというと、品川区の中でもいろいろな地域があって、そこの地域にいらっしゃる方の要望というのはやはりあると思うのです。その辺については、まずいかがか尋ねました。","respondent":"中西八潮まちづくり担当課長","answer":"前回もご報告申し上げましたが、私は八潮地域センター所長も兼ねてありますので、実際によく地域の方がいらっしゃって、ご要望も頂戴しております。","id":"exchange-025"},{"speaker":"藤原委員","kind":"質問・要望","question":"課が違うかもしれないけれども、そうすると、さっきから話に出ている縦割り行政になってしまうではないですか。その辺についても、いかがか尋ねました。","respondent":"中西八潮まちづくり担当課長","answer":"お互いにどういう取組をしていくかというところは、これから交流しながら、お互いに研究をしていかなければならないテーマかなと考えています。私のほうでも勉強しますし、所管のほうともきちっと連絡・連携を取りながら、私のほうもやっていきたいと考えています。","id":"exchange-026"},{"speaker":"藤原委員","kind":"質問・要望","question":"私たち議員の仕事でもあるけれども、これから課長が背負っていく大きな仕事の一つだと思っているので、その辺の思いを改めてお伺いしたいと思います。","respondent":"中西八潮まちづくり担当課長","answer":"本当に様々な地域の方とお話しする機会をいただいておりますので、そういった思いをきちっと地域センターのほうで受け止めながら、行政とつないでまいりたいと思います。","id":"exchange-027"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/753456?Template=document&Id=2954#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":27044,"voices":76}},{"id":"r05-20230228-7","meetingId":"r05-cm02","date":"2023年2月28日","dateIso":"2023-02-28","committee":"厚生委員会","time":"午前１０時００分～午前１１時５８分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を33件整理しています。","topics":[{"id":"topic-01","title":"地域福祉計画改定に伴う区民アンケート調査結果報告","agenda":"地域福祉計画改定に伴う区民アンケート調査結果報告","exchanges":[{"speaker":"石田委員","kind":"質問・要望","question":"７月にアンケートを行いますというご報告をいただきまして、その時も伺ったのですが、伺いたいです。こちらメンバーについても前回はお答えいただけなかったのですが、分かれば教えてほしいと求めました。","respondent":"寺嶋福祉計画課長","answer":"在宅介護支援センターの職員、障害分野では地域拠点相談支援センターの職員、こういった直接支援をされている方へのアンケートということで。来年度の設置ということになるのですけれども、策定委員会を設置するということで、今の段階では想定しております。","id":"exchange-001"},{"speaker":"石田委員","kind":"質問・要望","question":"分かりました。障害当事者等を入れてほしいという要望をいただいているのですが、もしいないのであれば入れてほしいと求めましたけれども、いかがか尋ねました。","respondent":"寺嶋福祉計画課長","answer":"そういった意味で無作為抽出のアンケートを実施するとか、パブリックコメントを行うということで、意見はお聞きできるような形をとっております。ただ、こちらから特に障害がある方というカテゴリーでお呼びしているとか、そういうことではございません。","id":"exchange-002"},{"speaker":"石田委員","kind":"確認","question":"このアンケートを今回とっていただいて、来年度、策定委員会が開かれていって、パブリックコメントはする予定とか、毎回やっていましたか。確認でお願いします。","respondent":"寺嶋福祉計画課長","answer":"前回の改定時も行いまして、今回も実施を予定しています。","id":"exchange-003"},{"speaker":"いながき委員","kind":"質問・要望","question":"というのはやはり、今後の課題とは思うのですけれども、より多くの方に広報、周知していただきたいと。その辺りをより強く、やっていただきたいと思うのですけれど、その辺りのことはいかがか尋ねました。","respondent":"寺嶋福祉計画課長","answer":"先ほどの説明の中で触れましたが、相談先が分からないという方が１６％以上いたということは、大変残念なことだと捉えております。で在宅介護支援センターを知っているという方が半数以上いたということで、策定委員会の中でご議論を交わしていただけたらと考えています。","id":"exchange-004"},{"speaker":"いながき委員","kind":"質問・要望","question":"そういう場所がここにありますというのを、ぜひとも広く広報していただきたいし、内容も充実してほしいと求めました。その辺り、いかがか尋ねました。","respondent":"寺嶋福祉計画課長","answer":"それが地域包括支援センターが望ましいのかどうかというのは、在宅介護支援センター、地域包括支援センターを運営しているという強みがありますので。","id":"exchange-005"},{"speaker":"いながき委員","kind":"質問・要望","question":"そこに直接行ける方ばかりではないので、そういった形での地域包括支援センターになってほしいし、充実していってほしい。その点はいかがか尋ねました。","respondent":"寺嶋福祉計画課長","answer":"現在品川区で進めております重層的支援体制整備事業の中で、まず今年度の課題というか検討事項になっていまして、いわゆるモデルケース。","id":"exchange-006"},{"speaker":"いながき委員","kind":"質問・要望","question":"ぜひ区民にとって一番分かりやすく、より充実したものになってほしいと思います。本当にこのアンケートはよかったと思いますので、施策に反映してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"高橋（し）委員","kind":"確認","question":"３ページの問２、２０～２９歳、ｎ＝１３１というのが回答数ということでよろしいのでしょうか。その確認です。","respondent":"寺嶋福祉計画課長","answer":"１点目、ｎの合計が１,９１０なので、それぞれの回答、いわゆる実数がこの数字というところは、おっしゃるとおりです。ウェブ回答等、なるべく回答しやすいような方法も導入して、進めているところです。","id":"exchange-008"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"この委員会なのか、また別の機会でも、教えていただけるとありがたいです。これは要望で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"}]},{"id":"topic-02","title":"（仮称）小山七丁目障害者グループホームの事業者公募","agenda":"（仮称）小山七丁目障害者グループホームの事業者公募","exchanges":[{"speaker":"石田委員","kind":"質問・要望","question":"この公募について、区のホームページで周知されると思うのですけれど、それ以外の周知方法は何かされるのでしょうか。今回、していただきたいと思うのですけれども、いかがか尋ねました。","respondent":"川崎障害者施策推進課長","answer":"今回は民間で整備して運営していく形になりますので、民間で整備すると都の補助金、そして品川区独自の補助金も使えます。民間の活力を使っての整備になりますので、補助金の周知も含めて広く周知していく、そのような予定になっております。","id":"exchange-010"},{"speaker":"石田委員","kind":"質問","question":"広く周知というのが、直接法人に、お手紙を出すとか、メールを出すとか、そういう当たり方になるのか、ホームページという形になってしまうのか、そこを伺いたいと思います。","respondent":"川崎障害者施策推進課長","answer":"すみません。方法が漏れていたのですけれども、今回、郵送またファクスも含めて、周知をする予定です。","id":"exchange-011"},{"speaker":"石田委員","kind":"質問・要望","question":"昨日も伺った中で、言えない整備状況というか、そういうふうに考えられているのか。重度の方の受入れについて、この小山七丁目のグループホームではどう考えられているのか、説明を求めました。","respondent":"川崎障害者施策推進課長","answer":"小山七丁目につきましても、中重度の方を受け入れていく想定ではありますが、具体的にはこれから公募、運営していく運営事業者との協議の上、決定してまいります。","id":"exchange-012"},{"speaker":"石田委員","kind":"質問・要望","question":"ぜひ公募の際にも、多分言わなくてもされると思うのですけれど、中重度の方も受け入れられるような法人が手を挙げてもらえるような、形にしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"いながき委員","kind":"質問・要望","question":"例えば先ほど中度から重度の方を受け入れる施設にしてほしいという要望となるのか、そういった整備の中身に関して、あるのですか。できれば重度の方を優先的にとか、そういった話とか、どういうようなものか教えていただけますか。","respondent":"川崎障害者施策推進課長","answer":"公募開始が４月になるのですけれども、実施要領ですね、そちらをホームページを通じて周知します。当然、説明会も行いますので、小山七丁目障害者グループホームの中身について、ご説明という形で運営事業者を希望される方にはご説明してまいります。","id":"exchange-014"},{"speaker":"いながき委員","kind":"質問","question":"思い出したのが、旗の台の方の声だったのですけれど、こういった施設が建つことを知らなかったと。説明会も、開かれたのかよく分からないんだよねというお話も聞いたので、近隣の方への説明会というのは既にあったのか、説明を求めました。","respondent":"川崎障害者施策推進課長","answer":"この小山七丁目障害者グループホームにつきましては４回、住民説明会を行いました。最初の説明会は令和４年３月、その後、７月、９月、そして令和５年１月と４回、丁寧にご説明はさせていただきました。","id":"exchange-015"},{"speaker":"あくつ副委員長","kind":"質問","question":"今おっしゃられた連携というのは、日常生活の上での連携と拝聴したのですけれど、いわゆる老後というか、グループホームで自立して生活をされている方たちが、小規模多機能が隣にあるということで、そういう意味での連携かと私は思ったのですけれど、そういうことではないのか尋ねました。","respondent":"川崎障害者施策推進課長","answer":"なので、まずは本当にご近所付き合いという、日常生活での連携というものが第一かと思っています。そこから発展していって、どのような形で高齢者、障害者との連携ができるかというのは、本当に今後になるかなと考えています。","id":"exchange-016"},{"speaker":"あくつ副委員長","kind":"質問","question":"先ほど１回目のご答弁の中で、小山の家、小山倶楽部を運営されている事業者は、障害者の施設の運営をされていないというお話がありましたが、公募のご案内はされるのか尋ねました。","respondent":"松山障害者支援課長","answer":"三徳会につきましては障害者の方の相談支援事業所を、荏原のほうで運営はしております。同じ福祉施設同士、情報共有あるいは勉強会とかもするようなことが想定されるのではないか、と考えております。","id":"exchange-017"}]},{"id":"topic-03","title":"品川区立西大井つばさの家の定員変更","agenda":"品川区立西大井つばさの家の定員変更","exchanges":[{"speaker":"石田委員","kind":"質問","question":"この定員変更で、それぞれ増えるということで、グループホームは区内に少ないので、居室が増えることはいいなと思ったのですが、同じスペースの中で増やすわけですから、何に使われていたスペースを居室や浴室、トイレにしていくのかというのを伺いたいと思います。","respondent":"松山障害者支援課長","answer":"面積は約３００平米ということで、変更はございません。現在は倉庫として使用していたスペースを減らしたです。","id":"exchange-018"},{"speaker":"石田委員","kind":"質問・要望","question":"問題ないように進めているとは思うのですけれども、どこをどう使われるのか疑問だったので、伺いました。もう一度確認させていただきたいのと、何度も質問して申し訳ないのですけれど、重度の方にも情報が行くのかということを伺いたいと思います。","respondent":"松山障害者支援課長","answer":"昨日ご説明しましたとおり、相談支援事業所を通じて皆様に周知をしているということと、知的障害者団体にも既に周知をしております。受付ですが、３月１０日まで受付をしているという状況で、入居候補者選定会議は３月１７日に開催する予定となっております。","id":"exchange-019"},{"speaker":"いながき委員","kind":"質問","question":"男女比というのはどういうふうになっているのかというのと、サポートされる人も増えるのかどうなのかということも伺いたいです。以上、何点か教えていただけますか。","respondent":"松山障害者支援課長","answer":"工事終了後は東京都が確認をして、５月１日に変更するという段取りを今、整えているところです。委員おっしゃるとおり、障害の場合は同性介護になりますので、入られる方によっての人員体制を確保しなければならないということになっております。","id":"exchange-020"},{"speaker":"いながき委員","kind":"確認","question":"ありがとうございました。その名簿管理をされている方たちには優先的にお知らせが行ったりとか、という感じだったのかなというのを確認だけさせてください。","respondent":"松山障害者支援課長","answer":"は相談員からお声かけをさせていただいているということになります。今年度４名という空きが生じるという形になりますから、そういう方から、恐らく情報を伝えさせていただいているかと考えています。","id":"exchange-021"}]},{"id":"topic-04","title":"国保財政健全化計画","agenda":"国保財政健全化計画","exchanges":[{"speaker":"石田委員","kind":"確認","question":"この繰入金の削減を目的としているわけですから、４の赤字削減額、これがゼロになると望ましいということを東京都は言っているということなのか。そこを、いつも聞いても分からないのですけれど、改めて伺いたいと思います。","respondent":"池田国保医療年金課長","answer":"こちらを６年間で削減するのは大変難しいということで、計画の見直しなどを行わない限りは、なかなかゼロにはならないかと考えているところです。","id":"exchange-022"},{"speaker":"石田委員","kind":"質問・要望","question":"決算補填等を目的とした繰入金に保険料の軽減は当たらないとされていますので、そこは引き続き、保険料の軽減に向けて検討はしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"いながき委員","kind":"質問","question":"何をやっているのかというのを、ごめんなさい、簡単に説明をしていただいてもいいですか。この辺、本当によく分かっていなくて申し訳ないのですけれども。","respondent":"池田国保医療年金課長","answer":"決算補填等を目的としたというところでは、確かに保険料の収納が不足しているというところで、補填で持ってきているというようなものがあります。","id":"exchange-024"},{"speaker":"いながき委員","kind":"質問","question":"でも、できればこれもなくしていきたい、みたいな。この段階ですみたいなもの、ロードマップといいますか、本当に素人に分かりやすく教えていただけるとうれしいのですが。","respondent":"池田国保医療年金課長","answer":"説明が分かりづらくて大変申し訳ありません。当然保険料は医療費の部分と比例して上がってまいりますので、健全な財政を目指していくという、そういうことが内容になっています。","id":"exchange-025"},{"speaker":"いながき委員","kind":"確認","question":"確認なのですが、収納率を高めていくという理解でいいのか、という確認が一つと。その２点を説明を求めました。","respondent":"池田国保医療年金課長","answer":"もし不都合な、間違いがありましたら、もしくは逆の場合は追加支給というようなことをやるのが二次点検とご理解いただければと思います。それと最初のご質問、先ほどの目的と内容等については、そのご認識で大丈夫です。","id":"exchange-026"},{"speaker":"いながき委員","kind":"確認","question":"ありがとうございました。柔道整復師の場合、長くなっていると内容が適当かどうかというような疑問が出てくるのかなと思ったので、１点確認して終わりにしたいと思います。","respondent":"池田国保医療年金課長","answer":"長い期間であると、そういったことがあるかということでの確認という形です。","id":"exchange-027"}]},{"id":"topic-05","title":"品川区における新型コロナウイルス感染症対策","agenda":"品川区における新型コロナウイルス感染症対策","exchanges":[{"speaker":"石田委員","kind":"質問・要望","question":"区としてはどういうアドバイスではないですが、診療所や現場にお任せしますという形になっているのか、そこを伺いたいのと。打つ方が減っているのでというところでは理解できるのですが、個別接種会場という各病院ではどうなっているのか、伺いたいと思います。","respondent":"坂野保健予防課長、豊嶋新型コロナウイルス予防接種担当課長","answer":"マスクのお話なのですけれども、医療機関の中と限定して考えれば、多分コロナの前から普通にマスクをしているのですよね。リスクが非常に高い病棟と、そこまで高くないところと当然ありますので… 個別接種会場であるクリニック等では、現在も接種ができます。引き続き４月以降もできるように医師会と調整しております。","id":"exchange-028"},{"speaker":"石田委員","kind":"質問","question":"介護の現場でも、ヘルパーに入る場合だったり、おうちの方はマスクをしてくださいとなっていくのかという問合せなどは、来ていないという状況ですか。もしそれが来た場合、現場、機関に委ねるとなっていくのでしょうか、ということをお願いします。","respondent":"坂野保健予防課長","answer":"なかなかうまくお話ができませんで、申し訳ありません。個別の医療機関によるコンディションの違いというのは非常に吸収し難いものがあるので、なかなか一律にお示しするのは難しいのかなと。","id":"exchange-029"},{"speaker":"石田委員","kind":"質問・要望","question":"もう院内でされているというお話も伺ったので、ぜひ検討していただきたいですし、運営の支援というのを行っていただきたいと思っています。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"いながき委員","kind":"意見","question":"決まった後、広報はどのような感じになるのかというのをお尋ねしたいのと。２番の今後の集団接種会場についての考え方の２つ目のポツで、そういったところのケアはどのようにしていただいているのか、というのがお尋ねですとの意見を述べました。","respondent":"坂野保健予防課長、豊嶋新型コロナウイルス予防接種担当課長","answer":"ですから、区としてというよりも、東京都とかの広域的な方針を、着実に実行する。ということがありますので、あまり区としてローカライズされたやり方というのは、かえって混乱を招くのかなと考えております。保健センターでは、昨年３月から小児接種が始まった以降、保健センターでも集団接種会場として、今まで接種体制を整えてまいりました。","id":"exchange-031"},{"speaker":"いながき委員","kind":"質問・要望","question":"すごく私はいいなと思ったのが、ニュースとかにも取り上げられて、品川区は先進的だねというお話も伺っていたのです。今後も充実していってほしいという思いなので、今後も続けていってほしいというところなので、その点についてはいかがか尋ねました。","respondent":"坂野保健予防課長","answer":"もう３年になりますので、区としては二人三脚でこの先もやっていこうと考えていますので、よろしくお願いいたします。","id":"exchange-032"},{"speaker":"いながき委員","kind":"質問・要望","question":"ぜひともそれは続けていってほしいと思います。広報は徹底していただきたいなと、広報とかは適宜というか、なるべく早くしていただきたいというお願いです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/651938?Template=document&Id=3656#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":30831,"voices":105}},{"id":"r05-20230228-8","meetingId":"r05-cm02","date":"2023年2月28日","dateIso":"2023-02-28","committee":"建設委員会","time":"午前１０時００分～午後 ０時０７分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を33件整理しています。","topics":[{"id":"topic-01","title":"品川区まちづくりマスタープラン改定に向けた検討状況","agenda":"品川区まちづくりマスタープラン改定に向けた検討状況","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"第６回品川区まちづくりマスタープラン改定委員会が行われたということですので、どういった質疑が行われたのか伺いたいと思います。それと、学生とのワークショップも行ったということで、そのワークショップの中で、どういった意見が出たのかも伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"改定されたマスタープランを自分の地区に持ち帰り具体的な検討を進めていきたいですとか、魅力あるまちづくりを進めていきたい。子ども・若者まちづくり委員会を設置し、募集をどういう形にするかは今後検討しますが、成果評価を行っていきたいというものです。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはり、区民参加がまだまだ弱いのかなと思いますので、そこは強めていくことが必要だと思いますけれども、いかがでしょうか。この間、そういった意見が出てくる背景にもあるのかなと思いますけれども、区の意見を伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"区民の方を無作為抽出しての区民アンケートを実施、あるいは計画が一定まとまってきた段階でオープンハウス型の説明会、これは区内４か所。それは区内で様々進めるまちづくりの個々の計画の中でも、考え方の下、今後もまちづくりを進めていきたいです。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"渋滞解消に向けては力を尽くしていただきたいと思うのですが、変更がないようにしていただきたいと思うのですが、区のお考えを伺いたいと思います。荏原ルート、早期の実施と区民要望に沿った新たなルートも実施をしていってほしいと求めましたが、いかがか尋ねました。","respondent":"溝口土木管理課長、鈴木都市計画課長","answer":"補助２６号線が開通してから、また所轄の警察のほうといろいろ協議いたしまして、今現在はかなり解消されてきているところです。少しでも快適に道路を利用していただけるように今改修を進めているところでございまして… 今試行運行を行っている大井ルート、これは様々な指標に基づいて、より効果的な導入地域ということで今実施しています。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"大井ルートの検証をしてということですけれども、ぜひ早期の実施をしていって、ほかのルートを増やしていってほしいと求めました。やはり、高齢者がフレイルにならないような取組にもなっていると思いますので、そうした福祉的な視点も含めて充実を求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"横山委員","kind":"質問","question":"少しお聞きしたいのですけれども、今回どのような点を工夫して、もし何かありましたらお聞かせください。この参考の資料ですかね、このデータの粒度の変化等も感じているところですが、工夫されているポイントがありましたら説明を求めました。","respondent":"鈴木都市計画課長","answer":"ホームページあるいは広報紙でのお知らせというところは、前回の１０年前のパブリックコメントの実施の仕方から変更点は大きくはないのですが。回数は５回から６回検討委員会を実施してございましたが、その２時間を時間いっぱいご議論いただいて、１０年前とは格段に違うなと。","id":"exchange-005"},{"speaker":"横山委員","kind":"質問・要望","question":"こうしていろいろ１０年間で、様々な手法で、そこからさらに区に関する関心を持っていただいているという様子がすごく分かりました。引き続き、そのような形で丁寧に進めてほしいと求めましたので、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"}]},{"id":"topic-02","title":"しなバスに関するアンケート結果","agenda":"しなバスに関するアンケート結果","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"バス停の位置などの不満が高いということですので、そうしたところも含めて改善をしていっていただきたいと思うのですけれども、いかがでしょうか。自由意見の中でも、運賃やバス停の位置などが改善の要望として高く上がっているということですので、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"恐らくは回答いただいた方のお住まいの近く、そうした方々へは、あるいは方法でお知らせしていく必要があるなというところを実感したところです。","id":"exchange-007"},{"speaker":"のだて委員","kind":"質問・要望","question":"別のルートということになるのか分かりませんけれども、そうしたルートの実施に向けても検討してほしいと求めましたが、いかがでしょうか。それがやはり、区民の利便性向上にもつながると思いますけれども、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"今準備を進めております沿線の利用者連絡会につきましては、これまでの１年間の運行状況なども、ご意見をいただきながら検討を進めてまいりたいです。コミュニティバスの役割という形で認識していますので、これまでの検討経緯も含めて、説明をこれからもしていきたいです。","id":"exchange-008"},{"speaker":"のだて委員","kind":"質問","question":"沿線利用者連絡会を今検討しているというところですが、どういった形になるのかというところを伺いたいのですが、人数とかメンバーの候補などがありましたら説明を求めました。","respondent":"鈴木都市計画課長","answer":"まさに今検討準備を進めているところで、何十人もという形ではなくて、ただ一定メンバーを検討して進めていきたい。開催は適宜進めていきたいと考えていますが、コミュニティバスを今後も愛して育てていっていただけるような会を、長く継続して進めていきたいです。","id":"exchange-009"},{"speaker":"澤田委員","kind":"質問","question":"アンケートですけれども、配布してアンケートを行ったということですけれども、ウェブのほうではやられたのか尋ねました。","respondent":"鈴木都市計画課長","answer":"利用者アンケートにつきましては、直接配布と、それからバス停に設置したものに、ウェブでも回答いただけるような案内を差し上げて、実際ウェブでも回答をいただいているというような状況です。","id":"exchange-010"},{"speaker":"澤田委員","kind":"質問","question":"若い世代の利用率がすごく低いのがとても残念だなと思っていて、若者の利用率を上げるためのお考えなどは何かあるのでしょうか。もしあればお聞かせほしいと求めました。","respondent":"鈴木都市計画課長","answer":"そうした方々の６割近い方が徒歩、４割近い方が自転車というところで、コミュニティバスを利用するようになったと。さらにこれはバス事業者とも今検討中なのですが、掘り起こしにつながるような検討というのは、継続して行っていきたいです。","id":"exchange-011"},{"speaker":"澤田委員","kind":"質問・要望","question":"要望ですけれども、ちぃばすのパスが、無料パスみたいのが１年間とかあるではないですか。そのような取組をすると２０代、３０代の若いママたちが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"いろいろ、他自治体の状況あるいは今回のアンケートの中でも、そうした声をいただいているところです。より広く支援を行っていく、割引を行っていく方については、より幅広く今後も継続して検討を行っていきたいです。","id":"exchange-012"},{"speaker":"横山委員","kind":"質問","question":"この項目についてどういったことを読み取っていけると区がお考えなのか、詳細を教えていただけたらと考えています。(3)利用状況ですけれども、一番下のその他の上から２番目の丸、今後どのように伝えていくのかというところも区のお考えを説明を求めました。","respondent":"鈴木都市計画課長","answer":"そうしたところでしなバスというのを認識していただいて、バス事業者を通じてしているのですが、なかなか今のところは応募がないです。１枚作り込んで、あるいはバス停だけではない、様々なＰＲを今後いろいろ検討して進めていきたいです。","id":"exchange-013"},{"speaker":"横山委員","kind":"質問・要望","question":"(4)の満足度のところですけれども、少し状況だけお聞かせいただきたいのですが、最終便の時間という項目があります。どういった希望なのかというところ、状況、現在どうなっているのかというところをお知らせいただけたらと思います。","respondent":"鈴木都市計画課長","answer":"ご意見としていただいたのは２２時以降、前後で、その辺りまでバスが欲しいです。午後１０時半、こうした声に対応していくかどうか、今後の検討課題になるかと思います。","id":"exchange-014"},{"speaker":"こんの委員","kind":"質問・要望","question":"やや満足も含めると約７０％、約８０％と満足度が非常に高いという、区民の皆さんのご要望が高いというのを感じました。区民の皆さんのご要望が高いというところで、ここを早く試行運転していただきたいという要望がありますけれども、今の進捗状況はどうか尋ねました。","respondent":"鈴木都市計画課長","answer":"そうすると、やはり、乗車定員が限られてくるというようなところと、それから車椅子等の対応ができないというところ。警視庁のほうと継続協議が続けられるかなですので、この大井ルートと一体的に走らせられるように、今鋭意取り組んでいるところです。","id":"exchange-015"},{"speaker":"こんの委員","kind":"質問・要望","question":"いの一番に走っていただきたいこの地域に、引き続き協議を進めていただきながら、引き続きお願いしたいと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"松永委員","kind":"質問","question":"今後品川区として、この料金の値上げをせざるを得ない場合のプロセスは、どういった形で値上げされるのかというのを教えてください。していないのか、少し見ていなかったので分かりませんが、それについてもお伺いいたします。","respondent":"鈴木都市計画課長","answer":"区のほうで設置しています地域公共交通会議にお諮りして、今のところ、バスの運賃を上げるというところは考えていないです。やはり先ほどもご説明したように、区のほうではシルバーパスもご利用いただいているところで、そうしたところで料金体系を考えていきたいです。","id":"exchange-017"},{"speaker":"松永委員","kind":"質問","question":"例えば、そちらの民間会社から２４０円でお願いしたいということを言われた場合に、区としては２２０円でやっていきたいと。これだけ、お伺いしたい。","respondent":"鈴木都市計画課長","answer":"区のほうで、コミュニティバスを今後本格導入するかの判断基準というのを設けておりまして、それが収支率５０％です。区のほうで、バス事業者と当然ながら協議をしながら、どうしていくかということの判断になると思います。","id":"exchange-018"},{"speaker":"芹澤委員","kind":"質問・要望","question":"何点かお伺いします。先ほどクロス集計みたいな話もありましたが、事前に想像していたところの分析というのは、これからやるというイメージなのか尋ねました。","respondent":"鈴木都市計画課長","answer":"複数回答への防止策ですが、先ほどご説明したように、そこにパスワードを設定して複数回答できないような形には。紙ベースでいただいた回答を見ると、皆さん等しく、今回ご回答いただいているのかなというような状況です。","id":"exchange-019"},{"speaker":"芹澤委員","kind":"提案","question":"すみません、３点手短に確認なのですが、収支率５０％というのは、大分前からおっしゃっていただいていたと思うのです。少しぐらい何か免除というか、大目に見るところもあっていいのかなという提案ですとの意見を述べました。","respondent":"鈴木都市計画課長","answer":"情報として、時期は未定ですが、ロータリーの工事を大田区側が行うような予定もあると聞いてあります。整備に合わせて何か新たにバス停を設けられるような位置が確保できないかどうかというのは、継続して、動向を見ながら考えていきたいです。","id":"exchange-020"},{"speaker":"芹澤委員","kind":"質問・要望","question":"今の、もともとの３ルートについて、ぜひ前向きに民間事業者とのお話合いが進めばと考えています。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"西村副委員長","kind":"確認","question":"２点伺わせていただきます。２点目が、ステップを低くしておられたかなと思うのですが、改めて確認をさせてください。","respondent":"鈴木都市計画課長","answer":"１点目のラッピングですとか、先ほどご説明したようになかなかまだ事例としてはご活用いただいていないですが、ご活用いただいている状況です。","id":"exchange-022"}]},{"id":"topic-03","title":"自転車等駐車場におけるキャッシュレス決済の導入等","agenda":"自転車等駐車場におけるキャッシュレス決済の導入等","exchanges":[{"speaker":"こんの委員","kind":"質問","question":"こちらを導入するに当たって、予算はどれぐらいかかっているのでしょうか。どうしても心理が働いてしまうので、そのものを使っていかれるようなことが必要かなと思うのですけれども、いかがか尋ねました。","respondent":"工藤交通安全担当課長","answer":"満空情報を提供して、それでご満足いただけるというものではないと考えております。指導であるとかと併せて対策をとっていきまして、放置自転車の防止を図ってまいりたいと思います。","id":"exchange-023"},{"speaker":"こんの委員","kind":"質問","question":"これは進めていただくというところですが、一方で、放置自転車というのは本当にいたちごっこの状態がまだまだ続いているかなと思います。その取組のもう一歩、何というのでしょうか、踏み込んだ取組などは考えていらっしゃるか尋ねました。","respondent":"工藤交通安全担当課長","answer":"はアイビーメンテナンスのほうにも、指導、警告ということでお願いをしております。あわせて、いろいろな広報媒体を使いまして、放置自転車の防止についてのＰＲ等を図りながら、違法駐輪の防止を図っていきたいと考えております。","id":"exchange-024"},{"speaker":"澤田委員","kind":"質問・要望","question":"今回さらにまた、ウェブで空いているか空いていないかを確認できるというのは、さらに便利になって本当にありがたいなと考えています。このことを知るにはどうしたらいいのかなというか、周知はどのようにされているのかなというのを教えていただきたいのですが、お願いいたします。","respondent":"工藤交通安全担当課長","answer":"こちらの周知についてですが、各駐輪場に貼り出しを行っております。活用した周知ということを行いますので、指導をされている人たちからの口づて、口頭での周知ということも考えてあります。","id":"exchange-025"},{"speaker":"澤田委員","kind":"質問・要望","question":"そういうふうにしていただけたら、より本当に広まって、皆さんがより便利に使えるようになるといいなと考えています。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"横山委員","kind":"質問・要望","question":"そのうちの１９施設が、電磁式駐輪ラック導入自転車等駐車場であるということを確認させていただきたいのですけれども、よろしいでしょうか。１点確認ですが、この自転車という中にどのように表示されるのか、区別というのは分かるものなのかどうなのかというところをお知らせください。","respondent":"工藤交通安全担当課長","answer":"委員ご説明のとおり、これは先ほどご説明したとおり、電磁式ラックが導入されているところに設置可能ですので。２つ目のＷＥＢ ＭＡＰでの情報提供ですが、バイク、収容台数何台のうちの空き状況が何台というような表記です。","id":"exchange-027"},{"speaker":"横山委員","kind":"質問・要望","question":"区のほうでも、平置きのスペース等の整備を進めていただいている中かなと把握しております。もし、そういったところで工夫をしていただきたいなと思っているのですけれども、区のご答弁をお願いできたらと思います。","respondent":"工藤交通安全担当課長","answer":"そちらの補助の表示の件については、検討させていただいて、なるべく分かりやすい表記等に努めたいと考えています。","id":"exchange-028"},{"speaker":"芹澤委員","kind":"提案","question":"今事業者の提案があってというようなお話だったと思うので、今後、そのキャッシュレスの対応事業者が増えていく可能性は一応あるのでしょうか。その確認だけお願いしますとの意見を述べました。","respondent":"工藤交通安全担当課長","answer":"こちらに表記されている１４事業者、今のところ１４事業者ということで、使えるようになってあります。今後増えていくかどうかというところですけれども、そちらについては、今後の活用状況を見まして検討させていただきたいと考えています。","id":"exchange-029"},{"speaker":"芹澤委員","kind":"質問・要望","question":"１４事業者は、多分この資料に書いてあるものを数えると１４事業者なので、非常に使う方が多くいらっしゃるかと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"西村副委員長","kind":"提案","question":"以前提案をさせていただいたことがあるのですけれども、導入してもなかなか効果的に機能しないことがあるというお話も事前に伺っているところです。利便性向上のマーケティングとしてぜひ活用していただきたいなと思うのですが、何かお考えとか、今後の見解があれば説明を求めました。","respondent":"工藤交通安全担当課長","answer":"こちらのほうをやらせていただきまして、どのぐらいの利用率等があるのかというところを確認しまして、その先のことについては、引き続き、あらゆる方面から検討させて活用できればと考えています。","id":"exchange-031"},{"speaker":"澤田委員","kind":"質問","question":"残りの７施設も今後、電磁式駐輪ラックに変わっていくのでしょうか、教えてほしいと求めました。その時期が分かるようでしたら、そちらも併せてお願いいたします。","respondent":"工藤交通安全担当課長","answer":"残りの区営７施設につきましては、現在のところ導入予定はございません。導入していない７か所については定期利用等の場所があるのですけれども、ニーズがあれば、その際に改めて検討させていただきたいと思います。","id":"exchange-032"}]},{"id":"topic-04","title":"目黒川安全航行啓発活動の実施","agenda":"目黒川安全航行啓発活動の実施","exchanges":[{"speaker":"西村副委員長","kind":"質問","question":"１点だけお伺いします。把握されているところで、特に区のほうから呼びかけていきたいことがございましたら、改めて説明を求めました。","respondent":"栗原河川下水道課長","answer":"危ないということがありますので、徐行、ゆっくり走っていただくことをしっかり呼びかけたいと考えています。特に桜の時期になりますと、特にスピードを出さないように、徐行して航行するように呼びかけていきたいと考えております。","id":"exchange-033"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/372951?Template=document&Id=4374#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":38900,"voices":110}}]);
